export enum MaterialType {
  STEEL_C45 = 'C45',
  ALUMINIUM_6061 = 'Alu 6061',
  STAINLESS_304 = 'SS 304',
  BRASS = 'Brass',
  PLASTIC_ABS = 'ABS'
}

export interface Dimensions {
  length: number;
  width: number;
  height: number;
}

export interface CalculationResult {
  volumeMm3: number;
  density: number; // g/cm3
  weightGrams: number;
  materialCost: number;
  totalLineCost: number;
}

export interface LineItem {
  id: string;
  description: string;
  material: MaterialType;
  dimensions: Dimensions;
  quantity: number;
  unit: string;
  tolerance?: string;
  deliveryDate?: string;
  calculation: CalculationResult;
}

export interface RFQHeader {
  customerName: string;
  rfqNumber: string;
  documentDate: string;
  vendorName: string;
  bidCloseDate: string;
  location: string;
}

export interface RFQData {
  header: RFQHeader;
  lineItems: LineItem[];
}

export type ViewMode = 'upload' | 'verify' | 'saved';

import { MaterialType } from './types';

// Density in g/cm^3
export const MATERIAL_DENSITY: Record<MaterialType, number> = {
  [MaterialType.STEEL_C45]: 7.85,
  [MaterialType.ALUMINIUM_6061]: 2.70,
  [MaterialType.STAINLESS_304]: 8.00,
  [MaterialType.BRASS]: 8.73,
  [MaterialType.PLASTIC_ABS]: 1.04,
};

// Base cost per gram in EUR (Mock values for calculation)
export const MATERIAL_COST_PER_GRAM: Record<MaterialType, number> = {
  [MaterialType.STEEL_C45]: 0.0015, // 1.50 EUR / kg
  [MaterialType.ALUMINIUM_6061]: 0.0028,
  [MaterialType.STAINLESS_304]: 0.0045,
  [MaterialType.BRASS]: 0.0060,
  [MaterialType.PLASTIC_ABS]: 0.0008,
};

export const INITIAL_HEADER = {
  customerName: '',
  rfqNumber: '',
  documentDate: new Date().toISOString().split('T')[0],
  vendorName: 'Matree Enterprise (Ven010)',
  bidCloseDate: '',
  location: 'Ad-Electronic City (019028000)'
};

import { LineItem, CalculationResult, Dimensions, MaterialType } from '../types';
import { MATERIAL_DENSITY, MATERIAL_COST_PER_GRAM } from '../constants';

/**
 * Calculates physics-based cost and weight.
 * Deterministic: Same input always returns same output.
 */
export const calculateLineItem = (
  material: MaterialType,
  dimensions: Dimensions,
  quantity: number
): CalculationResult => {
  const density = MATERIAL_DENSITY[material] || 7.85;
  const costPerGram = MATERIAL_COST_PER_GRAM[material] || 0.0015;

  // Volume in mm^3
  const volumeMm3 = dimensions.length * dimensions.width * dimensions.height;

  // Convert Volume to cm^3 for weight calc (1 cm^3 = 1000 mm^3)
  const volumeCm3 = volumeMm3 / 1000;

  // Weight in grams
  const weightGrams = volumeCm3 * density;

  // Material Cost per unit
  const materialCostPerUnit = weightGrams * costPerGram;

  // Total Line Cost
  const totalLineCost = materialCostPerUnit * quantity;

  return {
    volumeMm3,
    density,
    weightGrams,
    materialCost: materialCostPerUnit,
    totalLineCost
  };
};

export const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(amount);
};

export const formatNumber = (num: number, decimals = 2) => {
  return new Intl.NumberFormat('de-DE', { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(num);
};

import { GoogleGenAI, Type } from "@google/genai";
import { MaterialType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const EXTRACT_SYSTEM_INSTRUCTION = `
You are an expert manufacturing cost estimator. 
Extract structured RFQ data from the provided document image.
If specific dimensions or materials are missing, use null.
Identify standard materials from the list: C45, Alu 6061, SS 304, Brass, ABS.
Default to C45 if material is steel but unspecified.
Extract dimensions in millimeters.
`;

export const extractRFQData = async (base64Image: string, mimeType: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: "Extract the customer details, RFQ number, and a list of all line items including dimensions (length, width, height), quantity, and material description.",
          },
        ],
      },
      config: {
        systemInstruction: EXTRACT_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            customerName: { type: Type.STRING },
            rfqNumber: { type: Type.STRING },
            documentDate: { type: Type.STRING },
            lineItems: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  description: { type: Type.STRING },
                  material: { type: Type.STRING },
                  quantity: { type: Type.INTEGER },
                  length: { type: Type.NUMBER },
                  width: { type: Type.NUMBER },
                  height: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  deliveryDate: { type: Type.STRING },
                  tolerance: { type: Type.STRING }
                },
                required: ["description", "quantity", "length", "width", "height"],
              },
            },
          },
          required: ["lineItems"],
        },
      },
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    throw new Error("Failed to extract data from document.");
  }
};

