import React, { useState, useEffect, useCallback } from 'react';
import { Upload, FileText, ArrowLeft, Bot, Save, Download } from 'lucide-react';
import { extractRFQData } from './services/geminiService';
import { calculateLineItem, formatCurrency } from './services/calculationService';
import { RFQData, LineItem, ViewMode, MaterialType } from './types';
import { INITIAL_HEADER } from './constants';
import { LineItemCard } from './components/LineItemCard';
import { SaveQuoteModal } from './components/SaveQuoteModal';

// Helper to convert file to base64
const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('upload');
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [rfqData, setRfqData] = useState<RFQData>({ header: INITIAL_HEADER, lineItems: [] });
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Calculate total whenever line items change
  const totalCost = rfqData.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);

  // --- Handlers ---

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setIsProcessing(true);

      try {
        const base64Data = await fileToBase64(selectedFile);
        const base64Content = base64Data.split(',')[1];

        // Call Gemini
        const extracted = await extractRFQData(base64Content, selectedFile.type);

        // Transform Gemini response to App State
        const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
          const material = Object.values(MaterialType).includes(item.material as MaterialType) 
            ? item.material as MaterialType 
            : MaterialType.STEEL_C45;

          const dims = {
             length: item.length || 0,
             width: item.width || 0,
             height: item.height || 0
          };

          return {
            id: `item-${Date.now()}-${idx}`,
            description: item.description || `Item ${idx + 1}`,
            material,
            quantity: item.quantity || 1,
            unit: item.unit || 'ST',
            dimensions: dims,
            deliveryDate: item.deliveryDate || '',
            tolerance: item.tolerance,
            calculation: calculateLineItem(material, dims, item.quantity || 1)
          };
        });

        setRfqData({
          header: {
            ...INITIAL_HEADER,
            customerName: extracted.customerName || '',
            rfqNumber: extracted.rfqNumber || '',
            documentDate: extracted.documentDate || new Date().toISOString().split('T')[0]
          },
          lineItems: processedItems
        });

        setViewMode('verify');
      } catch (err) {
        console.error(err);
        alert("Failed to process document. Please try again.");
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const handleLineItemChange = useCallback((id: string, field: string, value: any) => {
    setRfqData(prev => {
      const newItems = prev.lineItems.map(item => {
        if (item.id !== id) return item;

        // Clone item to avoid mutation
        const updated = { ...item };

        if (field.startsWith('dimensions.')) {
          const dimKey = field.split('.')[1] as keyof typeof updated.dimensions;
          updated.dimensions = { ...updated.dimensions, [dimKey]: value };
        } else if (field === 'material') {
           updated.material = value as MaterialType;
        } else if (field === 'quantity') {
           updated.quantity = value;
        } else {
          (updated as any)[field] = value;
        }

        // RECALCULATE DETERMINISTICALLY
        updated.calculation = calculateLineItem(updated.material, updated.dimensions, updated.quantity);
        return updated;
      });

      return { ...prev, lineItems: newItems };
    });
  }, []);

  const handleSaveQuote = (header: typeof INITIAL_HEADER) => {
      setRfqData(prev => ({ ...prev, header }));
      setIsModalOpen(false);
      alert("Quote Saved Successfully to System! (Simulation)");
  };

  // --- Render ---

  if (viewMode === 'upload') {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
        <div className="max-w-md w-full text-center mb-8">
           <h1 className="text-3xl font-bold text-gray-900 mb-2">DBT AI Cost Estimation</h1>
           <p className="text-gray-500">Upload your RFQ document (PDF or Image) to automatically extract line items and calculate costs.</p>
        </div>

        <div className="w-full max-w-2xl bg-white rounded-2xl shadow-xl p-12 border-2 border-dashed border-gray-300 hover:border-blue-500 transition-colors group">
            <div className="flex flex-col items-center justify-center">
              <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                 <Upload className="w-10 h-10 text-blue-600" />
              </div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">Upload Document</h3>
              <p className="text-sm text-gray-400 mb-6">Drag and drop or click to browse</p>

              <label className="relative">
                <input 
                  type="file" 
                  accept="image/*,application/pdf"
                  onChange={handleFileUpload}
                  className="hidden"
                  disabled={isProcessing}
                />
                <span className={`cursor-pointer px-8 py-3 bg-blue-600 text-white font-medium rounded-lg shadow hover:bg-blue-700 transition-colors ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>
                  {isProcessing ? 'Analyzing with Gemini...' : 'Select File'}
                </span>
              </label>
            </div>
        </div>

        <div className="mt-8 text-xs text-gray-400">
           Powered by Google Gemini 2.5 Flash • Enterprise Grade Security
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-gray-100 overflow-hidden font-sans">
      {/* Top Bar */}
      <header className="bg-white border-b border-gray-200 h-14 flex items-center justify-between px-4 shrink-0 z-20">
        <div className="flex items-center gap-4">
           <button onClick={() => setViewMode('upload')} className="p-1.5 hover:bg-gray-100 rounded text-gray-600">
             <ArrowLeft className="w-5 h-5" />
           </button>
           <h1 className="font-semibold text-gray-800">DBT AI Cost Estimation</h1>
           <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs rounded font-medium">Verify Mode</span>
