         lineItems: [] // We would load line items here
       });
       setEditorMode('verify');
       setViewMode('editor');
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setIsProcessing(true);

      try {
        const base64Data = await fileToBase64(selectedFile);
        const base64Content = base64Data.split(',')[1];

        const extracted = await extractRFQData(base64Content, selectedFile.type);

        const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
          const material = Object.values(MaterialType).includes(item.material as MaterialType) 
            ? item.material as MaterialType 
            : MaterialType.STEEL_C45;

          const dims = {
             length: item.length || 0,
             width: item.width || 0,
             height: item.height || 0
          };

          return {
            id: `item-${Date.now()}-${idx}`,
            description: item.description || `Item ${idx + 1}`,
            material,
            quantity: item.quantity || 1,
            unit: item.unit || 'ST',
            dimensions: dims,
            deliveryDate: item.deliveryDate || '',
            tolerance: item.tolerance,
            calculation: calculateLineItem(material, dims, item.quantity || 1)
          };
        });

        setRfqData({
          header: {
            ...INITIAL_HEADER,
            customerName: extracted.customerName || '',
            rfqNumber: extracted.rfqNumber || '',
            documentDate: extracted.documentDate || new Date().toISOString().split('T')[0]
          },
          lineItems: processedItems
        });

        setEditorMode('verify');
      } catch (err) {
        console.error(err);
        alert("Failed to process document. Please try again.");
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const handleLineItemChange = useCallback((id: string, field: string, value: any) => {
    setRfqData(prev => {
      const newItems = prev.lineItems.map(item => {
        if (item.id !== id) return item;
        const updated = { ...item };

        if (field.startsWith('dimensions.')) {
          const dimKey = field.split('.')[1] as keyof typeof updated.dimensions;
          updated.dimensions = { ...updated.dimensions, [dimKey]: value };
        } else if (field === 'material') {
           updated.material = value as MaterialType;
        } else if (field === 'quantity') {
           updated.quantity = value;
        } else {
          (updated as any)[field] = value;
        }

        updated.calculation = calculateLineItem(updated.material, updated.dimensions, updated.quantity);
        return updated;
      });
      return { ...prev, lineItems: newItems };
    });
  }, []);

  const handleAddManualItem = () => {
    const newItem: LineItem = {
      id: `manual-${Date.now()}`,
      description: 'New Manual Item',
      material: MaterialType.STEEL_C45,
      quantity: 1,
      unit: 'ST',
      dimensions: { length: 0, width: 0, height: 0 },
      calculation: calculateLineItem(MaterialType.STEEL_C45, { length: 0, width: 0, height: 0 }, 1)
    };
    setRfqData(prev => ({ ...prev, lineItems: [...prev.lineItems, newItem] }));
    if (editorMode === 'upload') setEditorMode('verify');
  };

  const handleSaveQuote = (header: typeof INITIAL_HEADER) => {
    const newQuote: SavedQuote = {
      ...header,
      id: `q-${Date.now()}`,
      status: QuoteStatus.DRAFT,
      totalValue: totalCost,
      lastModified: new Date().toISOString()
    };
    setSavedQuotes(prev => [newQuote, ...prev]);
    setIsModalOpen(false);
    setViewMode('dashboard');
  };

  // --- Render ---

  return (
    <div className="flex h-screen bg-gray-100 font-sans overflow-hidden">

      {/* Sidebar Navigation */}
      <aside className="w-64 bg-slate-900 text-slate-300 flex flex-col shrink-0">
        <div className="h-16 flex items-center px-6 border-b border-slate-800">
           <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center mr-3">
             <Calculator className="w-5 h-5 text-white" />
           </div>
           <span className="font-bold text-white text-lg tracking-tight">CostAI</span>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          <button 
            onClick={() => setViewMode('dashboard')}
            className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors ${viewMode === 'dashboard' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'hover:bg-slate-800 hover:text-white'}`}
          >
            <LayoutDashboard className="w-5 h-5" />
            <span className="font-medium">Dashboard</span>
          </button>

          <button 
            onClick={() => {
              if (editorMode === 'upload' && rfqData.lineItems.length > 0) setEditorMode('verify');
              setViewMode('editor');
            }}
            className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors ${viewMode === 'editor' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'hover:bg-slate-800 hover:text-white'}`}
          >
            <FileText className="w-5 h-5" />
            <span className="font-medium">Active Quote</span>
          </button>
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button className="w-full flex items-center gap-3 px-3 py-2 text-sm hover:text-white transition-colors">
            <Settings className="w-4 h-4" /> Settings
          </button>
          <button className="w-full flex items-center gap-3 px-3 py-2 text-sm hover:text-white transition-colors mt-1">
            <LogOut className="w-4 h-4" /> Sign Out
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">

        {viewMode === 'dashboard' ? (
          <Dashboard 
            quotes={savedQuotes} 
            onNewQuote={startNewQuote}
            onEditQuote={handleEditQuote}
          />
        ) : (
          /* Editor View */
          <div className="flex-1 flex flex-col h-full relative">

            {/* Editor Top Bar */}
            <header className="h-14 bg-white border-b border-gray-200 flex items-center justify-between px-6 shrink-0 z-10">
               <div className="flex items-center gap-4">
                 <button onClick={() => setViewMode('dashboard')} className="hover:bg-gray-100 p-1.5 rounded-full transition-colors text-gray-500">
                   <ArrowLeft className="w-5 h-5" />
                 </button>
                 <div className="h-6 w-px bg-gray-200"></div>
                 <h2 className="font-semibold text-gray-800">
                   {rfqData.header.rfqNumber || 'New Cost Estimate'}
                 </h2>
                 <span className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${editorMode === 'upload' ? 'bg-gray-100 text-gray-600' : 'bg-green-100 text-green-700'}`}>
                   {editorMode === 'upload' ? 'Upload Phase' : 'Verification Phase'}
                 </span>
               </div>

               <div className="flex items-center gap-3">
                  <button 
                    onClick={handleAddManualItem}
                    className="text-sm font-medium text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded transition-colors flex items-center gap-1"
                  >
                    <Plus className="w-4 h-4" /> Add Item
                  </button>
                  <button 
                    onClick={() => setIsChatOpen(!isChatOpen)}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded border text-sm font-medium transition-colors ${isChatOpen ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-gray-300 text-gray-700 hover:bg-gray-50'}`}
                  >
                    <Bot className="w-4 h-4" /> {isChatOpen ? 'Hide AI' : 'Ask AI'}
                  </button>
               </div>
            </header>

            {/* Editor Content Layout */}
            <div className="flex-1 flex overflow-hidden relative">

              {editorMode === 'upload' ? (
                 <div className="w-full h-full flex items-center justify-center bg-gray-50 p-6">
                    <div className="max-w-2xl w-full bg-white rounded-2xl shadow-xl p-12 border-2 border-dashed border-gray-300 hover:border-blue-500 transition-colors text-center">
                        <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6">
                          <Upload className="w-10 h-10 text-blue-600" />
                        </div>
                        <h3 className="text-xl font-bold text-gray-800 mb-2">Upload RFQ Document</h3>
                        <p className="text-gray-500 mb-8 max-w-md mx-auto">Upload a PDF or Image of your engineering drawing or BOM. AI will automatically extract items and dimensions.</p>

                        <div className="flex gap-4 justify-center">
                          <label className="relative">
                            <input 
                              type="file" 
                              accept="image/*,application/pdf"
                              onChange={handleFileUpload}
                              className="hidden"
                              disabled={isProcessing}
                            />
                            <span className={`cursor-pointer px-8 py-3 bg-blue-600 text-white font-medium rounded-lg shadow hover:bg-blue-700 transition-colors inline-block ${isProcessing ? 'opacity-50' : ''}`}>
                              {isProcessing ? 'Analyzing...' : 'Browse Files'}
                            </span>
                          </label>
                          <button onClick={handleAddManualItem} className="px-8 py-3 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50">
                            Manual Entry
                          </button>
                        </div>
                    </div>
                 </div>
              ) : (
                <>
                  {/* Left: Doc Preview */}
                  <div className="w-[45%] bg-gray-900 border-r border-gray-800 flex flex-col min-w-[300px]">
                    <div className="h-10 bg-gray-800 flex items-center justify-between px-4">
                       <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                         <FileText className="w-3 h-3" /> Source Document
                       </span>
                       <button className="text-gray-400 hover:text-white"><Download className="w-4 h-4" /></button>
                    </div>
                    <div className="flex-1 overflow-auto flex items-center justify-center p-4 bg-gray-900/50 backdrop-blur-sm">
                      {file?.type === 'application/pdf' ? (
                        <iframe src={filePreview || ''} className="w-full h-full rounded bg-white" title="PDF Preview" />
                      ) : (
                        <img src={filePreview || ''} alt="RFQ Document" className="max-w-full max-h-full object-contain rounded shadow-lg" />
                      )}
                    </div>
                  </div>

                  {/* Center: Form */}
                  <div className="flex-1 flex flex-col bg-white min-w-[400px]">

                    {/* Form Header Area */}
                    <div className="p-6 border-b border-gray-100 bg-white">
                       <div className="grid grid-cols-2 gap-6">
                          <div className="group">
                             <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1 group-focus-within:text-blue-600 transition-colors">Customer</label>
                             <input 
                                value={rfqData.header.customerName}
                                onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, customerName: e.target.value}}))}
                                className="w-full text-lg font-semibold text-gray-800 border-b border-gray-200 focus:border-blue-600 outline-none py-1 bg-transparent transition-colors" 
                                placeholder="Client Name"
                             />
                          </div>
                          <div className="group">
                             <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1 group-focus-within:text-blue-600 transition-colors">RFQ Reference</label>
                             <input 
                                value={rfqData.header.rfqNumber}
                                onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, rfqNumber: e.target.value}}))}
                                className="w-full text-lg font-mono font-medium text-gray-800 border-b border-gray-200 focus:border-blue-600 outline-none py-1 bg-transparent transition-colors" 
                                placeholder="RFQ-0000"
                             />
                          </div>
                       </div>
                    </div>

                    {/* Scrollable Items */}
                    <div className="flex-1 overflow-y-auto p-6 bg-gray-50/50">
                       <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">
                         Line Items ({rfqData.lineItems.length})
                       </h3>
                       {rfqData.lineItems.map((item, index) => (
                          <LineItemCard 
                            key={item.id} 
                            item={item} 
                            index={index} 
                            onChange={handleLineItemChange} 
                          />
                       ))}

                       <button 
                         onClick={handleAddManualItem}
                         className="w-full py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 font-medium hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50 transition-all flex items-center justify-center gap-2"
                       >
                         <Plus className="w-5 h-5" /> Add Line Item
                       </button>
                    </div>

                    {/* Footer Actions */}
                    <div className="p-4 border-t border-gray-200 bg-white shadow-[0_-4px_20px_-5px_rgba(0,0,0,0.1)] z-20">
                      <div className="flex items-center justify-between">
                         <div>
                            <p className="text-xs text-gray-500 font-medium">TOTAL ESTIMATED COST</p>
                            <p className="text-3xl font-bold text-slate-800">{formatCurrency(totalCost)}</p>
                         </div>
                         <div className="flex gap-3">
                            <button 
                              onClick={() => setRfqData({header: INITIAL_HEADER, lineItems: []})}
                              className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg font-medium"
                            >
                              Reset
                            </button>
                            <button 
                              onClick={() => setIsModalOpen(true)}
                              className="px-6 py-2.5 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 shadow-lg shadow-blue-200 transition-transform active:scale-95 flex items-center gap-2"
                            >
                              <Save className="w-4 h-4" /> Save Quote
                            </button>
                         </div>
                      </div>
                    </div>
                  </div>
                </>
              )}

              {/* Right: AI Chat Panel (Overlay or pushes content) */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

export default App;

