  length: number;
  width: number;
  height: number;
}

export interface CalculationResult {
  volumeMm3: number;
  density: number; // g/cm3
  weightGrams: number;
  materialCost: number;
  totalLineCost: number;
}

export interface LineItem {
  id: string;
  description: string;
