                    <h2 className="font-semibold text-gray-800">
                      {rfqData.header.rfqNumber || 'New Cost Estimate'}
                    </h2>
                  </div>

                  {/* Workflow Stepper */}
                  {editorMode === 'verify' && (
                     <div className="flex items-center">
                        {[QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].map((step, idx) => {
                           const isActive = step === currentStatus;
                           const isPast = [QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].indexOf(currentStatus) > idx;
