                                 </button>
                              </div>
                           </div>
                        </div>
                       </>
                    )}

                    {/* Collaboration Tab Content */}
                    {activeTab === 'collaboration' && (
                       <div className="flex-1 flex flex-col bg-gray-50 p-6">
                          <div className="flex-1 overflow-y-auto space-y-4 mb-4">
