                          </div>
                          <div className="bg-white p-4 rounded-xl border border-gray-200 flex gap-2">
                             <input 
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && addComment()}
                                placeholder="Type a note or message..."
                                className="flex-1 outline-none text-sm"
                             />
                             <button onClick={addComment} className="text-blue-600 hover:bg-blue-50 p-2 rounded-lg"><Send className="w-4 h-4" /></button>
                          </div>
                       </div>
                    )}

                    {/* Documents Tab Content */}
                    {activeTab === 'documents' && (
                       <div className="flex-1 bg-gray-50 p-6">
                          <div className="grid grid-cols-2 gap-4">
                             {rfqData.attachments.map(file => (
                                <div key={file.id} className="bg-white p-4 rounded-lg border border-gray-200 flex items-center justify-between group hover:border-blue-500 transition-colors cursor-pointer">
                                   <div className="flex items-center gap-3">
                                      <div className="p-2 bg-red-50 text-red-600 rounded">
                                         <FileText className="w-6 h-6" />
                                      </div>
                                      <div>
                                         <p className="font-medium text-gray-800 text-sm">{file.name}</p>
                                         <p className="text-xs text-gray-500">{file.size} • {file.uploadDate}</p>
                                      </div>
                                   </div>
                                   <button className="text-gray-400 hover:text-blue-600"><Download className="w-4 h-4" /></button>
                                </div>
                             ))}
                             <div className="border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center p-6 text-gray-400 hover:border-blue-500 hover:text-blue-500 transition-colors cursor-pointer bg-white/50">
                                <Plus className="w-8 h-8 mb-2" />
                                <span className="text-sm font-medium">Add Document</span>
                             </div>
                          </div>
                       </div>
                    )}

                  </div>
                </>
              )}

              {/* Right: AI Chat Panel */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

export default App;

import React, { useState, useCallback } from 'react';
import { 
  Upload, FileText, ArrowLeft, Bot, Save, Download, 
  LayoutDashboard, Settings, LogOut, ChevronRight, Calculator, Plus, 
  Users, BarChart2, CheckCircle, MessageSquare, Paperclip, Send, Bell
} from 'lucide-react';
import { extractRFQData } from './services/geminiService';
import { calculateLineItem, formatCurrency } from './services/calculationService';
import { RFQData, LineItem, ViewMode, EditorMode, MaterialType, SavedQuote, QuoteStatus, Comment, Attachment } from './types';
import { INITIAL_HEADER } from './constants';
