import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { RFQData } from '../types';
import { formatCurrency, formatNumber } from './calculationService';

export const generateQuotePDF = (data: RFQData) => {
  const doc = new jsPDF();

  // Header
  doc.setFontSize(20);
  doc.setTextColor(40, 40, 40);
  doc.text('Cost Estimate / Quotation', 14, 22);

  doc.setFontSize(10);
  doc.setTextColor(100, 100, 100);
  doc.text(`Created: ${new Date().toLocaleDateString()}`, 14, 28);

  // Vendor & Customer Info
  doc.setDrawColor(200, 200, 200);
  doc.line(14, 32, 196, 32);

  doc.setFontSize(10);
  doc.setTextColor(0, 0, 0);

  // Left Column (Vendor)
  doc.setFont('helvetica', 'bold');
  doc.text('From:', 14, 40);
  doc.setFont('helvetica', 'normal');
  doc.text(data.header.vendorName || 'Vendor Name', 14, 45);
  doc.text(data.header.location || 'Location', 14, 50);

  // Right Column (Customer)
  doc.setFont('helvetica', 'bold');
  doc.text('Bill To:', 120, 40);
  doc.setFont('helvetica', 'normal');
  doc.text(data.header.customerName || 'Customer Name', 120, 45);
  doc.text(`RFQ #: ${data.header.rfqNumber}`, 120, 50);
  doc.text(`Date: ${data.header.documentDate}`, 120, 55);

  // Line Items Table
  const tableBody = data.lineItems.map((item, index) => [
    index + 1,
    item.description,
    item.material,
    `${item.dimensions.length}x${item.dimensions.width}x${item.dimensions.height}`,
    item.quantity,
    item.unit,
    formatCurrency(item.calculation.materialCost),
    formatCurrency(item.calculation.totalLineCost)
  ]);

  autoTable(doc, {
    startY: 65,
    head: [['#', 'Description', 'Material', 'Dims (mm)', 'Qty', 'Unit', 'Unit Cost', 'Total']],
    body: tableBody,
    theme: 'grid',
    headStyles: { fillColor: [37, 99, 235], textColor: 255 },
    styles: { fontSize: 8, cellPadding: 3 },
    columnStyles: {
      0: { cellWidth: 10 }, // #
      1: { cellWidth: 'auto' }, // Desc
      7: { halign: 'right', fontStyle: 'bold' }, // Total
      6: { halign: 'right' } // Unit Cost
    }
  });

  // Totals
  const totalCost = data.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);
  // Type assertion for jspdf-autotable extension
  const finalY = (doc as any).lastAutoTable ? (doc as any).lastAutoTable.finalY + 10 : 75;

  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Total Estimate:', 140, finalY);
  doc.text(formatCurrency(totalCost), 196, finalY, { align: 'right' });

  // Footer
  doc.setFontSize(8);
  doc.setFont('helvetica', 'italic');
  doc.setTextColor(150, 150, 150);
  doc.text('This is a computer-generated estimate. Not a binding contract unless signed.', 105, 280, { align: 'center' });

  doc.save(`Quote_${data.header.rfqNumber || 'Draft'}.pdf`);
};

import { GoogleGenAI, Type } from "@google/genai";
import { MaterialType, RFQData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const EXTRACT_SYSTEM_INSTRUCTION = `
You are an expert manufacturing cost estimator. 
Extract structured RFQ data from the provided document image.

RULES:
1. Extract ALL line items found in the document.
2. If specific dimensions (Length/Width/Height) are not explicitly labeled, infer them from descriptions like "45x25x160".
3. Map "Depth" or "Tiefe" to 'length' if 'length' is missing.
4. Identify standard materials. Map "C45", "C 45 K", "1.0503" to 'C45'. Map "Alu" to 'Alu 6061'.
5. If a unit price is listed in the document, ignore it for the calculation fields, but ensure the Quantity and Dimensions are extracted accurately so the system can recalculate.
6. Extract the 'Delivery Date' if present.
7. Extract 'Tolerance' information if present (e.g., "h9", "H7", "No Tolerance").
8. Default missing integer dimensions to 0.

OUTPUT FORMAT:
JSON with customer details and list of items.
`;

const CHAT_SYSTEM_INSTRUCTION = `
You are an expert manufacturing cost engineer assistant (Copilot).
You have access to the current RFQ data (JSON).
Answer the user's questions based strictly on the provided RFQ data and standard manufacturing knowledge.
Be concise, professional, and helpful.
If the user asks about costs, explain the calculation (Volume * Density * Cost Rate).
`;

export const extractRFQData = async (base64Image: string, mimeType: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: "Extract the customer details, RFQ number, document date, and a list of all line items including description, material, quantity, unit, dimensions (length, width, height), delivery date, and tolerance.",
          },
        ],
      },
      config: {
        systemInstruction: EXTRACT_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            customerName: { type: Type.STRING },
            rfqNumber: { type: Type.STRING },
            documentDate: { type: Type.STRING },
            lineItems: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  description: { type: Type.STRING },
                  material: { type: Type.STRING },
                  quantity: { type: Type.INTEGER },
                  length: { type: Type.NUMBER },
                  width: { type: Type.NUMBER },
                  height: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  deliveryDate: { type: Type.STRING },
                  tolerance: { type: Type.STRING }
                },
                required: ["description", "quantity", "length", "width", "height"],
              },
            },
          },
          required: ["lineItems"],
        },
      },
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    throw new Error("Failed to extract data from document.");
  }
};

export const chatWithQuote = async (rfqData: RFQData, userMessage: string, history: {role: string, text: string}[]) => {
  try {
    const context = JSON.stringify(rfqData);

    // Construct chat history for the model

    const prompt = `
    CURRENT RFQ CONTEXT:
    ${context}

    USER QUESTION:
    ${userMessage}
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        systemInstruction: CHAT_SYSTEM_INSTRUCTION,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Chat Error:", error);
    return "I'm having trouble analyzing the quote right now. Please try again.";
  }
};

