    if (rfqData.lineItems.length > 0) {
      setRfqData(prev => ({
        ...prev,
        lineItems: prev.lineItems.map(item => ({
          ...item,
          calculation: calculateLineItem(item.material, item.dimensions, item.quantity, newConfig)
        }))
      }));
    }
  };

  const startNewQuote = () => {
    setRfqData({ header: INITIAL_HEADER, lineItems: [], comments: [], attachments: [] });
    setFile(null);
    setFilePreview(null);
    setEditorMode('upload');
    setCurrentStatus(QuoteStatus.DRAFT);
    setViewMode('editor');
    setIsChatOpen(false);
  };

  const handleEditQuote = (id: string) => {
    const quote = savedQuotes.find(q => q.id === id);
    if (quote) {
       setRfqData({
         header: quote,
         lineItems: [], // In real app, load items
         comments: MOCK_COMMENTS,
         attachments: MOCK_ATTACHMENTS
       });
       setCurrentStatus(quote.status);
       setEditorMode('verify');
       setViewMode('editor');
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setIsProcessing(true);

      try {
        const base64Data = await fileToBase64(selectedFile);
        const base64Content = base64Data.split(',')[1];

        const extracted = await extractRFQData(base64Content, selectedFile.type);

        const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
          const material = Object.values(MaterialType).includes(item.material as MaterialType) 
            ? item.material as MaterialType 
            : MaterialType.STEEL_C45;

          const dims = {
             length: item.length || 0,
             width: item.width || 0,
             height: item.height || 0
          };

          return {
            id: `item-${Date.now()}-${idx}`,
            description: item.description || `Item ${idx + 1}`,
            material,
            quantity: item.quantity || 1,
            unit: item.unit || 'ST',
            dimensions: dims,
            deliveryDate: item.deliveryDate || '',
            tolerance: item.tolerance,
            calculation: calculateLineItem(material, dims, item.quantity || 1, pricingConfig)
          };
        });

        setRfqData(prev => ({
          ...prev,
          header: {
            ...INITIAL_HEADER,
            customerName: extracted.customerName || '',
            rfqNumber: extracted.rfqNumber || '',
            documentDate: extracted.documentDate || new Date().toISOString().split('T')[0]
          },
          lineItems: processedItems,
          attachments: [...prev.attachments, {
             id: Date.now().toString(),
             name: selectedFile.name,
             size: `${(selectedFile.size / 1024 / 1024).toFixed(2)} MB`,
             type: 'pdf',
             uploadDate: new Date().toLocaleDateString()
          }]
        }));

        setEditorMode('verify');
      } catch (err) {
        console.error(err);
        alert("Failed to process document. Please try again.");
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const handleLineItemChange = useCallback((id: string, field: string, value: any) => {
    setRfqData(prev => {
      const newItems = prev.lineItems.map(item => {
        if (item.id !== id) return item;
        const updated = { ...item };

        if (field.startsWith('dimensions.')) {
          const dimKey = field.split('.')[1] as keyof typeof updated.dimensions;
          updated.dimensions = { ...updated.dimensions, [dimKey]: value };
        } else if (field === 'material') {
           updated.material = value as MaterialType;
        } else if (field === 'quantity') {
           updated.quantity = value;
        } else {
          (updated as any)[field] = value;
        }

        updated.calculation = calculateLineItem(updated.material, updated.dimensions, updated.quantity, pricingConfig);
        return updated;
      });
      return { ...prev, lineItems: newItems };
    });
  }, [pricingConfig]);

  const handleAddManualItem = () => {
    const newItem: LineItem = {
      id: `manual-${Date.now()}`,
      description: 'New Manual Item',
      material: MaterialType.STEEL_C45,
      quantity: 1,
      unit: 'ST',
      dimensions: { length: 0, width: 0, height: 0 },
      calculation: calculateLineItem(MaterialType.STEEL_C45, { length: 0, width: 0, height: 0 }, 1, pricingConfig)
    };
    setRfqData(prev => ({ ...prev, lineItems: [...prev.lineItems, newItem] }));
    if (editorMode === 'upload') setEditorMode('verify');
  };

  const handleSaveQuote = (header: typeof INITIAL_HEADER) => {
    const newQuote: SavedQuote = {
      ...header,
      id: `q-${Date.now()}`,
      status: currentStatus,
      totalValue: totalCost,
      lastModified: new Date().toISOString()
    };
    setSavedQuotes(prev => [newQuote, ...prev]);
    setIsModalOpen(false);
    setViewMode('dashboard');
  };

  const handleExportPDF = () => {
    generateQuotePDF(rfqData);
  };

  const advanceWorkflow = () => {
     if (currentStatus === QuoteStatus.DRAFT) setCurrentStatus(QuoteStatus.REVIEW);
     else if (currentStatus === QuoteStatus.REVIEW) setCurrentStatus(QuoteStatus.APPROVED);
     else if (currentStatus === QuoteStatus.APPROVED) setCurrentStatus(QuoteStatus.SENT);
  };

  const addComment = () => {
    if (!newComment.trim()) return;
    setRfqData(prev => ({
      ...prev,
      comments: [...prev.comments, {
        id: Date.now().toString(),
        author: 'You',
        text: newComment,
        timestamp: new Date().toLocaleString(),
        type: 'internal'
      }]
    }));
    setNewComment('');
  };

  const NavigationButton = ({ mode, icon: Icon, label }: { mode: ViewMode, icon: any, label: string }) => {
    const isActive = viewMode === mode;
    return (
      <button 
        onClick={() => {
           if (mode === 'editor' && editorMode === 'upload' && rfqData.lineItems.length > 0) setEditorMode('verify');
           setViewMode(mode);
        }}
        className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200 group ${
          isActive 
            ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40 translate-x-1' 
            : 'text-slate-400 hover:bg-slate-800 hover:text-white'
        }`}
      >
        <Icon className={`w-5 h-5 ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-white'}`} />
        <span className="font-medium text-sm">{label}</span>
        {isActive && <ChevronRight className="w-4 h-4 ml-auto opacity-50" />}
      </button>
    );
  };

  // --- Render ---

  // 1. Customer Mode
  if (isCustomerMode) {
     return <CustomerPortal config={pricingConfig} onBackToLogin={handleBackToLogin} />;
  }

  // 2. Login Screen
  if (!isAuthenticated) {
     return <Login onLogin={handleLogin} onCustomerEnter={handleCustomerEnter} />;
  }

  // 3. Employee Dashboard
  return (
    <div className="flex h-screen bg-gray-50 font-sans overflow-hidden">

      {/* Modern Sidebar */}
      <aside className="w-64 bg-slate-950 flex flex-col shrink-0 z-20 shadow-xl">
        <div className="h-16 flex items-center px-6 border-b border-slate-800/50 bg-slate-950">
           <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-blue-700 rounded-lg flex items-center justify-center mr-3 shadow-lg shadow-blue-500/20">
             <Calculator className="w-5 h-5 text-white" />
           </div>
           <span className="font-bold text-white text-lg tracking-tight">CostAI</span>
           <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] bg-slate-800 text-slate-400 font-medium">ENT</span>
        </div>

        <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
          <div className="text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2 px-3 mt-2">Platform</div>
          <NavigationButton mode="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavigationButton mode="editor" icon={FileText} label="Active Quote" />

          <div className="text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2 px-3 mt-6">Management</div>
          <NavigationButton mode="suppliers" icon={Users} label="Suppliers" />
          <NavigationButton mode="analytics" icon={BarChart2} label="Analytics" />
          <NavigationButton mode="settings" icon={SettingsIcon} label="Settings" />
        </nav>

        <div className="p-4 border-t border-slate-800/50 bg-slate-900/50">
          <div className="flex items-center gap-3 px-3 py-2 mb-2">
             <div className="w-8 h-8 rounded-full bg-gradient-to-r from-purple-500 to-pink-500 flex items-center justify-center text-white text-xs font-bold">JD</div>
             <div className="flex-1 overflow-hidden">
                <p className="text-sm font-medium text-white truncate">John Doe</p>
                <p className="text-xs text-slate-500 truncate">Senior Estimator</p>
             </div>
          </div>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-2 text-sm text-slate-400 hover:text-white transition-colors">
            <LogOut className="w-4 h-4" /> Sign Out
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-gray-50/50">

        {viewMode === 'dashboard' && (
          <Dashboard 
            quotes={savedQuotes} 
            onNewQuote={startNewQuote}
            onEditQuote={handleEditQuote}
          />
        )}

        {viewMode === 'suppliers' && <Suppliers />}

        {viewMode === 'analytics' && <Analytics />}

        {viewMode === 'settings' && (
          <Settings 
            config={pricingConfig} 
            onUpdateConfig={updatePricingConfig} 
          />
        )}

        {viewMode === 'editor' && (
          <div className="flex-1 flex flex-col h-full relative animate-in fade-in duration-300">

            {/* Glassmorphism Header */}
            <header className="sticky top-0 z-10 bg-white/80 backdrop-blur-md border-b border-gray-200/50 shrink-0 transition-all">
               <div className="flex items-center justify-between px-6 h-16">
                  <div className="flex items-center gap-4">
                    <button onClick={() => setViewMode('dashboard')} className="hover:bg-gray-100 p-2 rounded-full transition-colors text-gray-500">
                      <ArrowLeft className="w-5 h-5" />
                    </button>
                    <div className="h-6 w-px bg-gray-200"></div>
                    <div>
                      <h2 className="font-bold text-gray-800 text-lg leading-tight">
                        {rfqData.header.rfqNumber || 'New Cost Estimate'}
                      </h2>
                      <p className="text-xs text-gray-500">{rfqData.header.customerName || 'Draft Quote'}</p>
                    </div>
                  </div>

                  {/* Modern Workflow Stepper */}
                  {editorMode === 'verify' && (
                     <div className="hidden lg:flex items-center bg-gray-100/50 p-1 rounded-full border border-gray-200/50">
                        {[QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].map((step, idx) => {
                           const isActive = step === currentStatus;
                           const isPast = [QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].indexOf(currentStatus) > idx;
                           return (
                              <div key={step} className="flex items-center">
                                 <div className={`flex items-center gap-1.5 px-4 py-1.5 rounded-full text-xs font-semibold transition-all duration-300 ${
                                    isActive ? 'bg-white text-blue-700 shadow-sm ring-1 ring-black/5' : 
                                    isPast ? 'text-green-600' : 'text-gray-400'
                                 }`}>
                                    {isPast && <CheckCircle className="w-3 h-3" />}
                                    {isActive && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />}
                                    {step}
                                 </div>
                              </div>
                           );
                        })}
                     </div>
                  )}

                  <div className="flex items-center gap-3">
                     <button 
                       onClick={handleExportPDF}
                       className="p-2 text-gray-400 hover:text-blue-600 relative transition-colors"
                       title="Export PDF"
                     >
                        <FileDown className="w-5 h-5" />
                     </button>
                     <div className="h-6 w-px bg-gray-200"></div>
                     <button className="p-2 text-gray-400 hover:text-gray-600 relative">
                        <Bell className="w-5 h-5" />
                        <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
                     </button>
                     <div className="h-6 w-px bg-gray-200"></div>
                     <button 
                       onClick={() => setIsChatOpen(!isChatOpen)}
                       className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all duration-200 ${isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white border border-gray-200 text-gray-700 hover:border-gray-300 hover:shadow-sm'}`}
                     >
                       <Bot className="w-4 h-4" /> {isChatOpen ? 'Copilot Active' : 'AI Copilot'}
                     </button>
                  </div>
               </div>

               {/* Sleek Tabs */}
               {editorMode === 'verify' && (
                  <div className="px-6 flex gap-8 border-t border-gray-100 bg-white/50 backdrop-blur-sm">
                     {[
                        { id: 'items', label: 'Line Items', count: rfqData.lineItems.length },
                        { id: 'collaboration', label: 'Collaboration', count: rfqData.comments.length },
                        { id: 'documents', label: 'Documents', count: rfqData.attachments.length }
                     ].map((tab) => (
                       <button 
                          key={tab.id}
                          onClick={() => setActiveTab(tab.id as any)}
                          className={`relative py-3 text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === tab.id ? 'text-blue-600' : 'text-gray-500 hover:text-gray-800'}`}
                       >
                          {tab.label}
                          {tab.count > 0 && (
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${activeTab === tab.id ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'}`}>
                              {tab.count}
                            </span>
                          )}
                          {activeTab === tab.id && (
                             <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-t-full layout-id-underline"></span>
                          )}
                       </button>
                     ))}
                  </div>
               )}
            </header>

            {/* Editor Content */}
            <div className="flex-1 flex overflow-hidden relative">

              {editorMode === 'upload' ? (
                 <div className="w-full h-full flex items-center justify-center bg-gray-50 p-8">
                    <div className="max-w-xl w-full bg-white rounded-3xl shadow-xl shadow-gray-200/50 p-12 border border-gray-100 text-center hover:shadow-2xl transition-shadow duration-500">
                        <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
                          <Upload className="w-10 h-10 text-blue-600" />
                        </div>
                        <h3 className="text-2xl font-bold text-gray-900 mb-3">Upload RFQ Document</h3>
                        <p className="text-gray-500 mb-10 leading-relaxed">Drag and drop your engineering drawings (PDF/Images) here. Our AI will extract specs, materials, and quantities instantly.</p>

                        <div className="flex flex-col gap-3">
                          <label className="relative group">
                            <input 
                              type="file" 
                              accept="image/*,application/pdf"
                              onChange={handleFileUpload}
                              className="hidden"
                              disabled={isProcessing}
                            />
                            <span className={`w-full block cursor-pointer px-8 py-4 bg-blue-600 text-white font-medium rounded-xl shadow-lg shadow-blue-500/30 hover:bg-blue-700 hover:shadow-blue-500/40 hover:-translate-y-0.5 transition-all ${isProcessing ? 'opacity-75' : ''}`}>
                              {isProcessing ? (
                                <span className="flex items-center justify-center gap-2"><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"/> Processing...</span>
                              ) : 'Select Document'}
                            </span>
                          </label>
                          <button onClick={handleAddManualItem} className="w-full px-8 py-4 bg-white text-gray-700 font-medium rounded-xl border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-colors">
                            Continue without File
                          </button>
                        </div>
                    </div>
                 </div>
              ) : (
                <>
                  {/* Document Preview Panel */}
                  <div className="hidden lg:flex w-[40%] bg-gray-900 border-r border-gray-800 flex-col min-w-[400px]">
                    <div className="h-12 bg-gray-950/50 flex items-center justify-between px-4 border-b border-white/5 backdrop-blur-sm">
                       <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                         <FileText className="w-3 h-3" /> Source Preview
                       </span>
                       <div className="flex gap-2">
                          <button className="p-1.5 text-gray-400 hover:text-white rounded hover:bg-white/10 transition-colors"><Download className="w-4 h-4" /></button>
                       </div>
                    </div>
                    <div className="flex-1 overflow-auto flex items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] bg-gray-900">
                      <div className="relative shadow-2xl shadow-black/50 rounded-lg overflow-hidden transition-transform hover:scale-[1.01] duration-300">
                        {file?.type === 'application/pdf' ? (
                          <iframe src={filePreview || ''} className="w-full h-[800px] bg-white" title="PDF Preview" />
                        ) : (
                          <img src={filePreview || ''} alt="RFQ Document" className="max-w-full max-h-[80vh] object-contain bg-white" />
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Form & Workspace */}
                  <div className="flex-1 flex flex-col bg-white min-w-[400px]">

                    {/* Items View */}
                    {activeTab === 'items' && (
                       <>
                        {/* Quote Details Bar */}
                        <div className="px-8 py-6 border-b border-gray-100 bg-white">
                           <div className="grid grid-cols-2 gap-8">
                              <div className="group relative">
                                 <label className="absolute -top-2 left-2 bg-white px-1 text-[10px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">Customer Name</label>
                                 <input 
                                    value={rfqData.header.customerName}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, customerName: e.target.value}}))}
                                    className="w-full text-lg font-semibold text-gray-800 border border-gray-200 rounded-lg px-4 py-3 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all" 
                                    placeholder="Enter Client Name"
                                 />
                              </div>
                              <div className="group relative">
                                 <label className="absolute -top-2 left-2 bg-white px-1 text-[10px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">RFQ Reference</label>
                                 <input 
                                    value={rfqData.header.rfqNumber}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, rfqNumber: e.target.value}}))}
                                    className="w-full text-lg font-mono font-medium text-gray-800 border border-gray-200 rounded-lg px-4 py-3 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all" 
                                    placeholder="RFQ-0000"
                                 />
                              </div>
                           </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-8 bg-gray-50/30 space-y-4">
                           <div className="flex justify-between items-center mb-2">
                              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider pl-1">Line Items</h3>
                              <button onClick={handleAddManualItem} className="text-sm text-blue-600 hover:text-blue-800 font-medium flex items-center gap-1 hover:underline">
                                 <Plus className="w-4 h-4" /> Add Item manually
                              </button>
                           </div>

                           {rfqData.lineItems.map((item, index) => (
                              <LineItemCard 
                                key={item.id} 
                                item={item} 
                                index={index} 
                                onChange={handleLineItemChange} 
                              />
                           ))}

                           <div className="h-20"></div> {/* Spacer */}
                        </div>

                        {/* Sticky Footer */}
                        <div className="px-8 py-5 border-t border-gray-200 bg-white shadow-[0_-4px_20px_-5px_rgba(0,0,0,0.05)] z-20">
                           <div className="flex items-center justify-between">
                              <div>
                                 <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider mb-0.5">Total Estimate</p>
                                 <p className="text-3xl font-bold text-slate-900 tracking-tight">{formatCurrency(totalCost)}</p>
                              </div>
                              <div className="flex gap-4">
                                 <button 
                                 onClick={advanceWorkflow}
                                 disabled={currentStatus === QuoteStatus.SENT}
                                 className="px-6 py-3 bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-xl font-medium disabled:opacity-50 transition-colors"
                                 >
                                    {currentStatus === QuoteStatus.SENT ? 'Locked' : 'Approve Stage'}
                                 </button>
                                 <button 
                                 onClick={() => setIsModalOpen(true)}
                                 className="px-8 py-3 bg-blue-600 text-white rounded-xl font-medium hover:bg-blue-700 shadow-lg shadow-blue-500/20 hover:shadow-blue-500/40 transition-all hover:-translate-y-0.5 active:translate-y-0 flex items-center gap-2"
                                 >
                                 <Save className="w-4 h-4" /> Save Quote
                                 </button>
                              </div>
                           </div>
                        </div>
                       </>
                    )}

                    {/* Collaboration View */}
                    {activeTab === 'collaboration' && (
                       <div className="flex-1 flex flex-col bg-gray-50 p-6">
                          <div className="flex-1 overflow-y-auto space-y-6 mb-4 px-4">
                             {rfqData.comments.length === 0 && (
                                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4">
                                  <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center">
                                    <MessageSquare className="w-8 h-8 text-gray-300" />
                                  </div>
                                  <p>No messages yet. Start the conversation.</p>
                                </div>
                             )}
                             {rfqData.comments.map(comment => (
                                <div key={comment.id} className={`flex ${comment.author === 'You' ? 'justify-end' : 'justify-start'}`}>
                                   <div className={`max-w-[80%] rounded-2xl p-5 shadow-sm ${comment.author === 'You' ? 'bg-blue-600 text-white rounded-br-sm' : 'bg-white border border-gray-100 text-gray-800 rounded-bl-sm'}`}>
                                      <div className="flex justify-between items-center mb-2 gap-8">
                                         <span className={`font-bold text-xs ${comment.author === 'You' ? 'text-blue-100' : 'text-gray-500'}`}>{comment.author}</span>
                                         <span className={`text-[10px] ${comment.author === 'You' ? 'text-blue-200' : 'text-gray-400'}`}>{comment.timestamp}</span>
                                      </div>
                                      <p className="text-sm leading-relaxed">{comment.text}</p>
                                   </div>
                                </div>
                             ))}
                          </div>
                          <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-lg shadow-gray-200/50 flex gap-3 items-end">
                             <div className="p-2 text-gray-400 hover:text-gray-600 cursor-pointer">
                                <Paperclip className="w-5 h-5" />
                             </div>
                             <textarea 
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && addComment()}
                                placeholder="Type a note to your team or supplier..."
                                className="flex-1 outline-none text-sm resize-none max-h-32 py-2"
                                rows={1}
                             />
                             <button 
                              onClick={addComment} 
                              className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 transition-colors shadow-md"
                             >
                               <Send className="w-4 h-4" />
                             </button>
                          </div>
                       </div>
