                       </thead>
                       <tbody className="divide-y divide-gray-50">
                          {rfqData.lineItems.map((item) => (
                             <tr key={item.id}>
                                <td className="py-4">
                                   <p className="font-medium text-gray-800">{item.description}</p>
                                   <p className="text-xs text-gray-400">{item.dimensions.length}x{item.dimensions.width}x{item.dimensions.height}mm</p>
                                </td>
                                <td className="py-4 text-sm text-gray-600">{item.material}</td>
                                <td className="py-4 text-sm text-gray-600">{item.quantity}</td>
                                <td className="py-4 text-sm font-bold text-gray-900 text-right">{formatCurrency(item.calculation.totalLineCost)}</td>
                             </tr>
