           <div className="bg-white rounded-2xl shadow-sm border border-gray-200/60 p-6">
              <div className="flex items-center gap-3 mb-4">
                 <AlertCircle className="w-5 h-5 text-amber-500" />
                 <h3 className="font-bold text-gray-800">Calculation Logic</h3>
              </div>
              <div className="space-y-4 text-sm text-gray-600">
                 <div className="flex justify-between border-b border-gray-100 pb-2">
                    <span>Formula</span>
                    <span className="font-mono text-gray-900">Vol × Density × Rate</span>
                 </div>
                 <div className="flex justify-between border-b border-gray-100 pb-2">
                    <span>Volume Unit</span>
                    <span className="font-mono text-gray-900">cm³ (derived from mm)</span>
                 </div>
                 <div className="flex justify-between border-b border-gray-100 pb-2">
                    <span>Currency</span>
                    <span className="font-mono text-gray-900">EUR (€)</span>
                 </div>
              </div>
           </div>
        </div>

      </div>
    </div>
  );
};

