                  <div className="flex-1 flex flex-col bg-white min-w-[400px]">

                    {/* Items View */}
                    {activeTab === 'items' && (
                       <>
                        {/* Quote Details Bar */}
                        <div className="px-8 py-6 border-b border-gray-100 bg-white">
                           <div className="grid grid-cols-2 gap-8">
                              <div className="group relative">
                                 <label className="absolute -top-2 left-2 bg-white px-1 text-[10px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">Customer Name</label>
                                 <input 
                                    value={rfqData.header.customerName}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, customerName: e.target.value}}))}
                                    className="w-full text-lg font-semibold text-gray-800 border border-gray-200 rounded-lg px-4 py-3 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all" 
                                    placeholder="Enter Client Name"
                                 />
                              </div>
                              <div className="group relative">
                                 <label className="absolute -top-2 left-2 bg-white px-1 text-[10px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">RFQ Reference</label>
                                 <input 
                                    value={rfqData.header.rfqNumber}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, rfqNumber: e.target.value}}))}
                                    className="w-full text-lg font-mono font-medium text-gray-800 border border-gray-200 rounded-lg px-4 py-3 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all" 
                                    placeholder="RFQ-0000"
                                 />
                              </div>
                           </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-8 bg-gray-50/30 space-y-4">
                           <div className="flex justify-between items-center mb-2">
                              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider pl-1">Line Items</h3>
                              <button onClick={handleAddManualItem} className="text-sm text-blue-600 hover:text-blue-800 font-medium flex items-center gap-1 hover:underline">
                                 <Plus className="w-4 h-4" /> Add Item manually
                              </button>
                           </div>

                           {rfqData.lineItems.map((item, index) => (
                              <LineItemCard 
                                key={item.id} 
                                item={item} 
                                index={index} 
                                onChange={handleLineItemChange} 
                              />
                           ))}

                           <div className="h-20"></div> {/* Spacer */}
                        </div>

                        {/* Sticky Footer */}
                        <div className="px-8 py-5 border-t border-gray-200 bg-white shadow-[0_-4px_20px_-5px_rgba(0,0,0,0.05)] z-20">
                           <div className="flex items-center justify-between">
                              <div>
                                 <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider mb-0.5">Total Estimate</p>
                                 <p className="text-3xl font-bold text-slate-900 tracking-tight">{formatCurrency(totalCost)}</p>
                              </div>
                              <div className="flex gap-4">
                                 <button 
                                 onClick={advanceWorkflow}
                                 disabled={currentStatus === QuoteStatus.SENT}
                                 className="px-6 py-3 bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-xl font-medium disabled:opacity-50 transition-colors"
                                 >
                                    {currentStatus === QuoteStatus.SENT ? 'Locked' : 'Approve Stage'}
                                 </button>
                                 <button 
                                 onClick={() => setIsModalOpen(true)}
                                 className="px-8 py-3 bg-blue-600 text-white rounded-xl font-medium hover:bg-blue-700 shadow-lg shadow-blue-500/20 hover:shadow-blue-500/40 transition-all hover:-translate-y-0.5 active:translate-y-0 flex items-center gap-2"
                                 >
                                 <Save className="w-4 h-4" /> Save Quote
                                 </button>
                              </div>
                           </div>
                        </div>
                       </>
                    )}

                    {/* Collaboration View */}
                    {activeTab === 'collaboration' && (
                       <div className="flex-1 flex flex-col bg-gray-50 p-6">
                          <div className="flex-1 overflow-y-auto space-y-6 mb-4 px-4">
                             {rfqData.comments.length === 0 && (
                                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4">
                                  <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center">
                                    <MessageSquare className="w-8 h-8 text-gray-300" />
                                  </div>
                                  <p>No messages yet. Start the conversation.</p>
                                </div>
                             )}
                             {rfqData.comments.map(comment => (
                                <div key={comment.id} className={`flex ${comment.author === 'You' ? 'justify-end' : 'justify-start'}`}>
                                   <div className={`max-w-[80%] rounded-2xl p-5 shadow-sm ${comment.author === 'You' ? 'bg-blue-600 text-white rounded-br-sm' : 'bg-white border border-gray-100 text-gray-800 rounded-bl-sm'}`}>
                                      <div className="flex justify-between items-center mb-2 gap-8">
                                         <span className={`font-bold text-xs ${comment.author === 'You' ? 'text-blue-100' : 'text-gray-500'}`}>{comment.author}</span>
                                         <span className={`text-[10px] ${comment.author === 'You' ? 'text-blue-200' : 'text-gray-400'}`}>{comment.timestamp}</span>
                                      </div>
                                      <p className="text-sm leading-relaxed">{comment.text}</p>
                                   </div>
                                </div>
                             ))}
                          </div>
                          <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-lg shadow-gray-200/50 flex gap-3 items-end">
                             <div className="p-2 text-gray-400 hover:text-gray-600 cursor-pointer">
                                <Paperclip className="w-5 h-5" />
                             </div>
                             <textarea 
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && addComment()}
                                placeholder="Type a note to your team or supplier..."
                                className="flex-1 outline-none text-sm resize-none max-h-32 py-2"
                                rows={1}
                             />
                             <button 
                              onClick={addComment} 
                              className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 transition-colors shadow-md"
                             >
                               <Send className="w-4 h-4" />
                             </button>
                          </div>
                       </div>
                    )}

                    {/* Documents View */}
                    {activeTab === 'documents' && (
                       <div className="flex-1 bg-gray-50 p-8">
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                             {rfqData.attachments.map(file => (
                                <div key={file.id} className="bg-white p-5 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-all group cursor-pointer relative overflow-hidden">
                                   <div className="absolute top-0 left-0 w-1 h-full bg-blue-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                   <div className="flex items-start justify-between mb-4">
                                      <div className="p-3 bg-red-50 text-red-600 rounded-lg">
                                         <FileText className="w-6 h-6" />
                                      </div>
                                      <button className="text-gray-300 hover:text-blue-600 transition-colors"><Download className="w-4 h-4" /></button>
                                   </div>
                                   <p className="font-semibold text-gray-800 text-sm truncate mb-1" title={file.name}>{file.name}</p>
                                   <p className="text-xs text-gray-400 flex items-center gap-2">
                                     <span>{file.size}</span>
                                     <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                     <span>{file.uploadDate}</span>
                                   </p>
                                </div>
                             ))}
                             <div className="border-2 border-dashed border-gray-300 rounded-xl flex flex-col items-center justify-center p-8 text-gray-400 hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50/50 transition-all cursor-pointer bg-white/50 group">
                                <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center mb-3 group-hover:bg-blue-100 transition-colors">
                                  <Plus className="w-6 h-6" />
                                </div>
                                <span className="text-sm font-bold">Add Document</span>
                                <span className="text-xs text-gray-400 mt-1">PDF, Excel, Images</span>
                             </div>
                          </div>
                       </div>
                    )}

                  </div>
                </>
              )}

              {/* Overlay AI Panel */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Upload, ArrowRight, CheckCircle, FileText, Loader2, AlertCircle, RefreshCw, Send, ChevronRight, Bot, X, Eye } from 'lucide-react';
import { extractRFQData } from '../services/geminiService';
import { calculateLineItem, formatCurrency } from '../services/calculationService';
import { RFQData, LineItem, MaterialType, PricingConfig } from '../types';
import { INITIAL_HEADER } from '../constants';
import { ChatPanel } from './ChatPanel';

interface CustomerPortalProps {
  config: PricingConfig;
  onBackToLogin: () => void;
}

type Step = 'upload' | 'analyzing' | 'review' | 'details' | 'success';

export const CustomerPortal: React.FC<CustomerPortalProps> = ({ config, onBackToLogin }) => {
  const [step, setStep] = useState<Step>('upload');
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [rfqData, setRfqData] = useState<RFQData>({
    header: INITIAL_HEADER,
    lineItems: [],
    comments: [],
    attachments: []
  });
  const [customerDetails, setCustomerDetails] = useState({ name: '', email: '', company: '', notes: '' });
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [showPreview, setShowPreview] = useState(true);

  // 1. Handle File Upload
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setStep('analyzing');

      try {
        // Convert to base64
        const reader = new FileReader();
        reader.readAsDataURL(selectedFile);
        reader.onload = async () => {
          const base64Content = (reader.result as string).split(',')[1];
          const extracted = await extractRFQData(base64Content, selectedFile.type);

          // Process Items
          const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
             const material = Object.values(MaterialType).includes(item.material as MaterialType) 
             ? item.material as MaterialType 
             : MaterialType.STEEL_C45;

             const dims = {
                length: item.length || 0,
                width: item.width || 0,
                height: item.height || 0
             };

             return {
               id: `cust-${Date.now()}-${idx}`,
               description: item.description || `Part #${idx + 1}`,
               material,
               quantity: item.quantity || 1,
               unit: item.unit || 'ST',
               dimensions: dims,
               deliveryDate: item.deliveryDate,
               tolerance: item.tolerance,
               calculation: calculateLineItem(material, dims, item.quantity || 1, config)
             };
          });

          setRfqData({
             ...rfqData,
             lineItems: processedItems
          });
          setStep('review');
        };
      } catch (error) {
        console.error(error);
        alert("We couldn't read that file. Please try a clear PDF or Image.");
        setStep('upload');
      }
    }
  };

  const totalCost = rfqData.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);

  const handleSubmit = () => {
    // In a real app, this would POST to an API
    setStep('success');
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans flex flex-col relative">
      {/* Public Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-20 shadow-sm">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
           <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/30">
                 <RefreshCw className="w-5 h-5 text-white" />
              </div>
              <div>
                 <h1 className="text-lg font-bold text-gray-900 tracking-tight">DBT Instant Quote</h1>
              </div>
           </div>

           <div className="flex items-center gap-4">
             {step === 'review' && (
                <button 
                  onClick={() => setIsChatOpen(!isChatOpen)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all ${
                    isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white border border-gray-200 text-gray-700 hover:bg-gray-50'
                  }`}
                >
                  <Bot className="w-4 h-4" /> 
                  {isChatOpen ? 'Assistant Active' : 'Ask AI Assistant'}
                </button>
             )}
             {step !== 'success' && (
               <button onClick={onBackToLogin} className="text-sm text-gray-500 hover:text-gray-900 font-medium">
                 Staff Login
               </button>
             )}
           </div>
        </div>
      </header>

      {/* Main Content */}
      <div className={`flex-1 flex flex-col ${step === 'review' ? 'overflow-hidden' : 'overflow-y-auto'}`}>

        {/* Step 1: Upload */}
        {step === 'upload' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
              <div className="max-w-xl w-full text-center">
                 <h2 className="text-4xl font-extrabold text-gray-900 mb-4 tracking-tight">Manufacturing quotes in seconds.</h2>
                 <p className="text-lg text-gray-600 mb-10">Upload your technical drawing. Our AI analyzes geometry and material to provide an instant estimate.</p>

                 <div className="bg-white rounded-3xl shadow-xl shadow-gray-200/50 border border-gray-100 p-12 text-center transition-all hover:shadow-2xl">
                    <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Upload className="w-10 h-10 text-blue-600" />
                    </div>
                    <label className="block mb-6 cursor-pointer group">
                        <input type="file" className="hidden" accept="application/pdf,image/*" onChange={handleFileUpload} />
                        <span className="block w-full py-4 px-6 bg-blue-600 text-white font-bold rounded-xl shadow-lg shadow-blue-500/30 group-hover:bg-blue-700 group-hover:shadow-blue-500/50 transition-all transform group-active:scale-95">
                          Upload Drawing (PDF/Image)
                        </span>
                    </label>
                    <p className="text-xs text-gray-400">Supported formats: PDF, PNG, JPG. Max size 25MB.</p>
                 </div>
              </div>
           </div>
        )}

        {/* Step 2: Analyzing */}
        {step === 'analyzing' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
              <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mb-8 shadow-xl relative">
                 <Loader2 className="w-12 h-12 text-blue-600 animate-spin" />
                 <div className="absolute inset-0 border-4 border-blue-100 rounded-full animate-ping opacity-20"></div>
              </div>
              <h3 className="text-2xl font-bold text-gray-900 mb-2">Analyzing Geometry...</h3>
              <p className="text-gray-500">Extracting dimensions, materials, and calculating volume.</p>
           </div>
        )}

        {/* Step 3: Review Estimate (Side-by-Side) */}
        {step === 'review' && (
           <div className="flex-1 flex flex-col lg:flex-row h-full overflow-hidden bg-gray-100">

              {/* Left: Document Preview (Collapsible on Mobile) */}
              {showPreview && (
                <div className="lg:w-1/2 bg-gray-900 border-r border-gray-800 flex flex-col relative h-[50vh] lg:h-auto">
                   <div className="h-12 bg-gray-950/50 flex items-center justify-between px-4 border-b border-white/5 backdrop-blur-sm shrink-0">
                      <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <FileText className="w-3 h-3" /> Drawing Preview
                      </span>
                      <button onClick={() => setShowPreview(false)} className="lg:hidden text-gray-400"><X className="w-4 h-4"/></button>
                   </div>
                   <div className="flex-1 overflow-auto bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] p-4 flex items-center justify-center">
                     {filePreview && (
                        file?.type === 'application/pdf' ? (
                          <iframe src={filePreview} className="w-full h-full bg-white rounded-lg shadow-2xl" title="Preview" />
                        ) : (
                          <img src={filePreview} alt="Preview" className="max-w-full max-h-full object-contain bg-white rounded-lg shadow-2xl" />
                        )
                     )}
                   </div>
                </div>
              )}

              {/* Right: Estimate Data */}
              <div className="flex-1 flex flex-col bg-gray-50 h-full overflow-hidden relative">

                 {/* Mobile Toggle for Preview */}
                 {!showPreview && (
                    <button 
                      onClick={() => setShowPreview(true)}
                      className="lg:hidden absolute top-4 right-4 z-10 bg-gray-900 text-white p-2 rounded-full shadow-lg"
                    >
                       <Eye className="w-4 h-4" />
                    </button>
                 )}

                 <div className="flex-1 overflow-y-auto p-4 lg:p-8">
                    <div className="max-w-3xl mx-auto space-y-6">

                       <div className="flex items-center justify-between">
                          <button onClick={() => setStep('upload')} className="text-sm text-gray-500 hover:text-gray-900 flex items-center gap-1">
                             <ChevronRight className="w-4 h-4 rotate-180" /> Back to Upload
                          </button>
                          <div className="bg-green-100 text-green-800 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-2">
                             <CheckCircle className="w-3 h-3" /> Analysis Complete
                          </div>
                       </div>

                       {/* Total Cost Card */}
                       <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 flex justify-between items-center bg-gradient-to-r from-blue-600 to-blue-700 text-white">
                          <div>
                             <h2 className="text-lg font-bold">Estimated Cost</h2>
                             <p className="text-xs text-blue-100 opacity-80">Based on geometry & raw material index</p>
                          </div>
                          <div className="text-right">
                             <span className="text-3xl font-bold block">{formatCurrency(totalCost)}</span>
                          </div>
                       </div>

                       {/* Line Items */}
                       <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                          <div className="px-6 py-4 border-b border-gray-100 bg-gray-50/50">
                             <h3 className="font-bold text-gray-800">Detected Items</h3>
                          </div>
                          <div className="divide-y divide-gray-100">
                             {rfqData.lineItems.map((item) => (
                                <div key={item.id} className="p-6 hover:bg-gray-50 transition-colors">
                                   <div className="flex justify-between items-start mb-2">
                                      <div>
                                         <h4 className="font-bold text-gray-900">{item.description}</h4>
                                         <div className="flex items-center gap-2 mt-1">
                                            <span className="text-xs font-mono bg-gray-100 px-1.5 py-0.5 rounded text-gray-600">{item.material}</span>
                                            <span className="text-xs text-gray-400">Qty: {item.quantity}</span>
                                         </div>
                                      </div>
                                      <span className="font-bold text-gray-900">{formatCurrency(item.calculation.totalLineCost)}</span>
                                   </div>
                                   <div className="grid grid-cols-3 gap-2 mt-3 text-xs text-gray-500">
                                      <div className="bg-gray-50 p-2 rounded">
                                         <span className="block text-[10px] uppercase text-gray-400">Dimensions</span>
                                         {item.dimensions.length} x {item.dimensions.width} x {item.dimensions.height} mm
                                      </div>
                                      <div className="bg-gray-50 p-2 rounded">
                                         <span className="block text-[10px] uppercase text-gray-400">Weight</span>
                                         {item.calculation.weightGrams.toFixed(0)} g
                                      </div>
                                      <div className="bg-gray-50 p-2 rounded">
                                         <span className="block text-[10px] uppercase text-gray-400">Vol</span>
                                         {(item.calculation.volumeMm3 / 1000).toFixed(1)} cm³
                                      </div>
                                   </div>
                                </div>
                             ))}
                          </div>
                       </div>

                       {/* Disclaimer */}
                       <div className="bg-amber-50 rounded-xl p-4 flex items-start gap-3 border border-amber-100">
                          <AlertCircle className="w-5 h-5 text-amber-600 mt-0.5 shrink-0" />
                          <p className="text-sm text-amber-800 leading-relaxed">
                             <strong>Preliminary Estimate:</strong> This price is generated by AI based on the visible geometry in your drawing. 
                             Complex features (threads, tight tolerances, surface finishes) may affect the final quote.
                          </p>
                       </div>

                       <div className="h-20"></div> {/* Spacer for bottom bar */}
                    </div>
                 </div>

                 {/* Sticky Action Bar */}
                 <div className="bg-white border-t border-gray-200 p-4 lg:px-8 flex justify-between items-center absolute bottom-0 w-full shadow-[0_-4px_20px_-5px_rgba(0,0,0,0.1)]">
                    <div className="hidden md:block">
                       <p className="text-xs text-gray-500">Ready to proceed?</p>
                       <p className="text-sm font-bold text-gray-900">Submit for formal review</p>
                    </div>
                    <button 
                      onClick={() => setStep('details')}
                      className="bg-gray-900 text-white px-8 py-3 rounded-xl font-bold shadow-lg hover:bg-gray-800 transition-all flex items-center gap-2"
                    >
                       Request Formal Quote <ArrowRight className="w-4 h-4" />
                    </button>
                 </div>
              </div>
           </div>
        )}

        {/* Step 4: Details */}
        {step === 'details' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in slide-in-from-right-4 duration-500">
              <div className="max-w-md w-full">
                <button onClick={() => setStep('review')} className="text-sm text-gray-500 hover:text-gray-900 flex items-center gap-1 mb-6">
                   <ChevronRight className="w-4 h-4 rotate-180" /> Back to Estimate
                </button>

                <div className="bg-white p-8 rounded-2xl shadow-xl border border-gray-200">
                   <h2 className="text-2xl font-bold text-gray-900 mb-6">Finalize Request</h2>
                   <div className="space-y-4">
                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                         <input 
                           type="text" 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                           value={customerDetails.name}
                           onChange={e => setCustomerDetails({...customerDetails, name: e.target.value})}
                           placeholder="Jane Doe"
                         />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Work Email</label>
                         <input 
                           type="email" 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                           value={customerDetails.email}
                           onChange={e => setCustomerDetails({...customerDetails, email: e.target.value})}
                           placeholder="jane@company.com"
                         />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Company Name</label>
                         <input 
                           type="text" 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                           value={customerDetails.company}
                           onChange={e => setCustomerDetails({...customerDetails, company: e.target.value})}
                           placeholder="Acme Industries"
                         />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Project Notes (Optional)</label>
                         <textarea 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none h-24 resize-none"
                           value={customerDetails.notes}
                           onChange={e => setCustomerDetails({...customerDetails, notes: e.target.value})}
                           placeholder="Special tolerances, coating requirements, etc."
                         />
                      </div>

