                                 <label className="absolute -top-2 left-2 bg-white px-1 text-[10px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">RFQ Reference</label>
                                 <input 
                                    value={rfqData.header.rfqNumber}
