  materials: {
    [MaterialType.STEEL_C45]: { id: MaterialType.STEEL_C45, name: 'Steel C45 (1.0503)', density: 7.85, costPerKg: 1.50, lastUpdated: new Date().toISOString() },
    [MaterialType.ALUMINIUM_6061]: { id: MaterialType.ALUMINIUM_6061, name: 'Aluminium 6061', density: 2.70, costPerKg: 2.80, lastUpdated: new Date().toISOString() },
    [MaterialType.STAINLESS_304]: { id: MaterialType.STAINLESS_304, name: 'Stainless Steel 304', density: 8.00, costPerKg: 4.50, lastUpdated: new Date().toISOString() },
    [MaterialType.BRASS]: { id: MaterialType.BRASS, name: 'Brass (CuZn39Pb3)', density: 8.73, costPerKg: 6.00, lastUpdated: new Date().toISOString() },
    [MaterialType.PLASTIC_ABS]: { id: MaterialType.PLASTIC_ABS, name: 'Plastic ABS', density: 1.04, costPerKg: 0.80, lastUpdated: new Date().toISOString() },
  }
};

export const getPricingConfig = (): PricingConfig => {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      return JSON.parse(stored);
    }
  } catch (e) {
    console.error('Failed to load pricing config', e);
  }
  return DEFAULT_PRICING;
};

export const savePricingConfig = (config: PricingConfig): void => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch (e) {
    console.error('Failed to save pricing config', e);
  }
};

import { LineItem, CalculationResult, Dimensions, MaterialType, PricingConfig } from '../types';

/**
 * Calculates physics-based cost and weight.
 * Deterministic: Same input always returns same output.
 * Now accepts a dynamic pricing configuration.
 */
export const calculateLineItem = (
  material: MaterialType,
  dimensions: Dimensions,
  quantity: number,
  config: PricingConfig
): CalculationResult => {
  const materialDef = config.materials[material];

  // Fallbacks if config is missing (safety)
  const density = materialDef ? materialDef.density : 7.85;
  const costPerKg = materialDef ? materialDef.costPerKg : 1.50;
  const markup = config.globalMarkup || 0;

  // Convert Cost/Kg to Cost/Gram
  const costPerGram = costPerKg / 1000;

  // Volume in mm^3
  const volumeMm3 = dimensions.length * dimensions.width * dimensions.height;

  // Convert Volume to cm^3 for weight calc (1 cm^3 = 1000 mm^3)
  const volumeCm3 = volumeMm3 / 1000;

  // Weight in grams
  const weightGrams = volumeCm3 * density;

  // Material Cost per unit (Raw)
  const rawMaterialCostPerUnit = weightGrams * costPerGram;

  // Apply Markup
  const materialCostPerUnit = rawMaterialCostPerUnit * (1 + (markup / 100));

  // Total Line Cost
  const totalLineCost = materialCostPerUnit * quantity;

  return {
    volumeMm3,
    density,
    weightGrams,
    materialCost: materialCostPerUnit,
    totalLineCost
  };
};

export const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(amount);
};

export const formatNumber = (num: number, decimals = 2) => {
  return new Intl.NumberFormat('de-DE', { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(num);
};

