      <aside className="w-64 bg-slate-950 flex flex-col shrink-0 z-20 shadow-xl">
        <div className="h-16 flex items-center px-6 border-b border-slate-800/50 bg-slate-950">
           <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-blue-700 rounded-lg flex items-center justify-center mr-3 shadow-lg shadow-blue-500/20">
             <Calculator className="w-5 h-5 text-white" />
           </div>
           <span className="font-bold text-white text-lg tracking-tight">CostAI</span>
           <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] bg-slate-800 text-slate-400 font-medium">ENT</span>
        </div>

        <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
          <div className="text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2 px-3 mt-2">Platform</div>
          <NavigationButton mode="dashboard" icon={LayoutDashboard} label="Dashboard" />
