        <div className="p-4 border-t border-slate-800/50 bg-slate-900/50">
          <div className="flex items-center gap-3 px-3 py-2 mb-2">
             <div className="w-8 h-8 rounded-full bg-gradient-to-r from-purple-500 to-pink-500 flex items-center justify-center text-white text-xs font-bold">JD</div>
             <div className="flex-1 overflow-hidden">
                <p className="text-sm font-medium text-white truncate">John Doe</p>
                <p className="text-xs text-slate-500 truncate">Senior Estimator</p>
             </div>
          </div>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-2 text-sm text-slate-400 hover:text-white transition-colors">
            <LogOut className="w-4 h-4" /> Sign Out
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-gray-50/50">

        {viewMode === 'dashboard' && (
          <Dashboard 
            quotes={savedQuotes} 
            onNewQuote={startNewQuote}
            onEditQuote={handleEditQuote}
          />
        )}

        {viewMode === 'suppliers' && <Suppliers />}

        {viewMode === 'analytics' && <Analytics />}

        {viewMode === 'demand_intelligence' && <DemandIntelligence />}

        {viewMode === 'settings' && (
          <Settings 
            config={pricingConfig} 
            onUpdateConfig={updatePricingConfig}
            onOpenCustomerPortal={() => {
                setIsAuthenticated(false);
                setIsCustomerMode(true);
            }}
          />
        )}

        {viewMode === 'editor' && (
          <div className="flex-1 flex flex-col h-full relative animate-in fade-in duration-300">

            {/* Glassmorphism Header */}
            <header className="sticky top-0 z-10 bg-white/80 backdrop-blur-md border-b border-gray-200/50 shrink-0 transition-all">
               <div className="flex items-center justify-between px-6 h-16">
