                     <div className="h-6 w-px bg-gray-200"></div>
                     <button 
                       onClick={() => setIsChatOpen(!isChatOpen)}
                       className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all duration-200 ${isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white border border-gray-200 text-gray-700 hover:border-gray-300 hover:shadow-sm'}`}
                     >
                       <Bot className="w-4 h-4" /> {isChatOpen ? 'Copilot Active' : 'AI Copilot'}
                     </button>
                  </div>
               </div>

               {/* Sleek Tabs */}
