  const getStatusStyle = (status: QuoteStatus) => {
    switch(status) {
      case QuoteStatus.APPROVED: return 'border-emerald-500 text-emerald-600 bg-white';
      case QuoteStatus.REVIEW: return 'border-amber-500 text-amber-600 bg-white';
      case QuoteStatus.WIP: return 'border-amber-400 text-amber-500 bg-white'; // Match 'WIP' style from ref
