      default: return 'border-gray-300 text-gray-500 bg-white';
    }
  };

  // Mock data enhancement to match the reference image columns
  const enhancedQuotes = quotes.map((q, idx) => ({
    ...q,
    sNo: 11 + idx, // Continuing from ref image numbering
    partNo: q.partNumber || `Tata-0${idx + 1}`,
    remark: q.remark || (idx % 2 === 0 ? 'Trial for software outcome' : 'POC Trial'),
    template: q.templateRef || (idx % 2 === 0 ? 'gfe' : 'withoutprocess'),
