  return (
    <div className="flex-1 bg-gray-50 flex flex-col h-full animate-in fade-in duration-300">

      {/* Top Header Bar */}
      <div className="h-14 bg-white border-b border-gray-200 flex items-center justify-between px-6 shrink-0">
         <div className="flex items-center gap-4">
            <h1 className="text-lg font-semibold text-gray-800">APQP Master</h1>
         </div>
         <button 
           onClick={onNewQuote}
           className="bg-[#2E74B5] text-white px-4 py-2 rounded text-sm font-medium hover:bg-[#245b8f] flex items-center gap-2 shadow-sm"
         >
           <Plus className="w-4 h-4" /> Add APQP Master
         </button>
      </div>

      {/* Filter Bar */}
      <div className="p-4 flex items-center justify-between gap-4">
         <div className="flex items-center gap-2 flex-1 max-w-lg">
            <span className="text-sm text-gray-600 font-medium">Filter:</span>
            <div className="relative flex-1">
               <input 
                 type="text" 
                 placeholder="Type to filter..." 
                 className="w-full pl-3 pr-10 py-2 border border-gray-300 rounded text-sm focus:border-blue-500 outline-none"
               />
               <Search className="w-4 h-4 text-gray-400 absolute right-3 top-2.5" />
            </div>
         </div>
         <div className="flex items-center gap-2">
            <span className="text-sm text-gray-600">Show:</span>
            <select className="border border-gray-300 rounded py-1.5 px-3 text-sm outline-none">
               <option>10</option>
               <option>25</option>
               <option>50</option>
            </select>
         </div>
      </div>

      {/* Data Table - Matches Reference Image 3 Style */}
      <div className="flex-1 px-4 pb-4 overflow-hidden">
        <div className="bg-white border border-gray-200 rounded-t shadow-sm h-full flex flex-col">

          {/* Table Header - Teal/Blue Background */}
          <div className="grid grid-cols-12 bg-[#1F4E79] text-white text-xs font-semibold py-3 px-4 rounded-t">
             <div className="col-span-1">S. No.</div>
             <div className="col-span-2">APQP Number</div>
             <div className="col-span-1">Part No</div>
             <div className="col-span-2">Location</div>
             <div className="col-span-2">Customers</div>
             <div className="col-span-2">Remark</div>
             <div className="col-span-1 text-center">Status</div>
             <div className="col-span-1 text-center">Action</div>
          </div>

          {/* Table Body */}
          <div className="overflow-y-auto flex-1">
             {enhancedQuotes.map((quote, idx) => (
                <div 
                   key={quote.id} 
                   className="grid grid-cols-12 text-sm py-4 px-4 border-b border-gray-100 items-center hover:bg-blue-50/30 transition-colors"
