                   <div className="col-span-1 text-gray-600">{quote.sNo}</div>

                   <div className="col-span-2 font-medium text-[#2E74B5] cursor-pointer hover:underline" onClick={() => onEditQuote(quote.id)}>
                      {quote.rfqName || quote.partNo.toLowerCase()}
