                   <div className="col-span-1 text-gray-700">{quote.partNo}</div>

                   <div className="col-span-2 text-gray-600">{quote.location}</div>

                   <div className="col-span-2 text-gray-700 uppercase font-medium">{quote.customerName}</div>

                   <div className="col-span-2 text-gray-500 text-xs">{quote.remark}</div>

                   <div className="col-span-1 flex justify-center">
