        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Upload, ArrowRight, CheckCircle, FileText, Loader2, AlertCircle, RefreshCw, Send, ChevronRight, Bot, X, Eye, HelpCircle, MessageSquare, ShieldCheck, FileCheck } from 'lucide-react';
import { extractRFQData } from '../services/geminiService';
import { calculateLineItem, formatCurrency } from '../services/calculationService';
import { logEvent, initSession } from '../services/analyticsService';
import { RFQData, LineItem, MaterialType, PricingConfig } from '../types';
import { INITIAL_HEADER } from '../constants';
import { ChatPanel } from './ChatPanel';

interface CustomerPortalProps {
  config: PricingConfig;
  onBackToLogin: () => void;
}

type Step = 'upload' | 'analyzing' | 'review' | 'details' | 'success' | 'negotiate';

export const CustomerPortal: React.FC<CustomerPortalProps> = ({ config, onBackToLogin }) => {
  const [step, setStep] = useState<Step>('upload');
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [rfqData, setRfqData] = useState<RFQData>({
    header: INITIAL_HEADER,
    lineItems: [],
    comments: [],
    attachments: []
  });
  const [customerDetails, setCustomerDetails] = useState({ name: '', email: '', company: '', notes: '' });
  const [negotiationTopic, setNegotiationTopic] = useState('Price');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [showPreview, setShowPreview] = useState(true);

  // Initialize Analytics Session on Mount
  useEffect(() => {
    initSession();
  }, []);

  // 1. Handle File Upload
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      logEvent('upload_attempt', `Uploaded ${selectedFile.name} (${(selectedFile.size/1024).toFixed(0)}kb)`);
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setStep('analyzing');

      try {
        // Convert to base64
        const reader = new FileReader();
        reader.readAsDataURL(selectedFile);
        reader.onload = async () => {
          const base64Content = (reader.result as string).split(',')[1];
          const extracted = await extractRFQData(base64Content, selectedFile.type);

          // Process Items
          const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
             const material = Object.values(MaterialType).includes(item.material as MaterialType) 
             ? item.material as MaterialType 
             : MaterialType.STEEL_C45;

             const dims = {
                length: item.length || 0,
                width: item.width || 0,
                height: item.height || 0
             };

             return {
               id: `cust-${Date.now()}-${idx}`,
               description: item.description || `Part #${idx + 1}`,
               material,
               quantity: item.quantity || 1,
               unit: item.unit || 'ST',
               dimensions: dims,
               deliveryDate: item.deliveryDate,
               tolerance: item.tolerance,
               calculation: calculateLineItem(material, dims, item.quantity || 1, config)
             };
          });

          setRfqData({
             ...rfqData,
             lineItems: processedItems
          });
          logEvent('view_estimate', 'AI Analysis complete, viewing initial pricing');
          setStep('review');
        };
      } catch (error) {
        console.error(error);
        alert("We couldn't read that file. Please try a clear PDF or Image.");
        setStep('upload');
      }
    }
  };

  const handleMaterialChange = (itemId: string, newMaterial: MaterialType) => {
    logEvent('material_change', `User switched to ${newMaterial}`);
    setRfqData(prev => ({
        ...prev,
        lineItems: prev.lineItems.map(item => {
            if (item.id !== itemId) return item;
            return {
                ...item,
                material: newMaterial,
                calculation: calculateLineItem(newMaterial, item.dimensions, item.quantity, config)
            };
        })
    }));
  };

  const handleQuantityChange = (itemId: string, newQty: number) => {
    if (newQty > 0) {
        logEvent('quantity_change', `Quantity adjusted to ${newQty}`);
        setRfqData(prev => ({
            ...prev,
            lineItems: prev.lineItems.map(item => {
                if (item.id !== itemId) return item;
                return {
                    ...item,
                    quantity: newQty,
                    calculation: calculateLineItem(item.material, item.dimensions, newQty, config)
                };
            })
        }));
    }
  };

  const totalCost = rfqData.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);

  const handleSubmit = () => {
    logEvent('submit_rfq', `Formal RFQ submitted. Value: ${totalCost}`);
    // In a real app, this would POST to an API
    setStep('success');
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans flex flex-col relative">
      {/* Public Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-20 shadow-sm">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
           <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-[#1F4E79] rounded-lg flex items-center justify-center shadow-lg shadow-blue-900/20">
                 <RefreshCw className="w-5 h-5 text-white" />
              </div>
              <div>
                 <h1 className="text-lg font-bold text-gray-900 tracking-tight">Nosta Instant Quote</h1>
              </div>
           </div>

           <div className="flex items-center gap-4">
             {(step === 'review' || step === 'upload') && (
                <button 
                  onClick={() => setIsChatOpen(!isChatOpen)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all ${
                    isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white border border-gray-200 text-gray-700 hover:bg-gray-50'
                  }`}
                >
                  <Bot className="w-4 h-4" /> 
                  {isChatOpen ? 'Copilot Active' : 'Cost Copilot'}
                </button>
             )}
             {step !== 'success' && (
               <button onClick={onBackToLogin} className="text-sm text-gray-500 hover:text-gray-900 font-medium">
                 Nosta Staff Login
               </button>
             )}
           </div>
        </div>
      </header>

      {/* Main Content */}
      <div className={`flex-1 flex flex-col ${step === 'review' ? 'overflow-hidden' : 'overflow-y-auto'}`}>

        {/* Step 1: Upload */}
        {step === 'upload' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
              <div className="max-w-xl w-full text-center">
                 <h2 className="text-4xl font-extrabold text-gray-900 mb-4 tracking-tight">Precision Manufacturing Estimates.</h2>
                 <p className="text-lg text-gray-600 mb-10">Upload your technical drawing. Nosta AI provides an instant, non-binding cost analysis.</p>

                 <div className="bg-white rounded-3xl shadow-xl shadow-gray-200/50 border border-gray-100 p-12 text-center transition-all hover:shadow-2xl">
                    <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Upload className="w-10 h-10 text-[#1F4E79]" />
                    </div>
                    <label className="block mb-6 cursor-pointer group">
                        <input type="file" className="hidden" accept="application/pdf,image/*" onChange={handleFileUpload} />
                        <span className="block w-full py-4 px-6 bg-[#1F4E79] text-white font-bold rounded-xl shadow-lg shadow-blue-900/30 group-hover:bg-[#163a5c] transition-all transform group-active:scale-95">
                          Upload Drawing (PDF/Image)
                        </span>
                    </label>
                    <p className="text-xs text-gray-400">Supported formats: PDF, PNG, JPG. Max size 25MB.</p>
                 </div>
              </div>
           </div>
        )}

        {/* Step 2: Analyzing */}
        {step === 'analyzing' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
              <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mb-8 shadow-xl relative">
                 <Loader2 className="w-12 h-12 text-[#1F4E79] animate-spin" />
                 <div className="absolute inset-0 border-4 border-blue-100 rounded-full animate-ping opacity-20"></div>
              </div>
              <h3 className="text-2xl font-bold text-gray-900 mb-2">Analyzing Geometry...</h3>
              <p className="text-gray-500">Applying Nosta standard cost models and material indices.</p>
           </div>
        )}

        {/* Step 3: Review Estimate (Side-by-Side) */}
        {step === 'review' && (
           <div className="flex-1 flex flex-col lg:flex-row h-full overflow-hidden bg-gray-100">

              {/* Left: Document Preview (Collapsible on Mobile) */}
              {showPreview && (
                <div className="lg:w-1/2 bg-gray-900 border-r border-gray-800 flex flex-col relative h-[50vh] lg:h-auto">
                   <div className="h-12 bg-gray-950/50 flex items-center justify-between px-4 border-b border-white/5 backdrop-blur-sm shrink-0">
                      <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <FileText className="w-3 h-3" /> Drawing Preview
                      </span>
                      <button onClick={() => setShowPreview(false)} className="lg:hidden text-gray-400"><X className="w-4 h-4"/></button>
                   </div>
                   <div className="flex-1 overflow-auto bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] p-4 flex items-center justify-center">
                     {filePreview && (
                        file?.type === 'application/pdf' ? (
                          <iframe src={filePreview} className="w-full h-full bg-white rounded-lg shadow-2xl" title="Preview" />
                        ) : (
                          <img src={filePreview} alt="Preview" className="max-w-full max-h-full object-contain bg-white rounded-lg shadow-2xl" />
                        )
                     )}
                   </div>
                </div>
              )}

              {/* Right: Estimate Data */}
              <div className="flex-1 flex flex-col bg-gray-50 h-full overflow-hidden relative">

                 {/* Mobile Toggle for Preview */}
                 {!showPreview && (
                    <button 
                      onClick={() => setShowPreview(true)}
                      className="lg:hidden absolute top-4 right-4 z-10 bg-gray-900 text-white p-2 rounded-full shadow-lg"
                    >
                       <Eye className="w-4 h-4" />
                    </button>
                 )}

                 <div className="flex-1 overflow-y-auto p-4 lg:p-8">
                    <div className="max-w-3xl mx-auto space-y-6">

                       <div className="flex items-center justify-between">
                          <button onClick={() => setStep('upload')} className="text-sm text-gray-500 hover:text-gray-900 flex items-center gap-1">
                             <ChevronRight className="w-4 h-4 rotate-180" /> Back to Upload
                          </button>
                          <div className="bg-amber-100 text-amber-800 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-2 border border-amber-200">
                             <AlertCircle className="w-3 h-3" /> Non-Binding Instant Estimate
                          </div>
                       </div>

                       {/* Total Cost Card */}
                       <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 flex justify-between items-center bg-gradient-to-r from-[#1F4E79] to-[#2E74B5] text-white">
                          <div>
                             <h2 className="text-lg font-bold">Estimated Production Cost</h2>
                             <p className="text-xs text-blue-100 opacity-80">Subject to engineering validation</p>
                          </div>
                          <div className="text-right">
                             <span className="text-3xl font-bold block">{formatCurrency(totalCost)}</span>
                          </div>
                       </div>

                       {/* Line Items */}
                       <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                          <div className="px-6 py-4 border-b border-gray-100 bg-gray-50/50">
                             <h3 className="font-bold text-gray-800">Detected Geometry</h3>
                          </div>
                          <div className="divide-y divide-gray-100">
                             {rfqData.lineItems.map((item) => (
                                <div key={item.id} className="p-6 hover:bg-gray-50 transition-colors">
                                   <div className="flex justify-between items-start mb-2">
                                      <div>
                                         <h4 className="font-bold text-gray-900">{item.description}</h4>
                                         <div className="flex items-center gap-2 mt-1">
                                            {/* Material Dropdown for Analysis */}
                                            <select 
                                                value={item.material}
                                                onChange={(e) => handleMaterialChange(item.id, e.target.value as MaterialType)}
                                                className="text-xs font-mono bg-blue-50 border border-blue-100 px-1.5 py-0.5 rounded text-blue-800 outline-none cursor-pointer hover:bg-blue-100"
                                            >
                                                {Object.values(MaterialType).map(m => (
                                                    <option key={m} value={m}>{m}</option>
                                                ))}
                                            </select>
                                            <div className="flex items-center gap-1">
                                                <span className="text-xs text-gray-400">Qty:</span>
                                                <input 
                                                    type="number" 
                                                    value={item.quantity}
                                                    onChange={(e) => handleQuantityChange(item.id, parseInt(e.target.value))}
                                                    className="w-12 text-xs border border-gray-200 rounded px-1 py-0.5 text-center"
                                                />
                                            </div>
                                         </div>
                                      </div>
                                      <span className="font-bold text-gray-900">{formatCurrency(item.calculation.totalLineCost)}</span>
                                   </div>
                                   <div className="grid grid-cols-3 gap-2 mt-3 text-xs text-gray-500">
                                      <div className="bg-gray-50 p-2 rounded">
                                         <span className="block text-[10px] uppercase text-gray-400">Dimensions</span>
                                         {item.dimensions.length} x {item.dimensions.width} x {item.dimensions.height} mm
                                      </div>
                                      <div className="bg-gray-50 p-2 rounded">
                                         <span className="block text-[10px] uppercase text-gray-400">Weight</span>
                                         {item.calculation.weightGrams.toFixed(0)} g
                                      </div>
                                      <div className="bg-gray-50 p-2 rounded">
                                         <span className="block text-[10px] uppercase text-gray-400">Vol</span>
                                         {(item.calculation.volumeMm3 / 1000).toFixed(1)} cm³
                                      </div>
                                   </div>
                                </div>
                             ))}
                          </div>
                       </div>

                       {/* Disclaimer */}
                       <div className="bg-gray-50 rounded-xl p-4 flex items-start gap-3 border border-gray-200">
                          <ShieldCheck className="w-5 h-5 text-gray-500 mt-0.5 shrink-0" />
                          <p className="text-sm text-gray-600 leading-relaxed">
                             This instant estimate is directional. Nosta requires a formal engineering review before issuing a binding quote.
                          </p>
                       </div>

                       <div className="h-20"></div> {/* Spacer for bottom bar */}
                    </div>
                 </div>

                 {/* Sticky Action Bar */}
                 <div className="bg-white border-t border-gray-200 p-4 lg:px-8 flex justify-between items-center absolute bottom-0 w-full shadow-[0_-4px_20px_-5px_rgba(0,0,0,0.1)]">
                    <div className="hidden md:block">
                       <p className="text-xs text-gray-500">How would you like to proceed?</p>
                       <p className="text-sm font-bold text-gray-900">Choose your next step</p>
                    </div>
                    <div className="flex gap-3">
                       <button 
                         onClick={() => setStep('negotiate')}
                         className="bg-white border border-gray-300 text-gray-700 px-4 py-3 rounded-xl font-medium hover:bg-gray-50 transition-all flex items-center gap-2 text-sm"
                       >
                         <HelpCircle className="w-4 h-4" /> Raise Issue / Request Recommendation
                       </button>
                       <button 
                         onClick={() => setStep('details')}
                         className="bg-[#1F4E79] text-white px-8 py-3 rounded-xl font-bold shadow-lg hover:bg-[#163a5c] transition-all flex items-center gap-2"
                       >
                          <FileCheck className="w-4 h-4" /> Request Formal Quote
                       </button>
                    </div>
                 </div>
              </div>
           </div>
        )}

        {/* Step 4a: Negotiation / Consultation */}
        {step === 'negotiate' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in slide-in-from-right-4 duration-500">
              <div className="max-w-md w-full">
                <button onClick={() => setStep('review')} className="text-sm text-gray-500 hover:text-gray-900 flex items-center gap-1 mb-6">
                   <ChevronRight className="w-4 h-4 rotate-180" /> Back to Estimate
                </button>

                <div className="bg-white p-8 rounded-2xl shadow-xl border border-gray-200">
                   <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                      <MessageSquare className="w-8 h-8 text-[#1F4E79]" />
                   </div>
                   <h2 className="text-2xl font-bold text-gray-900 mb-2">Technical Consultation</h2>
                   <p className="text-gray-500 mb-6 text-sm">
                     Price target not met? Or need material advice? Our engineering team will review your requirements.
                   </p>

                   <div className="space-y-4">
                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Reason</label>
                         <select 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                           value={negotiationTopic}
                           onChange={e => setNegotiationTopic(e.target.value)}
                         >
                           <option>Target Price Not Met</option>
                           <option>Material Recommendation Needed</option>
                           <option>Lead Time Inquiry</option>
                           <option>Technical Question</option>
                         </select>
                      </div>

                      {!customerDetails.name && (
                         <>
                            <div>
                               <label className="block text-sm font-medium text-gray-700 mb-1">Your Name</label>
                               <input 
                                 type="text" 
                                 className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                 value={customerDetails.name}
                                 onChange={e => setCustomerDetails({...customerDetails, name: e.target.value})}
                                 placeholder="Jane Doe"
                               />
                            </div>
                            <div>
                               <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                               <input 
                                 type="email" 
                                 className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                 value={customerDetails.email}
                                 onChange={e => setCustomerDetails({...customerDetails, email: e.target.value})}
                                 placeholder="jane@company.com"
                               />
                            </div>
                         </>
                      )}

                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Message</label>
                         <textarea 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none h-32 resize-none"
                           value={customerDetails.notes}
                           onChange={e => setCustomerDetails({...customerDetails, notes: e.target.value})}
                           placeholder="Describe your requirement..."
                         />
                      </div>

                      <button 
                         onClick={handleSubmit}
                         disabled={!customerDetails.name && !customerDetails.email}
                         className="w-full bg-[#1F4E79] text-white py-3 rounded-xl font-bold shadow-lg hover:bg-[#163a5c] transition-all flex items-center justify-center gap-2 mt-2 disabled:opacity-50"
                      >
                         <Send className="w-4 h-4" /> Send to Engineering
                      </button>
                   </div>
                </div>
              </div>
           </div>
        )}

        {/* Step 4b: Formal Quote Request */}
        {step === 'details' && (
