                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                           value={customerDetails.email}
                           onChange={e => setCustomerDetails({...customerDetails, email: e.target.value})}
                           placeholder="jane@company.com"
                         />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Company Name</label>
                         <input 
                           type="text" 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                           value={customerDetails.company}
                           onChange={e => setCustomerDetails({...customerDetails, company: e.target.value})}
                           placeholder="Acme Industries"
                         />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">Project Notes / Tolerances</label>
                         <textarea 
                           className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none h-24 resize-none"
                           value={customerDetails.notes}
                           onChange={e => setCustomerDetails({...customerDetails, notes: e.target.value})}
                           placeholder="Specific standard requirements, surface finish..."
                         />
                      </div>

                      <button 
                         onClick={handleSubmit}
                         disabled={!customerDetails.name || !customerDetails.email}
                         className="w-full bg-[#1F4E79] text-white py-4 rounded-xl font-bold shadow-lg hover:bg-[#163a5c] transition-all flex items-center justify-center gap-2 mt-4 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                         <Send className="w-4 h-4" /> Submit for Formal Review
                      </button>
                   </div>
                </div>
              </div>
           </div>
        )}

        {/* Step 5: Success */}
        {step === 'success' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 text-center animate-in zoom-in duration-500">
              <div className="max-w-lg w-full">
                <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-8">
                   <CheckCircle className="w-12 h-12 text-green-600" />
                </div>
                <h2 className="text-3xl font-extrabold text-gray-900 mb-4">Request Submitted!</h2>
                <p className="text-gray-600 text-lg mb-8">
                   Thank you, {customerDetails.name}. Your request <strong>#REQ-{Math.floor(Math.random() * 10000)}</strong> is now with Nosta Engineering. 
                   <br/>A formal quote will be issued to <strong>{customerDetails.email}</strong> within 24 hours.
                </p>
                <div className="bg-white p-6 rounded-xl border border-gray-200 mb-8 text-left">
                   <h4 className="font-bold text-gray-900 mb-2">Next Steps:</h4>
                   <ul className="space-y-2 text-sm text-gray-600">
                      <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div> Engineering Validation (DFM)</li>
                      <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-gray-300"></div> Formal Pricing & Lead Time Commitment</li>
                   </ul>
                </div>
                <button onClick={() => window.location.reload()} className="text-[#1F4E79] font-medium hover:underline">
                   Start Another Quote
                </button>
              </div>
           </div>
        )}

      </div>

      {/* Floating Chat Panel */}
      {isChatOpen && (
        <div className="fixed bottom-4 right-4 z-50 h-[600px] w-full max-w-[400px] animate-in slide-in-from-bottom-4 duration-300 shadow-2xl rounded-2xl overflow-hidden">
          <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
        </div>
      )}

      {/* Simple Footer (only visible in non-review steps to maximize space in review) */}
      {step !== 'review' && (
        <footer className="py-6 text-center text-xs text-gray-400 border-t border-gray-200 shrink-0">
           &copy; 2024 Nosta Precision. All rights reserved.
        </footer>
      )}
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
