      currency: 'EUR',
      currencyDisplay: 'symbol',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
    // This will ensure the Euro symbol comes first with a non-breaking space
    return `€\u00A0${formatter
      .format(amount || 0)
      .replace(/[^\d,.-]/g, '')
      .trim()}`;
