  { id: '1', author: 'Procurement Mgr', text: 'Please double check the steel grade tolerances.', timestamp: '2024-10-21 10:30', type: 'internal' },
  { id: '2', author: 'Supplier Rep', text: 'Can we substitute SS 304 for 316 on line 2?', timestamp: '2024-10-21 11:15', type: 'supplier' },
];

const MOCK_ATTACHMENTS: Attachment[] = [
  { id: '1', name: 'Technical_Drawing_v2.pdf', size: '2.4 MB', type: 'pdf', uploadDate: '2024-10-18' },
  { id: '2', name: 'Spec_Sheet_A.pdf', size: '1.1 MB', type: 'pdf', uploadDate: '2024-10-18' },
];

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isCustomerMode, setIsCustomerMode] = useState(false);

  // Navigation State
  const [viewMode, setViewMode] = useState<ViewMode>('dashboard');
  const [editorMode, setEditorMode] = useState<EditorMode>('upload');
  const [activeTab, setActiveTab] = useState<'items' | 'collaboration' | 'documents'>('items');
  const [itemViewMode, setItemViewMode] = useState<'list' | 'table'>('list');

  // Data State
  const [pricingConfig, setPricingConfig] = useState<PricingConfig>(getPricingConfig());
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [rfqData, setRfqData] = useState<RFQData>({ 
    header: INITIAL_HEADER, 
    lineItems: [],
    comments: [],
    attachments: []
  });
  const [savedQuotes, setSavedQuotes] = useState<SavedQuote[]>(MOCK_QUOTES);
  const [currentStatus, setCurrentStatus] = useState<QuoteStatus>(QuoteStatus.DRAFT);

  // UI State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [newComment, setNewComment] = useState('');

  // Calculate total
  const totalCost = rfqData.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);

  // --- Actions ---

  const handleLogin = () => setIsAuthenticated(true);
  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsCustomerMode(false);
  }

  const handleCustomerEnter = () => {
    setIsCustomerMode(true);
  }

  const handleBackToLogin = () => {
    setIsCustomerMode(false);
    setIsAuthenticated(false);
  }

  // Update configuration and recalculate current items if necessary
  const updatePricingConfig = (newConfig: PricingConfig) => {
    setPricingConfig(newConfig);
    savePricingConfig(newConfig);

    // Recalculate existing items with new prices
    if (rfqData.lineItems.length > 0) {
      setRfqData(prev => ({
        ...prev,
        lineItems: prev.lineItems.map(item => ({
          ...item,
          calculation: calculateLineItem(item.material, item.dimensions, item.quantity, newConfig)
        }))
      }));
    }
  };

  const startNewQuote = () => {
    setRfqData({ header: INITIAL_HEADER, lineItems: [], comments: [], attachments: [] });
    setFile(null);
    setFilePreview(null);
    setEditorMode('upload');
    setCurrentStatus(QuoteStatus.DRAFT);
    setViewMode('editor');
    setIsChatOpen(false);
  };

  const handleEditQuote = (id: string) => {
    const quote = savedQuotes.find(q => q.id === id);
    if (quote) {
       setRfqData({
         header: quote,
         lineItems: [], // In real app, load items
         comments: MOCK_COMMENTS,
         attachments: MOCK_ATTACHMENTS
       });
       setCurrentStatus(quote.status);
       setEditorMode('verify');
       setViewMode('editor');
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setIsProcessing(true);

      try {
        const base64Data = await fileToBase64(selectedFile);
        const base64Content = base64Data.split(',')[1];

        const extracted = await extractRFQData(base64Content, selectedFile.type);

        const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
          const material = Object.values(MaterialType).includes(item.material as MaterialType) 
            ? item.material as MaterialType 
            : MaterialType.STEEL_C45;

          const dims = {
             length: item.length || 0,
             width: item.width || 0,
             height: item.height || 0
          };

          return {
            id: `item-${Date.now()}-${idx}`,
            description: item.description || `Item ${idx + 1}`,
            material,
            quantity: item.quantity || 1,
            unit: item.unit || 'ST',
            dimensions: dims,
            deliveryDate: item.deliveryDate || '',
            tolerance: item.tolerance,
            calculation: calculateLineItem(material, dims, item.quantity || 1, pricingConfig)
          };
        });

        setRfqData(prev => ({
          ...prev,
          header: {
            ...INITIAL_HEADER,
            customerName: extracted.customerName || '',
            rfqNumber: extracted.rfqNumber || '',
            documentDate: extracted.documentDate || new Date().toISOString().split('T')[0]
          },
          lineItems: processedItems,
          attachments: [...prev.attachments, {
             id: Date.now().toString(),
             name: selectedFile.name,
             size: `${(selectedFile.size / 1024 / 1024).toFixed(2)} MB`,
             type: 'pdf',
             uploadDate: new Date().toLocaleDateString()
          }]
        }));

        setEditorMode('verify');
      } catch (err) {
        console.error(err);
        alert("Failed to process document. Please try again.");
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const handleLineItemChange = useCallback((id: string, field: string, value: any) => {
    setRfqData(prev => {
      const newItems = prev.lineItems.map(item => {
        if (item.id !== id) return item;
        const updated = { ...item };

        if (field.startsWith('dimensions.')) {
          const dimKey = field.split('.')[1] as keyof typeof updated.dimensions;
          updated.dimensions = { ...updated.dimensions, [dimKey]: value };
        } else if (field === 'material') {
           updated.material = value as MaterialType;
        } else if (field === 'quantity') {
           updated.quantity = value;
        } else {
          (updated as any)[field] = value;
        }

        updated.calculation = calculateLineItem(updated.material, updated.dimensions, updated.quantity, pricingConfig);
        return updated;
      });
      return { ...prev, lineItems: newItems };
    });
  }, [pricingConfig]);

  const handleDeleteItem = (id: string) => {
    setRfqData(prev => ({
      ...prev,
      lineItems: prev.lineItems.filter(item => item.id !== id)
    }));
  };

  const handleAddManualItem = () => {
    const newItem: LineItem = {
      id: `manual-${Date.now()}`,
      description: 'New Manual Item',
      material: MaterialType.STEEL_C45,
      quantity: 1,
      unit: 'ST',
      dimensions: { length: 0, width: 0, height: 0 },
      calculation: calculateLineItem(MaterialType.STEEL_C45, { length: 0, width: 0, height: 0 }, 1, pricingConfig)
    };
    setRfqData(prev => ({ ...prev, lineItems: [...prev.lineItems, newItem] }));
    if (editorMode === 'upload') setEditorMode('verify');
  };

  const handleSaveQuote = (header: typeof INITIAL_HEADER) => {
    const newQuote: SavedQuote = {
      ...header,
      id: `q-${Date.now()}`,
      status: currentStatus,
      totalValue: totalCost,
      lastModified: new Date().toISOString()
    };
    setSavedQuotes(prev => [newQuote, ...prev]);
    setIsModalOpen(false);
    setViewMode('dashboard');
  };

  const handleExportPDF = () => {
    generateQuotePDF(rfqData);
  };

  const advanceWorkflow = () => {
     if (currentStatus === QuoteStatus.DRAFT) setCurrentStatus(QuoteStatus.REVIEW);
     else if (currentStatus === QuoteStatus.REVIEW) setCurrentStatus(QuoteStatus.APPROVED);
     else if (currentStatus === QuoteStatus.APPROVED) setCurrentStatus(QuoteStatus.SENT);
  };

  const addComment = () => {
    if (!newComment.trim()) return;
    setRfqData(prev => ({
      ...prev,
      comments: [...prev.comments, {
        id: Date.now().toString(),
        author: 'You',
        text: newComment,
        timestamp: new Date().toLocaleString(),
        type: 'internal'
      }]
    }));
    setNewComment('');
  };

  const NavigationButton = ({ mode, icon: Icon, label }: { mode: ViewMode, icon: any, label: string }) => {
    const isActive = viewMode === mode;
    return (
      <button 
        onClick={() => {
           if (mode === 'editor' && editorMode === 'upload' && rfqData.lineItems.length > 0) setEditorMode('verify');
           setViewMode(mode);
        }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 group ${
          isActive 
            ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' 
            : 'text-slate-400 hover:bg-white/5 hover:text-white'
        }`}
      >
        <Icon className={`w-5 h-5 transition-transform group-hover:scale-110 ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-white'}`} />
        <span className="font-medium text-sm">{label}</span>
      </button>
    );
  };

  // --- Render ---

  // 1. Customer Mode
  if (isCustomerMode) {
     return <CustomerPortal config={pricingConfig} onBackToLogin={handleBackToLogin} />;
  }

  // 2. Login Screen
  if (!isAuthenticated) {
     return <Login onLogin={handleLogin} onCustomerEnter={handleCustomerEnter} />;
  }

  // 3. Employee Dashboard
  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans overflow-hidden selection:bg-blue-100 selection:text-blue-900">

      {/* Modern Sidebar */}
      <aside className="w-[280px] bg-[#0F172A] flex flex-col shrink-0 z-30 transition-all duration-300 relative border-r border-white/5">
        {/* Subtle texture or gradient overlay */}
        <div className="absolute top-0 left-0 w-full h-96 bg-gradient-to-b from-blue-600/5 to-transparent pointer-events-none"></div>

        <div className="h-24 flex items-center px-8 relative z-10">
           <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center mr-3 shadow-lg shadow-blue-500/20 ring-1 ring-white/10">
             <Calculator className="w-5 h-5 text-white" />
           </div>
           <div>
             <span className="font-bold text-white text-lg tracking-tight block">CostAI</span>
             <span className="text-[10px] text-blue-300/80 font-semibold tracking-wider uppercase">Enterprise</span>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-8 overflow-y-auto py-4 scrollbar-none relative z-10">
          <div>
            <div className="px-4 mb-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">Platform</div>
            <div className="space-y-1">
              <NavigationButton mode="dashboard" icon={LayoutDashboard} label="Dashboard" />
              <NavigationButton mode="editor" icon={FileText} label="Active Quote" />
            </div>
          </div>

          <div>
            <div className="px-4 mb-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">Intelligence</div>
            <div className="space-y-1">
              <NavigationButton mode="analytics" icon={BarChart2} label="Analytics" />
              <NavigationButton mode="demand_intelligence" icon={Radar} label="Demand Intel" />
            </div>
          </div>

          <div>
            <div className="px-4 mb-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">Management</div>
            <div className="space-y-1">
              <NavigationButton mode="suppliers" icon={Users} label="Suppliers" />
              <NavigationButton mode="settings" icon={SettingsIcon} label="Settings" />
            </div>
          </div>
        </nav>

        <div className="p-6 border-t border-white/5 bg-[#0B1120] relative z-10">
          <div className="flex items-center gap-4 group cursor-pointer">
             <div className="w-10 h-10 rounded-full p-[2px] bg-gradient-to-r from-blue-500 to-purple-500">
               <div className="w-full h-full rounded-full bg-[#0B1120] flex items-center justify-center border-2 border-[#0B1120]">
                  <span className="text-white text-xs font-bold">JD</span>
               </div>
             </div>
             <div className="flex-1 overflow-hidden">
                <p className="text-sm font-semibold text-white group-hover:text-blue-400 transition-colors truncate">John Doe</p>
                <p className="text-xs text-slate-500 truncate">Senior Estimator</p>
             </div>
             <button onClick={handleLogout} className="text-slate-500 hover:text-white transition-colors p-2 hover:bg-white/5 rounded-lg">
                <LogOut className="w-4 h-4" />
             </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-[#F8FAFC]">

        {viewMode === 'dashboard' && (
          <Dashboard 
            quotes={savedQuotes} 
            onNewQuote={startNewQuote}
            onEditQuote={handleEditQuote}
          />
        )}

        {viewMode === 'suppliers' && <Suppliers />}

        {viewMode === 'analytics' && <Analytics />}

        {viewMode === 'demand_intelligence' && <DemandIntelligence />}

        {viewMode === 'settings' && (
          <Settings 
            config={pricingConfig} 
            onUpdateConfig={updatePricingConfig}
            onOpenCustomerPortal={() => {
                setIsAuthenticated(false);
                setIsCustomerMode(true);
            }}
          />
        )}

        {viewMode === 'editor' && (
          <div className="flex-1 flex flex-col h-full relative animate-in fade-in duration-300">

            {/* Glassmorphism Header */}
            <header className="sticky top-0 z-10 bg-white/80 backdrop-blur-xl border-b border-gray-200/60 shrink-0 transition-all">
               <div className="flex items-center justify-between px-8 h-20">
                  <div className="flex items-center gap-6">
                    <button onClick={() => setViewMode('dashboard')} className="hover:bg-gray-100 p-2.5 rounded-xl transition-colors text-gray-500 group">
                      <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
                    </button>
                    <div className="h-8 w-px bg-gray-200"></div>
                    <div>
                      <h2 className="font-bold text-gray-900 text-xl leading-tight tracking-tight">
                        {rfqData.header.rfqNumber || 'New Cost Estimate'}
                      </h2>
                      <p className="text-xs font-medium text-gray-500 mt-0.5">{rfqData.header.customerName || 'Draft Quote'}</p>
                    </div>
                  </div>

                  {/* Modern Workflow Stepper */}
                  {editorMode === 'verify' && (
                     <div className="hidden lg:flex items-center bg-gray-100/50 p-1.5 rounded-full border border-gray-200/50">
                        {[QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].map((step, idx) => {
                           const isActive = step === currentStatus;
                           const isPast = [QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].indexOf(currentStatus) > idx;
                           return (
                              <div key={step} className="flex items-center">
                                 <div className={`flex items-center gap-2 px-5 py-2 rounded-full text-xs font-bold transition-all duration-300 ${
                                    isActive ? 'bg-white text-blue-700 shadow-sm ring-1 ring-black/5' : 
                                    isPast ? 'text-green-600' : 'text-gray-400'
                                 }`}>
                                    {isPast && <CheckCircle className="w-3.5 h-3.5" />}
                                    {isActive && <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />}
                                    {step}
                                 </div>
                              </div>
                           );
                        })}
                     </div>
                  )}

                  <div className="flex items-center gap-4">
                     <button 
                       onClick={handleExportPDF}
                       className="p-2.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl relative transition-all"
                       title="Export PDF"
                     >
                        <FileDown className="w-5 h-5" />
                     </button>
                     <div className="h-8 w-px bg-gray-200"></div>
                     <button 
                       onClick={() => setIsChatOpen(!isChatOpen)}
                       className={`flex items-center gap-2.5 px-5 py-2.5 rounded-xl text-sm font-bold transition-all duration-200 ${isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30 ring-2 ring-blue-600 ring-offset-2' : 'bg-white border border-gray-200 text-gray-700 hover:border-gray-300 hover:shadow-sm'}`}
                     >
                       <Bot className="w-4 h-4" /> {isChatOpen ? 'Copilot Active' : 'AI Copilot'}
                     </button>
                  </div>
               </div>

               {/* Sleek Tabs */}
               {editorMode === 'verify' && (
                  <div className="px-8 flex gap-8 border-t border-gray-100 bg-white/50 backdrop-blur-sm">
                     {[
                        { id: 'items', label: 'Line Items', count: rfqData.lineItems.length },
                        { id: 'collaboration', label: 'Collaboration', count: rfqData.comments.length },
                        { id: 'documents', label: 'Documents', count: rfqData.attachments.length }
                     ].map((tab) => (
                       <button 
                          key={tab.id}
                          onClick={() => setActiveTab(tab.id as any)}
                          className={`relative py-4 text-sm font-medium transition-all flex items-center gap-2.5 ${activeTab === tab.id ? 'text-blue-600' : 'text-gray-500 hover:text-gray-800'}`}
                       >
                          {tab.label}
                          {tab.count > 0 && (
                            <span className={`px-2 py-0.5 rounded-md text-[10px] font-bold ${activeTab === tab.id ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'}`}>
                              {tab.count}
                            </span>
                          )}
                          {activeTab === tab.id && (
                             <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-t-full layout-id-underline shadow-[0_-2px_10px_rgba(37,99,235,0.5)]"></span>
                          )}
                       </button>
                     ))}
                  </div>
               )}
            </header>

            {/* Editor Content */}
            <div className="flex-1 flex overflow-hidden relative">

              {editorMode === 'upload' ? (
                 <div className="w-full h-full flex items-center justify-center bg-gradient-to-b from-[#F8FAFC] to-gray-50 p-8">
                    <div className="max-w-xl w-full bg-white/80 backdrop-blur-sm rounded-[2rem] shadow-2xl shadow-blue-900/5 p-12 border border-white/20 text-center hover:shadow-3xl transition-shadow duration-500 ring-1 ring-black/5">
                        <div className="w-24 h-24 bg-gradient-to-tr from-blue-50 to-indigo-50 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner ring-1 ring-black/5">
                          <Upload className="w-10 h-10 text-blue-600" />
                        </div>
                        <h3 className="text-3xl font-extrabold text-gray-900 mb-3 tracking-tight">Upload RFQ Document</h3>
                        <p className="text-gray-500 mb-10 leading-relaxed text-lg">Drag and drop your engineering drawings (PDF/Images) here. Our AI will extract specs, materials, and quantities instantly.</p>

                        <div className="flex flex-col gap-4">
                          <label className="relative group">
                            <input 
                              type="file" 
                              accept="image/*,application/pdf"
                              onChange={handleFileUpload}
                              className="hidden"
                              disabled={isProcessing}
                            />
                            <span className={`w-full block cursor-pointer px-8 py-5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-blue-500/30 hover:shadow-blue-500/50 hover:-translate-y-0.5 transition-all ${isProcessing ? 'opacity-75' : ''}`}>
                              {isProcessing ? (
                                <span className="flex items-center justify-center gap-3"><div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"/> Processing...</span>
                              ) : 'Select Document'}
                            </span>
                          </label>
                          <button onClick={handleAddManualItem} className="w-full px-8 py-5 bg-white text-gray-700 font-bold rounded-2xl border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-colors shadow-sm">
                            Continue without File
                          </button>
                        </div>
                    </div>
                 </div>
              ) : (
                <>
                  {/* Document Preview Panel */}
                  <div className="hidden lg:flex w-[40%] bg-[#0B1120] border-r border-gray-800 flex-col min-w-[400px] shadow-2xl z-10">
                    <div className="h-16 bg-[#0F172A]/80 backdrop-blur-md flex items-center justify-between px-6 border-b border-white/5">
                       <span className="text-xs font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
                         <FileText className="w-4 h-4 text-blue-500" /> Source Preview
                       </span>
                       <div className="flex gap-2">
                          <button className="p-2 text-gray-400 hover:text-white rounded-lg hover:bg-white/10 transition-colors"><Download className="w-4 h-4" /></button>
                       </div>
                    </div>
                    <div className="flex-1 overflow-auto flex items-center justify-center p-8 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
                      <div className="relative shadow-2xl shadow-black/80 rounded-xl overflow-hidden transition-transform hover:scale-[1.01] duration-300 ring-1 ring-white/10">
                        {file?.type === 'application/pdf' ? (
                          <iframe src={filePreview || ''} className="w-full h-[800px] bg-white" title="PDF Preview" />
                        ) : (
                          <img src={filePreview || ''} alt="RFQ Document" className="max-w-full max-h-[80vh] object-contain bg-white" />
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Form & Workspace */}
                  <div className="flex-1 flex flex-col bg-white min-w-[400px]">

                    {/* Items View */}
                    {activeTab === 'items' && (
                       <>
                        {/* Quote Details Bar */}
                        <div className="px-10 py-8 border-b border-gray-100 bg-white">
                           <div className="grid grid-cols-2 gap-12">
                              <div className="group relative">
                                 <label className="absolute -top-2.5 left-4 bg-white px-2 text-[11px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">Customer Name</label>
                                 <input 
                                    value={rfqData.header.customerName}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, customerName: e.target.value}}))}
                                    className="w-full text-xl font-bold text-gray-800 border border-gray-200 rounded-xl px-6 py-4 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all placeholder-gray-300" 
                                    placeholder="Enter Client Name"
                                 />
                              </div>
                              <div className="group relative">
                                 <label className="absolute -top-2.5 left-4 bg-white px-2 text-[11px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">RFQ Reference</label>
                                 <input 
                                    value={rfqData.header.rfqNumber}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, rfqNumber: e.target.value}}))}
                                    className="w-full text-xl font-mono font-medium text-gray-800 border border-gray-200 rounded-xl px-6 py-4 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all placeholder-gray-300" 
                                    placeholder="RFQ-0000"
                                 />
                              </div>
                           </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-10 bg-gray-50/50 space-y-6">
                           <div className="flex justify-between items-end mb-2">
                              <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider pl-1 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-blue-500"></span> Line Items
                              </h3>
                              <div className="flex gap-4 items-center">
                                {/* View Toggle */}
                                <div className="bg-white border border-gray-200 rounded-xl p-1 flex shadow-sm">
                                  <button 
                                    onClick={() => setItemViewMode('list')}
                                    className={`p-2 rounded-lg transition-all ${itemViewMode === 'list' ? 'bg-gray-100 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                                  >
                                    <LayoutList className="w-4 h-4" />
                                  </button>
                                  <button 
                                    onClick={() => setItemViewMode('table')}
                                    className={`p-2 rounded-lg transition-all ${itemViewMode === 'table' ? 'bg-gray-100 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                                  >
                                    <TableIcon className="w-4 h-4" />
                                  </button>
                                </div>
                                <div className="h-6 w-px bg-gray-200"></div>
