                             <div className="border-2 border-dashed border-gray-300 rounded-2xl flex flex-col items-center justify-center p-10 text-gray-400 hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50/50 transition-all cursor-pointer bg-white/50 group min-h-[200px]">
                                <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center mb-4 group-hover:bg-blue-100 transition-colors">
                                  <Plus className="w-6 h-6" />
                                </div>
                                <span className="text-sm font-bold">Add Document</span>
                                <span className="text-xs text-gray-400 mt-1">PDF, Excel, Images</span>
                             </div>
                          </div>
                       </div>
                    )}

                  </div>
                </>
              )}

              {/* Overlay AI Panel */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

