                           return (
                              <div key={step} className="flex items-center">
                                 <div className={`flex items-center gap-2 px-5 py-2 rounded-full text-xs font-bold transition-all duration-300 ${
                                    isActive ? 'bg-white text-blue-700 shadow-sm ring-1 ring-black/5' : 
                                    isPast ? 'text-green-600' : 'text-gray-400'
                                 }`}>
                                    {isPast && <CheckCircle className="w-3.5 h-3.5" />}
                                    {isActive && <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />}
                                    {step}
                                 </div>
                              </div>
                           );
                        })}
                     </div>
                  )}

                  <div className="flex items-center gap-4">
                     <button 
                       onClick={handleExportPDF}
                       className="p-2.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl relative transition-all"
                       title="Export PDF"
                     >
                        <FileDown className="w-5 h-5" />
                     </button>
                     <div className="h-8 w-px bg-gray-200"></div>
                     <button 
                       onClick={() => setIsChatOpen(!isChatOpen)}
                       className={`flex items-center gap-2.5 px-5 py-2.5 rounded-xl text-sm font-bold transition-all duration-200 ${isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30 ring-2 ring-blue-600 ring-offset-2' : 'bg-white border border-gray-200 text-gray-700 hover:border-gray-300 hover:shadow-sm'}`}
                     >
                       <Bot className="w-4 h-4" /> {isChatOpen ? 'Copilot Active' : 'AI Copilot'}
                     </button>
                  </div>
               </div>

               {/* Sleek Tabs */}
               {editorMode === 'verify' && (
                  <div className="px-8 flex gap-8 border-t border-gray-100 bg-white/50 backdrop-blur-sm">
                     {[
                        { id: 'items', label: 'Line Items', count: rfqData.lineItems.length },
                        { id: 'collaboration', label: 'Collaboration', count: rfqData.comments.length },
                        { id: 'documents', label: 'Documents', count: rfqData.attachments.length }
                     ].map((tab) => (
                       <button 
                          key={tab.id}
                          onClick={() => setActiveTab(tab.id as any)}
                          className={`relative py-4 text-sm font-medium transition-all flex items-center gap-2.5 ${activeTab === tab.id ? 'text-blue-600' : 'text-gray-500 hover:text-gray-800'}`}
                       >
                          {tab.label}
                          {tab.count > 0 && (
                            <span className={`px-2 py-0.5 rounded-md text-[10px] font-bold ${activeTab === tab.id ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'}`}>
                              {tab.count}
                            </span>
                          )}
                          {activeTab === tab.id && (
                             <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-t-full layout-id-underline shadow-[0_-2px_10px_rgba(37,99,235,0.5)]"></span>
                          )}
                       </button>
                     ))}
                  </div>
               )}
            </header>

            {/* Editor Content */}
            <div className="flex-1 flex overflow-hidden relative">

              {editorMode === 'upload' ? (
                 <div className="w-full h-full flex items-center justify-center bg-gradient-to-b from-[#F8FAFC] to-gray-50 p-8">
                    <div className="max-w-xl w-full bg-white/80 backdrop-blur-sm rounded-[2rem] shadow-2xl shadow-blue-900/5 p-12 border border-white/20 text-center hover:shadow-3xl transition-shadow duration-500 ring-1 ring-black/5">
                        <div className="w-24 h-24 bg-gradient-to-tr from-blue-50 to-indigo-50 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner ring-1 ring-black/5">
                          <Upload className="w-10 h-10 text-blue-600" />
                        </div>
                        <h3 className="text-3xl font-extrabold text-gray-900 mb-3 tracking-tight">Upload RFQ Document</h3>
                        <p className="text-gray-500 mb-10 leading-relaxed text-lg">Drag and drop your engineering drawings (PDF/Images) here. Our AI will extract specs, materials, and quantities instantly.</p>

                        <div className="flex flex-col gap-4">
                          <label className="relative group">
                            <input 
                              type="file" 
                              accept="image/*,application/pdf"
                              onChange={handleFileUpload}
                              className="hidden"
                              disabled={isProcessing}
                            />
                            <span className={`w-full block cursor-pointer px-8 py-5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-blue-500/30 hover:shadow-blue-500/50 hover:-translate-y-0.5 transition-all ${isProcessing ? 'opacity-75' : ''}`}>
                              {isProcessing ? (
                                <span className="flex items-center justify-center gap-3"><div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"/> Processing...</span>
                              ) : 'Select Document'}
                            </span>
                          </label>
                          <button onClick={handleAddManualItem} className="w-full px-8 py-5 bg-white text-gray-700 font-bold rounded-2xl border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-colors shadow-sm">
                            Continue without File
                          </button>
                        </div>
                    </div>
                 </div>
              ) : (
                <>
                  {/* Document Preview Panel */}
                  <div className="hidden lg:flex w-[40%] bg-[#0B1120] border-r border-gray-800 flex-col min-w-[400px] shadow-2xl z-10">
                    <div className="h-16 bg-[#0F172A]/80 backdrop-blur-md flex items-center justify-between px-6 border-b border-white/5">
                       <span className="text-xs font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
                         <FileText className="w-4 h-4 text-blue-500" /> Source Preview
                       </span>
                       <div className="flex gap-2">
                          <button className="p-2 text-gray-400 hover:text-white rounded-lg hover:bg-white/10 transition-colors"><Download className="w-4 h-4" /></button>
                       </div>
                    </div>
                    <div className="flex-1 overflow-auto flex items-center justify-center p-8 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
                      <div className="relative shadow-2xl shadow-black/80 rounded-xl overflow-hidden transition-transform hover:scale-[1.01] duration-300 ring-1 ring-white/10">
                        {file?.type === 'application/pdf' ? (
                          <iframe src={filePreview || ''} className="w-full h-[800px] bg-white" title="PDF Preview" />
                        ) : (
                          <img src={filePreview || ''} alt="RFQ Document" className="max-w-full max-h-[80vh] object-contain bg-white" />
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Form & Workspace */}
                  <div className="flex-1 flex flex-col bg-white min-w-[400px]">

                    {/* Items View */}
                    {activeTab === 'items' && (
                       <>
                        {/* Quote Details Bar */}
                        <div className="px-10 py-8 border-b border-gray-100 bg-white">
                           <div className="grid grid-cols-2 gap-12">
                              <div className="group relative">
                                 <label className="absolute -top-2.5 left-4 bg-white px-2 text-[11px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">Customer Name</label>
                                 <input 
                                    value={rfqData.header.customerName}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, customerName: e.target.value}}))}
                                    className="w-full text-xl font-bold text-gray-800 border border-gray-200 rounded-xl px-6 py-4 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all placeholder-gray-300" 
                                    placeholder="Enter Client Name"
                                 />
                              </div>
                              <div className="group relative">
                                 <label className="absolute -top-2.5 left-4 bg-white px-2 text-[11px] font-bold text-gray-400 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">RFQ Reference</label>
                                 <input 
                                    value={rfqData.header.rfqNumber}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, rfqNumber: e.target.value}}))}
                                    className="w-full text-xl font-mono font-medium text-gray-800 border border-gray-200 rounded-xl px-6 py-4 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all placeholder-gray-300" 
                                    placeholder="RFQ-0000"
                                 />
                              </div>
                           </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-10 bg-gray-50/50 space-y-6">
                           <div className="flex justify-between items-end mb-2">
                              <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider pl-1 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-blue-500"></span> Line Items
                              </h3>
                              <div className="flex gap-4 items-center">
                                {/* View Toggle */}
                                <div className="bg-white border border-gray-200 rounded-xl p-1 flex shadow-sm">
                                  <button 
                                    onClick={() => setItemViewMode('list')}
                                    className={`p-2 rounded-lg transition-all ${itemViewMode === 'list' ? 'bg-gray-100 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                                  >
                                    <LayoutList className="w-4 h-4" />
                                  </button>
                                  <button 
                                    onClick={() => setItemViewMode('table')}
                                    className={`p-2 rounded-lg transition-all ${itemViewMode === 'table' ? 'bg-gray-100 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                                  >
                                    <TableIcon className="w-4 h-4" />
                                  </button>
                                </div>
                                <div className="h-6 w-px bg-gray-200"></div>
                                <button onClick={handleAddManualItem} className="text-sm text-blue-600 hover:text-blue-800 font-bold flex items-center gap-1.5 hover:underline decoration-2 underline-offset-2">
                                   <Plus className="w-4 h-4" /> Add Item manually
                                </button>
                              </div>
                           </div>

                           {/* View Mode Rendering */}
                           {itemViewMode === 'list' ? (
                             rfqData.lineItems.map((item, index) => (
                                <LineItemCard 
                                  key={item.id} 
                                  item={item} 
                                  index={index} 
                                  onChange={handleLineItemChange} 
                                />
                             ))
                           ) : (
                             <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-sm">
                               <table className="w-full text-left text-sm">
                                 <thead className="bg-gray-50 border-b border-gray-100 text-gray-500 font-bold uppercase text-[11px] tracking-wider">
                                   <tr>
                                     <th className="px-6 py-4 w-16 text-center">#</th>
                                     <th className="px-6 py-4">Description</th>
                                     <th className="px-6 py-4 w-40">Material</th>
                                     <th className="px-6 py-4 w-28 text-center">Qty</th>
                                     <th className="px-6 py-4 w-48">Dims (L x W x H)</th>
                                     <th className="px-6 py-4 w-28 text-right">Unit Price</th>
                                     <th className="px-6 py-4 w-32 text-right">Total</th>
                                     <th className="px-6 py-4 w-16"></th>
                                   </tr>
                                 </thead>
                                 <tbody className="divide-y divide-gray-50">
                                   {rfqData.lineItems.map((item, index) => (
                                     <tr key={item.id} className="hover:bg-blue-50/20 transition-colors">
                                       <td className="px-6 py-4 text-center text-gray-400 font-medium">{index + 1}</td>
                                       <td className="px-6 py-4">
                                         <input 
                                           className="w-full bg-transparent border-b border-transparent focus:border-blue-500 outline-none font-medium text-gray-700"
                                           value={item.description}
                                           onChange={(e) => handleLineItemChange(item.id, 'description', e.target.value)}
                                         />
                                       </td>
                                       <td className="px-6 py-4">
                                         <select 
                                            value={item.material}
                                            onChange={(e) => handleLineItemChange(item.id, 'material', e.target.value)}
                                            className="w-full bg-transparent text-xs border-b border-transparent focus:border-blue-500 outline-none py-1 font-mono text-blue-600"
                                         >
                                            {Object.values(MaterialType).map(m => (
                                              <option key={m} value={m}>{m}</option>
                                            ))}
                                         </select>
                                       </td>
                                       <td className="px-6 py-4">
                                         <input 
                                            type="number"
                                            className="w-full text-center bg-transparent border-b border-transparent focus:border-blue-500 outline-none font-medium"
                                            value={item.quantity}
                                            onChange={(e) => handleLineItemChange(item.id, 'quantity', parseInt(e.target.value) || 0)}
                                         />
                                       </td>
                                       <td className="px-6 py-4">
                                          <div className="flex gap-2 justify-center">
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-gray-50 rounded-md border-none text-xs py-1 font-mono text-gray-600 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.length}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.length', parseFloat(e.target.value) || 0)}
                                            />
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-gray-50 rounded-md border-none text-xs py-1 font-mono text-gray-600 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.width}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.width', parseFloat(e.target.value) || 0)}
                                            />
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-gray-50 rounded-md border-none text-xs py-1 font-mono text-gray-600 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.height}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.height', parseFloat(e.target.value) || 0)}
                                            />
                                          </div>
                                       </td>
                                       <td className="px-6 py-4 text-right font-mono text-gray-600 text-sm">
                                         {formatCurrency(item.calculation.materialCost)}
                                       </td>
                                       <td className="px-6 py-4 text-right font-mono font-bold text-gray-900 text-sm">
                                         {formatCurrency(item.calculation.totalLineCost)}
                                       </td>
                                       <td className="px-6 py-4 text-right">
                                          <button onClick={() => handleDeleteItem(item.id)} className="text-gray-300 hover:text-red-500 transition-colors p-1 hover:bg-red-50 rounded">
                                            <Trash2 className="w-4 h-4" />
                                          </button>
                                       </td>
                                     </tr>
                                   ))}
                                 </tbody>
                               </table>
                             </div>
                           )}

                           <div className="h-24"></div> {/* Spacer */}
                        </div>

                        {/* Sticky Footer */}
                        <div className="px-10 py-6 border-t border-gray-200 bg-white shadow-[0_-10px_40px_-15px_rgba(0,0,0,0.1)] z-20">
                           <div className="flex items-center justify-between">
                              <div>
                                 <p className="text-[11px] text-gray-400 font-bold uppercase tracking-wider mb-1">Total Estimate</p>
                                 <p className="text-4xl font-extrabold text-slate-900 tracking-tight">{formatCurrency(totalCost)}</p>
                              </div>
                              <div className="flex gap-4">
                                 <button 
                                   onClick={handleExportPDF}
                                   className="px-6 py-3.5 bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm hover:shadow-md"
                                 >
                                    <FileText className="w-4 h-4" /> Save PDF
                                 </button>
                                 <button 
                                 onClick={advanceWorkflow}
                                 disabled={currentStatus === QuoteStatus.SENT}
                                 className="px-6 py-3.5 bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-xl font-bold disabled:opacity-50 transition-colors"
                                 >
                                    {currentStatus === QuoteStatus.SENT ? 'Locked' : 'Approve Stage'}
                                 </button>
                                 <button 
                                 onClick={() => setIsModalOpen(true)}
                                 className="px-8 py-3.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl font-bold hover:shadow-lg hover:shadow-blue-500/30 transition-all hover:-translate-y-0.5 active:translate-y-0 flex items-center gap-2"
                                 >
                                 <Save className="w-4 h-4" /> Save Quote
                                 </button>
                              </div>
                           </div>
                        </div>
                       </>
                    )}

                    {/* Collaboration View */}
                    {activeTab === 'collaboration' && (
                       <div className="flex-1 flex flex-col bg-gray-50 p-8">
                          <div className="flex-1 overflow-y-auto space-y-6 mb-4 px-4">
                             {rfqData.comments.length === 0 && (
                                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4">
                                  <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center">
                                    <MessageSquare className="w-10 h-10 text-gray-300" />
                                  </div>
                                  <p className="font-medium">No messages yet. Start the conversation.</p>
                                </div>
                             )}
                             {rfqData.comments.map(comment => (
                                <div key={comment.id} className={`flex ${comment.author === 'You' ? 'justify-end' : 'justify-start'}`}>
                                   <div className={`max-w-[80%] rounded-[1.5rem] p-6 shadow-sm ${comment.author === 'You' ? 'bg-blue-600 text-white rounded-br-sm' : 'bg-white border border-gray-100 text-gray-800 rounded-bl-sm'}`}>
                                      <div className="flex justify-between items-center mb-2 gap-8">
                                         <span className={`font-bold text-xs ${comment.author === 'You' ? 'text-blue-100' : 'text-gray-500'}`}>{comment.author}</span>
                                         <span className={`text-[10px] ${comment.author === 'You' ? 'text-blue-200' : 'text-gray-400'}`}>{comment.timestamp}</span>
                                      </div>
                                      <p className="text-sm leading-relaxed">{comment.text}</p>
                                   </div>
                                </div>
                             ))}
                          </div>
                          <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-xl shadow-gray-200/50 flex gap-3 items-end">
                             <div className="p-3 text-gray-400 hover:text-gray-600 cursor-pointer hover:bg-gray-50 rounded-xl transition-colors">
                                <Paperclip className="w-5 h-5" />
                             </div>
                             <textarea 
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && addComment()}
                                placeholder="Type a note to your team or supplier..."
                                className="flex-1 outline-none text-sm resize-none max-h-32 py-3 px-2"
                                rows={1}
                             />
                             <button 
                              onClick={addComment} 
                              className="bg-blue-600 text-white p-3 rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-500/30"
                             >
                               <Send className="w-4 h-4" />
                             </button>
                          </div>
                       </div>
                    )}

                    {/* Documents View */}
                    {activeTab === 'documents' && (
                       <div className="flex-1 bg-gray-50 p-10">
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                             {rfqData.attachments.map(file => (
                                <div key={file.id} className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm hover:shadow-xl hover:border-blue-200 transition-all group cursor-pointer relative overflow-hidden">
                                   <div className="absolute top-0 left-0 w-1.5 h-full bg-blue-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                   <div className="flex items-start justify-between mb-6">
                                      <div className="p-4 bg-red-50 text-red-600 rounded-2xl">
                                         <FileText className="w-8 h-8" />
                                      </div>
                                      <button className="text-gray-300 hover:text-blue-600 transition-colors p-2 hover:bg-gray-50 rounded-lg"><Download className="w-5 h-5" /></button>
                                   </div>
                                   <p className="font-bold text-gray-900 text-base truncate mb-2" title={file.name}>{file.name}</p>
                                   <p className="text-xs text-gray-400 flex items-center gap-2 font-medium">
                                     <span>{file.size}</span>
                                     <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                     <span>{file.uploadDate}</span>
                                   </p>
                                </div>
                             ))}
                             <div className="border-2 border-dashed border-gray-300 rounded-2xl flex flex-col items-center justify-center p-10 text-gray-400 hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50/50 transition-all cursor-pointer bg-white/50 group min-h-[200px]">
                                <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center mb-4 group-hover:bg-blue-100 transition-colors">
                                  <Plus className="w-6 h-6" />
                                </div>
                                <span className="text-sm font-bold">Add Document</span>
                                <span className="text-xs text-gray-400 mt-1">PDF, Excel, Images</span>
                             </div>
                          </div>
                       </div>
                    )}

                  </div>
                </>
              )}

              {/* Overlay AI Panel */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

export default App;

export enum MaterialType {
  STEEL_C45 = 'C45',
  ALUMINIUM_6061 = 'Alu 6061',
  STAINLESS_304 = 'SS 304',
  BRASS = 'Brass',
  PLASTIC_ABS = 'ABS'
}

export interface Dimensions {
  length: number;
  width: number;
  height: number;
}

export interface CalculationResult {
  volumeMm3: number;
  density: number; // g/cm3
  weightGrams: number;
  materialCost: number;
  totalLineCost: number;
}

export interface LineItem {
  id: string;
  description: string;
  material: MaterialType;
  dimensions: Dimensions;
  quantity: number;
  unit: string;
  tolerance?: string;
  deliveryDate?: string;
  calculation: CalculationResult;
}

export interface RFQHeader {
  customerName: string;
  rfqNumber: string;
  rfqName: string; // Added from ref image
  rfqDescription: string; // Added from ref image
  partNumber: string; // Added from ref image
  documentDate: string;
  vendorName: string;
  responsiblePerson: string; // Added from ref image
  bidCloseDate: string;
  location: string;
  isAuction: boolean; // Added from ref image
}

export interface Comment {
  id: string;
  author: string;
  text: string;
  timestamp: string;
  type: 'internal' | 'supplier';
}

export interface Attachment {
  id: string;
  name: string;
  size: string;
  type: string;
  uploadDate: string;
}

export interface RFQData {
  header: RFQHeader;
  lineItems: LineItem[];
  comments: Comment[];
  attachments: Attachment[];
}

export type ViewMode = 'dashboard' | 'editor' | 'rfq_flow' | 'suppliers' | 'analytics' | 'demand_intelligence' | 'settings';
export type EditorMode = 'upload' | 'verify';

export enum QuoteStatus {
  DRAFT = 'Draft',
  WIP = 'WIP', // From ref image
  REVIEW = 'In Review',
  APPROVED = 'Approved',
  SENT = 'Sent',
  ON_HOLD = 'On Hold' // From ref image
}

export interface SavedQuote extends RFQHeader {
  id: string;
  status: QuoteStatus;
  totalValue: number;
  lastModified: string;
  remark?: string; // From ref image
  templateRef?: string; // From ref image
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  timestamp: Date;
}

export interface Supplier {
  id: string;
  name: string;
  contactPerson: string;
  email: string;
  phone?: string;
  address?: string;
  rating: number; // 1-5
  status: 'active' | 'inactive';
  category: string[];
}

// Pricing Configuration Types
export interface MaterialDef {
  id: MaterialType;
  name: string;
  density: number; // g/cm3
  costPerKg: number; // EUR per Kg
  lastUpdated: string;
}

export interface PricingConfig {
  materials: Record<MaterialType, MaterialDef>;
  globalMarkup: number; // Percentage
  currency: string;
}

// --- ANALYTICS TYPES ---

export type IntentLevel = 'Low (Browsing)' | 'Medium (Evaluation)' | 'High (Commitment)';

