export const RFQStatusFlow: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');

  // The 4 steps shown in the Excel RFQ image
  const flowSteps = ['Released', 'Responded', 'Evaluated', 'Awarded'];

  const getFlowStatusColor = (currentStep: number, stepIndex: number) => {
    // stepIndex is 0-based. 
    // currentStep is 1-based (1 = Released done, 4 = Awarded done)

    // If this step is completed or active
    if (stepIndex < currentStep) {
      return 'bg-emerald-400 text-white'; // Green filled
    }
    // If this step is pending
    return 'bg-gray-100 text-gray-400';
  };

  return (
    <div className="flex-1 bg-[#F8FAFC] p-8 overflow-y-auto h-full animate-in fade-in duration-300">

      {/* Header Area */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 tracking-tight mb-1">RFQ Status Flow</h1>
          <p className="text-gray-500 text-sm">Real-time fulfillment tracking and stage visualization.</p>
        </div>

        <div className="flex gap-3 w-full md:w-auto">
           <div className="relative flex-1 md:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
              <input 
                type="text" 
                placeholder="Search RFQ ID..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none text-sm bg-white shadow-sm"
              />
           </div>
           <button className="flex items-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-blue-500/30 hover:bg-blue-700 transition-all">
             + Add New RFQ
           </button>
        </div>
      </div>

      {/* Main Table Card */}
      <div className="bg-white border border-gray-200 rounded-2xl shadow-sm overflow-hidden">

        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-4 font-semibold text-gray-500">Type</th>
                <th className="px-6 py-4 font-semibold text-gray-500">RFQ ID</th>
                <th className="px-6 py-4 font-semibold text-gray-500">Date</th>
                <th className="px-6 py-4 font-semibold text-gray-500">Expiry</th>
                <th className="px-6 py-4 font-semibold text-gray-500 w-1/3">Fulfilment (Flow)</th>
