                <th className="px-6 py-4 font-semibold text-gray-500 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {MOCK_FLOW_DATA.map((item, index) => (
                <tr key={index} className="hover:bg-blue-50/10 transition-colors group">
                  <td className="px-6 py-5 text-gray-600 font-medium">{item.type}</td>
                  <td className="px-6 py-5 text-gray-900 font-bold">{item.id}</td>
                  <td className="px-6 py-5 text-gray-500">{item.date}</td>
                  <td className="px-6 py-5 text-gray-500">{item.expiry}</td>

                  {/* Flow Visualization */}
                  <td className="px-6 py-5">
                    <div className="flex items-center gap-1">
                       {flowSteps.map((step, idx) => {
                          const isCompleted = idx < item.flowStep;
                          const isLast = idx === flowSteps.length - 1;

