                                 <div className={`h-0.5 w-4 ${isCompleted && idx + 1 < item.flowStep ? 'bg-emerald-400' : 'bg-gray-200'}`}></div>
                               )}
                            </div>
                          );
                       })}
                    </div>
                  </td>

                  <td className="px-6 py-5 text-gray-600 font-medium pl-10">{item.participants}</td>

                  <td className="px-6 py-5 text-right">
                    <button className="px-4 py-2 border border-gray-200 rounded-lg text-xs font-bold text-gray-600 hover:bg-gray-50 hover:text-blue-600 transition-colors">
