        </div>
        <div className="bg-white p-4 rounded-xl border border-gray-200/60 shadow-sm flex items-center justify-between">
           <div>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Active RFQs</p>
              <h3 className="text-xl font-extrabold text-gray-900">{quotes.length}</h3>
           </div>
           <div className="p-2.5 bg-blue-50 text-blue-600 rounded-lg">
              <FileText className="w-4 h-4" />
           </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-gray-200/60 shadow-sm flex items-center justify-between">
           <div>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Win Rate</p>
              <h3 className="text-xl font-extrabold text-gray-900">34.2%</h3>
           </div>
           <div className="p-2.5 bg-purple-50 text-purple-600 rounded-lg">
              <TrendingUp className="w-4 h-4" />
           </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-gray-200/60 shadow-sm flex items-center justify-between">
           <div>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Action Items</p>
              <h3 className="text-xl font-extrabold text-gray-900">{quotes.filter(q => q.status === QuoteStatus.REVIEW).length}</h3>
           </div>
           <div className="p-2.5 bg-amber-50 text-amber-600 rounded-lg">
