                             <WorkflowProgress status={quote.status} />
                          </div>
                       </td>
                       <td className="px-6 py-3 text-right">
                          <div className="flex items-center justify-end gap-2">
                             <button 
                               onClick={() => onEditQuote(quote.id)}
                               className="px-3 py-1.5 bg-white border border-gray-200 text-gray-600 rounded-lg text-xs font-bold hover:bg-gray-50 hover:text-blue-600 transition-colors shadow-sm"
                             >
                                Manage
