                                       </td>
                                       <td className="px-6 py-4">
                                         <input 
                                            type="number"
                                            className="w-full text-center bg-transparent border-b border-transparent focus:border-blue-500 outline-none font-medium"
                                            value={item.quantity}
                                            onChange={(e) => handleLineItemChange(item.id, 'quantity', parseInt(e.target.value) || 0)}
                                         />
                                       </td>
                                       <td className="px-6 py-4">
                                          <div className="flex gap-2 justify-center">
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-gray-50 rounded-md border-none text-xs py-1 font-mono text-gray-600 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.length}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.length', parseFloat(e.target.value) || 0)}
                                            />
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-gray-50 rounded-md border-none text-xs py-1 font-mono text-gray-600 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.width}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.width', parseFloat(e.target.value) || 0)}
                                            />
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-gray-50 rounded-md border-none text-xs py-1 font-mono text-gray-600 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.height}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.height', parseFloat(e.target.value) || 0)}
                                            />
                                          </div>
                                       </td>
                                       <td className="px-6 py-4 text-right font-mono text-gray-600 text-sm">
                                         {formatCurrency(item.calculation.materialCost)}
                                       </td>
                                       <td className="px-6 py-4 text-right font-mono font-bold text-gray-900 text-sm">
                                         {formatCurrency(item.calculation.totalLineCost)}
                                       </td>
                                       <td className="px-6 py-4 text-right">
                                          <button onClick={() => handleDeleteItem(item.id)} className="text-gray-300 hover:text-red-500 transition-colors p-1 hover:bg-red-50 rounded">
                                            <Trash2 className="w-4 h-4" />
                                          </button>
                                       </td>
                                     </tr>
                                   ))}
                                 </tbody>
                               </table>
                             </div>
                           )}

                           <div className="h-24"></div> {/* Spacer */}
                        </div>

                        {/* Sticky Footer */}
                        <div className="px-10 py-6 border-t border-gray-200 bg-white shadow-[0_-10px_40px_-5px_rgba(0,0,0,0.1)] z-20">
