                              <div>
                                 <p className="text-[11px] text-gray-400 font-bold uppercase tracking-wider mb-1">Total Estimate</p>
                                 <p className="text-4xl font-extrabold text-slate-900 tracking-tight">{formatCurrency(totalCost)}</p>
                              </div>
                              <div className="flex gap-4">
                                 <button 
                                   onClick={handleExportPDF}
                                   className="px-6 py-3.5 bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm hover:shadow-md"
                                 >
                                    <FileText className="w-4 h-4" /> Save PDF
                                 </button>
                                 <button 
                                 onClick={advanceWorkflow}
                                 disabled={currentStatus === QuoteStatus.SENT}
                                 className="px-6 py-3.5 bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-xl font-bold disabled:opacity-50 transition-colors"
                                 >
                                    {currentStatus === QuoteStatus.SENT ? 'Locked' : 'Approve Stage'}
                                 </button>
                                 <button 
                                 onClick={() => setIsModalOpen(true)}
                                 className="px-8 py-3.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl font-bold hover:shadow-lg hover:shadow-blue-500/30 transition-all hover:-translate-y-0.5 active:translate-y-0 flex items-center gap-2"
                                 >
                                 <Save className="w-4 h-4" /> Save Quote
                                 </button>
                              </div>
                           </div>
                        </div>
                       </>
                    )}

                    {/* Collaboration View */}
                    {activeTab === 'collaboration' && (
                       <div className="flex-1 flex flex-col bg-gray-50 p-8">
                          <div className="flex-1 overflow-y-auto space-y-6 mb-4 px-4">
                             {rfqData.comments.length === 0 && (
                                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4">
                                  <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center">
                                    <MessageSquare className="w-10 h-10 text-gray-300" />
                                  </div>
                                  <p className="font-medium">No messages yet. Start the conversation.</p>
                                </div>
                             )}
                             {rfqData.comments.map(comment => (
                                <div key={comment.id} className={`flex ${comment.author === 'You' ? 'justify-end' : 'justify-start'}`}>
                                   <div className={`max-w-[80%] rounded-[1.5rem] p-6 shadow-sm ${comment.author === 'You' ? 'bg-blue-600 text-white rounded-br-sm' : 'bg-white border border-gray-100 text-gray-800 rounded-bl-sm'}`}>
                                      <div className="flex justify-between items-center mb-2 gap-8">
                                         <span className={`font-bold text-xs ${comment.author === 'You' ? 'text-blue-100' : 'text-gray-500'}`}>{comment.author}</span>
                                         <span className={`text-[10px] ${comment.author === 'You' ? 'text-blue-200' : 'text-gray-400'}`}>{comment.timestamp}</span>
                                      </div>
                                      <p className="text-sm leading-relaxed">{comment.text}</p>
                                   </div>
                                </div>
                             ))}
                          </div>
                          <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-xl shadow-gray-200/50 flex gap-3 items-end">
                             <div className="p-3 text-gray-400 hover:text-gray-600 cursor-pointer hover:bg-gray-50 rounded-xl transition-colors">
                                <Paperclip className="w-5 h-5" />
                             </div>
                             <textarea 
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && addComment()}
                                placeholder="Type a note to your team or supplier..."
                                className="flex-1 outline-none text-sm resize-none max-h-32 py-3 px-2"
                                rows={1}
                             />
                             <button 
                              onClick={addComment} 
                              className="bg-blue-600 text-white p-3 rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-500/30"
                             >
                               <Send className="w-4 h-4" />
                             </button>
                          </div>
                       </div>
                    )}

                    {/* Documents View */}
                    {activeTab === 'documents' && (
                       <div className="flex-1 bg-gray-50 p-10">
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                             {rfqData.attachments.map(file => (
                                <div key={file.id} className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm hover:shadow-xl hover:border-blue-200 transition-all group cursor-pointer relative overflow-hidden">
                                   <div className="absolute top-0 left-0 w-1.5 h-full bg-blue-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                   <div className="flex items-start justify-between mb-6">
                                      <div className="p-4 bg-red-50 text-red-600 rounded-2xl">
                                         <FileText className="w-8 h-8" />
                                      </div>
                                      <button className="text-gray-300 hover:text-blue-600 transition-colors p-2 hover:bg-gray-50 rounded-lg"><Download className="w-5 h-5" /></button>
                                   </div>
                                   <p className="font-bold text-gray-900 text-base truncate mb-2" title={file.name}>{file.name}</p>
                                   <p className="text-xs text-gray-400 flex items-center gap-2 font-medium">
                                     <span>{file.size}</span>
                                     <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                     <span>{file.uploadDate}</span>
                                   </p>
                                </div>
                             ))}
                             <div className="border-2 border-dashed border-gray-300 rounded-2xl flex flex-col items-center justify-center p-10 text-gray-400 hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50/50 transition-all cursor-pointer bg-white/50 group min-h-[200px]">
                                <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center mb-4 group-hover:bg-blue-100 transition-colors">
                                  <Plus className="w-6 h-6" />
                                </div>
                                <span className="text-sm font-bold">Add Document</span>
                                <span className="text-xs text-gray-400 mt-1">PDF, Excel, Images</span>
                             </div>
                          </div>
                       </div>
                    )}

                  </div>
                </>
              )}

              {/* Overlay AI Panel */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

export default App;

export enum MaterialType {
  STEEL_C45 = 'C45',
  ALUMINIUM_6061 = 'Alu 6061',
  STAINLESS_304 = 'SS 304',
  BRASS = 'Brass',
  PLASTIC_ABS = 'ABS'
}

export interface Dimensions {
  length: number;
  width: number;
  height: number;
}

export interface CalculationResult {
  volumeMm3: number;
  density: number; // g/cm3
  weightGrams: number;
  materialCost: number;
  totalLineCost: number;
}

export interface LineItem {
  id: string;
  description: string;
  material: MaterialType;
  dimensions: Dimensions;
  quantity: number;
  unit: string;
  tolerance?: string;
  deliveryDate?: string;
  calculation: CalculationResult;
}

export interface RFQHeader {
  customerName: string;
  rfqNumber: string;
  rfqName: string; // Added from ref image
  rfqDescription: string; // Added from ref image
  partNumber: string; // Added from ref image
  documentDate: string;
  vendorName: string;
  responsiblePerson: string; // Added from ref image
  bidCloseDate: string;
  location: string;
  isAuction: boolean; // Added from ref image
}

export interface Comment {
  id: string;
  author: string;
  text: string;
  timestamp: string;
  type: 'internal' | 'supplier';
  role?: string; // To differentiate visual style
}

export interface Attachment {
  id: string;
  name: string;
  size: string;
  type: string;
  uploadDate: string;
}

export interface RFQData {
  header: RFQHeader;
  lineItems: LineItem[];
  comments: Comment[];
  attachments: Attachment[];
}

export type ViewMode = 'dashboard' | 'editor' | 'rfq_flow' | 'suppliers' | 'analytics' | 'demand_intelligence' | 'settings' | 'team';
export type EditorMode = 'upload' | 'verify';

export enum QuoteStatus {
  DRAFT = 'Draft',
  WIP = 'WIP', // From ref image
  REVIEW = 'In Review',
  APPROVED = 'Approved',
  SENT = 'Sent',
  ON_HOLD = 'On Hold' // From ref image
}

export interface SavedQuote extends RFQHeader {
  id: string;
  status: QuoteStatus;
  totalValue: number;
  lastModified: string;
  remark?: string; // From ref image
  templateRef?: string; // From ref image
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  timestamp: Date;
}

export interface Supplier {
  id: string;
  name: string;
  contactPerson: string;
  email: string;
  phone?: string;
  address?: string;
  rating: number; // 1-5
  status: 'active' | 'inactive';
  category: string[];
}

// Pricing Configuration Types
export interface MaterialDef {
  id: MaterialType;
  name: string;
  density: number; // g/cm3
  costPerKg: number; // EUR per Kg
  lastUpdated: string;
}

export interface PricingConfig {
  materials: Record<MaterialType, MaterialDef>;
  globalMarkup: number; // Percentage
  currency: string;
}

// --- ANALYTICS TYPES ---

export type IntentLevel = 'Low (Browsing)' | 'Medium (Evaluation)' | 'High (Commitment)';

export interface InteractionEvent {
  id: string;
  sessionId: string;
  timestamp: number;
  action: 'page_view' | 'upload_attempt' | 'material_change' | 'dimension_edit' | 'quantity_change' | 'view_estimate' | 'submit_rfq';
  details?: string;
  metadata?: any;
}

export interface SessionIntent {
  sessionId: string;
  startTime: number;
  lastActive: number;
  actionsCount: number;
  intentScore: number;
  intentLevel: IntentLevel;
  currentConfig?: {
    material?: string;
    value?: number;
  };
}

// --- USER MANAGEMENT TYPES ---
export type UserRole = 'admin' | 'user';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar?: string;
  status: 'active' | 'pending';
  joinedDate: string;
}

