const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isCustomerMode, setIsCustomerMode] = useState(false);

  // Navigation State
  const [viewMode, setViewMode] = useState<ViewMode>('dashboard');
  const [editorMode, setEditorMode] = useState<EditorMode>('upload');
  const [activeTab, setActiveTab] = useState<'items' | 'collaboration' | 'documents'>('items');
  const [itemViewMode, setItemViewMode] = useState<'list' | 'table'>('list');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // Data State
  const [pricingConfig, setPricingConfig] = useState<PricingConfig>(getPricingConfig());
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [rfqData, setRfqData] = useState<RFQData>({ 
    header: INITIAL_HEADER, 
    lineItems: [],
    comments: [],
    attachments: []
  });
  const [savedQuotes, setSavedQuotes] = useState<SavedQuote[]>(MOCK_QUOTES);
  const [currentStatus, setCurrentStatus] = useState<QuoteStatus>(QuoteStatus.DRAFT);

  // UI State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [newComment, setNewComment] = useState('');

  // Calculate total
  const totalCost = rfqData.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);

  // --- Actions ---

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setIsCustomerMode(false);
  }

  const handleCustomerEnter = () => {
    setIsCustomerMode(true);
  }

  const handleBackToLogin = () => {
    setIsCustomerMode(false);
    setCurrentUser(null);
  }

  // Update configuration and recalculate current items if necessary
  const updatePricingConfig = (newConfig: PricingConfig) => {
    setPricingConfig(newConfig);
    savePricingConfig(newConfig);

    // Recalculate existing items with new prices
    if (rfqData.lineItems.length > 0) {
      setRfqData(prev => ({
        ...prev,
        lineItems: prev.lineItems.map(item => ({
          ...item,
          calculation: calculateLineItem(item.material, item.dimensions, item.quantity, newConfig)
        }))
      }));
    }
  };

  const startNewQuote = () => {
    setRfqData({ header: INITIAL_HEADER, lineItems: [], comments: [], attachments: [] });
    setFile(null);
    setFilePreview(null);
    setEditorMode('upload');
    setCurrentStatus(QuoteStatus.DRAFT);
    setViewMode('editor');
    setIsChatOpen(false);
  };

  const handleEditQuote = (id: string) => {
    const quote = savedQuotes.find(q => q.id === id);
    if (quote) {
       setRfqData({
         header: quote,
         lineItems: [], // In real app, load items
         comments: MOCK_COMMENTS, // In real app, load from ID
         attachments: MOCK_ATTACHMENTS
       });
       setCurrentStatus(quote.status);
       setEditorMode('verify');
       setViewMode('editor');
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setIsProcessing(true);

      try {
        const base64Data = await fileToBase64(selectedFile);
        const base64Content = base64Data.split(',')[1];

        const extracted = await extractRFQData(base64Content, selectedFile.type);

        const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
          const material = Object.values(MaterialType).includes(item.material as MaterialType) 
            ? item.material as MaterialType 
            : MaterialType.STEEL_C45;

          const dims = {
             length: item.length || 0,
             width: item.width || 0,
             height: item.height || 0
          };

          return {
            id: `item-${Date.now()}-${idx}`,
            description: item.description || `Item ${idx + 1}`,
            material,
            quantity: item.quantity || 1,
            unit: item.unit || 'ST',
            dimensions: dims,
            deliveryDate: item.deliveryDate || '',
            tolerance: item.tolerance,
            calculation: calculateLineItem(material, dims, item.quantity || 1, pricingConfig)
          };
        });

        setRfqData(prev => ({
          ...prev,
          header: {
            ...INITIAL_HEADER,
            customerName: extracted.customerName || '',
            rfqNumber: extracted.rfqNumber || '',
            documentDate: extracted.documentDate || new Date().toISOString().split('T')[0]
          },
          lineItems: processedItems,
          attachments: [...prev.attachments, {
             id: Date.now().toString(),
             name: selectedFile.name,
             size: `${(selectedFile.size / 1024 / 1024).toFixed(2)} MB`,
             type: 'pdf',
             uploadDate: new Date().toLocaleDateString()
          }]
        }));

        setEditorMode('verify');
      } catch (err) {
        console.error(err);
        alert("Failed to process document. Please try again.");
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const handleLineItemChange = useCallback((id: string, field: string, value: any) => {
    setRfqData(prev => {
      const newItems = prev.lineItems.map(item => {
        if (item.id !== id) return item;
        const updated = { ...item };

        if (field.startsWith('dimensions.')) {
          const dimKey = field.split('.')[1] as keyof typeof updated.dimensions;
          updated.dimensions = { ...updated.dimensions, [dimKey]: value };
        } else if (field === 'material') {
           updated.material = value as MaterialType;
        } else if (field === 'quantity') {
           updated.quantity = value;
        } else {
          (updated as any)[field] = value;
        }

        updated.calculation = calculateLineItem(updated.material, updated.dimensions, updated.quantity, pricingConfig);
        return updated;
      });
      return { ...prev, lineItems: newItems };
    });
  }, [pricingConfig]);

  const handleDeleteItem = (id: string) => {
    setRfqData(prev => ({
      ...prev,
      lineItems: prev.lineItems.filter(item => item.id !== id)
    }));
  };

  const handleAddManualItem = () => {
    const newItem: LineItem = {
      id: `manual-${Date.now()}`,
      description: 'New Manual Item',
      material: MaterialType.STEEL_C45,
      quantity: 1,
      unit: 'ST',
      dimensions: { length: 0, width: 0, height: 0 },
      calculation: calculateLineItem(MaterialType.STEEL_C45, { length: 0, width: 0, height: 0 }, 1, pricingConfig)
    };
    setRfqData(prev => ({ ...prev, lineItems: [...prev.lineItems, newItem] }));
    if (editorMode === 'upload') setEditorMode('verify');
  };

  const handleSaveQuote = (header: typeof INITIAL_HEADER) => {
    const newQuote: SavedQuote = {
      ...header,
      id: `q-${Date.now()}`,
      status: currentStatus,
      totalValue: totalCost,
      lastModified: new Date().toISOString()
    };
    setSavedQuotes(prev => [newQuote, ...prev]);
    setIsModalOpen(false);
    setViewMode('dashboard');
  };

  const handleExportPDF = () => {
    generateQuotePDF(rfqData);
  };

  const advanceWorkflow = () => {
     if (currentStatus === QuoteStatus.DRAFT) setCurrentStatus(QuoteStatus.REVIEW);
     else if (currentStatus === QuoteStatus.REVIEW) setCurrentStatus(QuoteStatus.APPROVED);
     else if (currentStatus === QuoteStatus.APPROVED) setCurrentStatus(QuoteStatus.SENT);
  };

  const addComment = () => {
    if (!newComment.trim() || !currentUser) return;

