                                       </td>
                                       <td className="px-6 py-4 text-right font-mono font-bold text-gray-900 text-sm">
                                         {formatCurrency(item.calculation.totalLineCost)}
                                       </td>
                                       <td className="px-6 py-4 text-right">
                                          <button onClick={() => handleDeleteItem(item.id)} className="text-gray-300 hover:text-red-500 transition-colors p-1 hover:bg-red-50 rounded">
                                            <Trash2 className="w-4 h-4" />
                                          </button>
                                       </td>
                                     </tr>
                                   ))}
                                 </tbody>
                               </table>
                             </div>
                           )}

                           <div className="h-24"></div> {/* Spacer */}
                        </div>

                        {/* Sticky Footer */}
                        <div className="px-10 py-6 border-t border-gray-200 bg-white shadow-[0_-10px_40px_-5px_rgba(0,0,0,0.1)] z-20">
                           <div className="flex items-center justify-between">
                              <div>
                                 <p className="text-[11px] text-gray-400 font-bold uppercase tracking-wider mb-1">Total Estimate</p>
                                 <p className="text-4xl font-extrabold text-slate-900 tracking-tight">{formatCurrency(totalCost)}</p>
                              </div>
                              <div className="flex gap-4">
                                 <button 
                                   onClick={handleExportPDF}
                                   className="px-6 py-3.5 bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm hover:shadow-md"
                                 >
                                    <FileText className="w-4 h-4" /> Save PDF
                                 </button>
                                 <button 
                                 onClick={advanceWorkflow}
                                 disabled={currentStatus === QuoteStatus.SENT}
                                 className="px-6 py-3.5 bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-xl font-bold disabled:opacity-50 transition-colors"
                                 >
                                    {currentStatus === QuoteStatus.SENT ? 'Locked' : 'Approve Stage'}
                                 </button>
                                 <button 
                                 onClick={() => setIsModalOpen(true)}
                                 className="px-8 py-3.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl font-bold hover:shadow-lg hover:shadow-blue-500/30 transition-all hover:-translate-y-0.5 active:translate-y-0 flex items-center gap-2"
                                 >
                                 <Save className="w-4 h-4" /> Save Quote
                                 </button>
                              </div>
                           </div>
                        </div>
                       </>
                    )}

                    {/* Collaboration View */}
                    {activeTab === 'collaboration' && (
                       <div className="flex-1 flex flex-col bg-gray-50 p-8">
                          <div className="flex-1 overflow-y-auto space-y-6 mb-4 px-4">
                             {rfqData.comments.length === 0 && (
                                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4">
                                  <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center">
                                    <MessageSquare className="w-10 h-10 text-gray-300" />
                                  </div>
                                  <p className="font-medium">No messages yet. Start the conversation.</p>
                                </div>
                             )}
                             {rfqData.comments.map(comment => {
                                const isMe = comment.author === currentUser.name;
                                const isInternal = comment.type === 'internal';

                                return (
                                <div key={comment.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                   <div className={`max-w-[80%] rounded-[1.5rem] p-6 shadow-sm ${
                                      isMe 
                                        ? 'bg-blue-600 text-white rounded-br-sm' 
                                        : !isInternal 
                                          ? 'bg-amber-50 border border-amber-200 text-gray-800 rounded-bl-sm' // Supplier style
                                          : 'bg-white border border-gray-100 text-gray-800 rounded-bl-sm' // Standard colleague
                                   }`}>
                                      <div className="flex justify-between items-center mb-2 gap-8">
                                         <div className="flex items-center gap-2">
                                           <span className={`font-bold text-xs ${isMe ? 'text-blue-100' : 'text-gray-900'}`}>{comment.author}</span>
                                           {comment.role && !isMe && (
                                              <span className={`text-[10px] px-1.5 py-0.5 rounded uppercase font-bold ${
                                                comment.role === 'admin' ? 'bg-purple-100 text-purple-700' : 
                                                comment.role === 'supplier' ? 'bg-amber-100 text-amber-700' : 
                                                'bg-gray-100 text-gray-500'
                                              }`}>
                                                {comment.role}
                                              </span>
                                           )}
                                         </div>
                                         <span className={`text-[10px] ${isMe ? 'text-blue-200' : 'text-gray-400'}`}>{comment.timestamp}</span>
                                      </div>
                                      <p className="text-sm leading-relaxed">{comment.text}</p>
                                   </div>
                                </div>
                             )})}
                          </div>
                          <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-xl shadow-gray-200/50 flex gap-3 items-end">
                             <div className="p-3 text-gray-400 hover:text-gray-600 cursor-pointer hover:bg-gray-50 rounded-xl transition-colors">
                                <Paperclip className="w-5 h-5" />
                             </div>
                             <textarea 
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && addComment()}
                                placeholder={`Reply as ${currentUser.name}...`}
                                className="flex-1 outline-none text-sm resize-none max-h-32 py-3 px-2"
                                rows={1}
                             />
                             <button 
                              onClick={addComment} 
                              className="bg-blue-600 text-white p-3 rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-500/30"
                             >
                               <Send className="w-4 h-4" />
                             </button>
                          </div>
                       </div>
                    )}

                    {/* Documents View */}
                    {activeTab === 'documents' && (
                       <div className="flex-1 bg-gray-50 p-10">
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                             {rfqData.attachments.map(file => (
                                <div key={file.id} className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm hover:shadow-xl hover:border-blue-200 transition-all group cursor-pointer relative overflow-hidden">
                                   <div className="absolute top-0 left-0 w-1.5 h-full bg-blue-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                   <div className="flex items-start justify-between mb-6">
                                      <div className="p-4 bg-red-50 text-red-600 rounded-2xl">
                                         <FileText className="w-8 h-8" />
                                      </div>
                                      <button className="text-gray-300 hover:text-blue-600 transition-colors p-2 hover:bg-gray-50 rounded-lg"><Download className="w-5 h-5" /></button>
                                   </div>
                                   <p className="font-bold text-gray-900 text-base truncate mb-2" title={file.name}>{file.name}</p>
                                   <p className="text-xs text-gray-400 flex items-center gap-2 font-medium">
                                     <span>{file.size}</span>
                                     <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                     <span>{file.uploadDate}</span>
                                   </p>
                                </div>
                             ))}
                             <div className="border-2 border-dashed border-gray-300 rounded-2xl flex flex-col items-center justify-center p-10 text-gray-400 hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50/50 transition-all cursor-pointer bg-white/50 group min-h-[200px]">
                                <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center mb-4 group-hover:bg-blue-100 transition-colors">
                                  <Plus className="w-6 h-6" />
                                </div>
                                <span className="text-sm font-bold">Add Document</span>
                                <span className="text-xs text-gray-400 mt-1">PDF, Excel, Images</span>
                             </div>
                          </div>
                       </div>
                    )}

                  </div>
                </>
              )}

              {/* Overlay AI Panel */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Upload, ArrowRight, CheckCircle, FileText, Loader2, AlertCircle, RefreshCw, Send, ChevronRight, Bot, X, Eye, HelpCircle, MessageSquare, ShieldCheck, FileCheck, Search, ZoomIn, ZoomOut } from 'lucide-react';
import { extractRFQData } from '../services/geminiService';
import { calculateLineItem, formatCurrency } from '../services/calculationService';
import { logEvent, initSession } from '../services/analyticsService';
import { RFQData, LineItem, MaterialType, PricingConfig } from '../types';
import { INITIAL_HEADER } from '../constants';
import { ChatPanel } from './ChatPanel';

interface CustomerPortalProps {
  config: PricingConfig;
  onBackToLogin: () => void;
}

type Step = 'upload' | 'analyzing' | 'review' | 'details' | 'success' | 'negotiate';

export const CustomerPortal: React.FC<CustomerPortalProps> = ({ config, onBackToLogin }) => {
  const [step, setStep] = useState<Step>('upload');
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [rfqData, setRfqData] = useState<RFQData>({
    header: INITIAL_HEADER,
    lineItems: [],
    comments: [],
    attachments: []
  });
  const [customerDetails, setCustomerDetails] = useState({ name: '', email: '', company: '', notes: '' });
  const [negotiationTopic, setNegotiationTopic] = useState('Price');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [showPreview, setShowPreview] = useState(true);
  const [verifiedItems, setVerifiedItems] = useState<Set<string>>(new Set());
  const [zoomLevel, setZoomLevel] = useState(1);

  // Initialize Analytics Session on Mount
  useEffect(() => {
    initSession();
  }, []);

  // 1. Handle File Upload
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      logEvent('upload_attempt', `Uploaded ${selectedFile.name} (${(selectedFile.size/1024).toFixed(0)}kb)`);
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setStep('analyzing');

      try {
        // Convert to base64
        const reader = new FileReader();
        reader.readAsDataURL(selectedFile);
        reader.onload = async () => {
          const base64Content = (reader.result as string).split(',')[1];
          const extracted = await extractRFQData(base64Content, selectedFile.type);

          // Process Items
          const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
             const material = Object.values(MaterialType).includes(item.material as MaterialType) 
             ? item.material as MaterialType 
             : MaterialType.STEEL_C45;

             const dims = {
                length: item.length || 0,
                width: item.width || 0,
                height: item.height || 0
             };

             return {
               id: `cust-${Date.now()}-${idx}`,
               description: item.description || `Part #${idx + 1}`,
               material,
               quantity: item.quantity || 1,
               unit: item.unit || 'ST',
               dimensions: dims,
               deliveryDate: item.deliveryDate,
               tolerance: item.tolerance,
               calculation: calculateLineItem(material, dims, item.quantity || 1, config)
             };
          });

          setRfqData({
             ...rfqData,
             lineItems: processedItems
          });
          setVerifiedItems(new Set()); // Reset verification
          logEvent('view_estimate', 'AI Analysis complete, viewing initial pricing');
          setStep('review');
        };
      } catch (error) {
        console.error(error);
        alert("We couldn't read that file. Please try a clear PDF or Image.");
        setStep('upload');
      }
    }
  };

  const handleMaterialChange = (itemId: string, newMaterial: MaterialType) => {
    logEvent('material_change', `User switched to ${newMaterial}`);
    setRfqData(prev => ({
        ...prev,
        lineItems: prev.lineItems.map(item => {
            if (item.id !== itemId) return item;
            return {
                ...item,
                material: newMaterial,
                calculation: calculateLineItem(newMaterial, item.dimensions, item.quantity, config)
            };
        })
    }));
  };

  const handleQuantityChange = (itemId: string, newQty: number) => {
    if (newQty > 0) {
        logEvent('quantity_change', `Quantity adjusted to ${newQty}`);
        setRfqData(prev => ({
            ...prev,
            lineItems: prev.lineItems.map(item => {
                if (item.id !== itemId) return item;
                return {
                    ...item,
                    quantity: newQty,
                    calculation: calculateLineItem(item.material, item.dimensions, newQty, config)
                };
            })
        }));
    }
  };

  const toggleVerification = (id: string) => {
    const next = new Set(verifiedItems);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setVerifiedItems(next);
  };

  const totalCost = rfqData.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);
  const allVerified = rfqData.lineItems.length > 0 && verifiedItems.size === rfqData.lineItems.length;

  const handleSubmit = () => {
    logEvent('submit_rfq', `Formal RFQ submitted. Value: ${totalCost}`);
    // In a real app, this would POST to an API
    setStep('success');
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans flex flex-col relative">
      {/* Public Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-20 shadow-sm">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
           <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-[#1F4E79] rounded-lg flex items-center justify-center shadow-lg shadow-blue-900/20">
                 <RefreshCw className="w-5 h-5 text-white" />
              </div>
              <div>
                 <h1 className="text-lg font-bold text-gray-900 tracking-tight">Nosta Instant Quote</h1>
              </div>
           </div>

           <div className="flex items-center gap-4">
             {(step === 'review' || step === 'upload') && (
                <button 
                  onClick={() => setIsChatOpen(!isChatOpen)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all ${
                    isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white border border-gray-200 text-gray-700 hover:bg-gray-50'
                  }`}
                >
                  <Bot className="w-4 h-4" /> 
                  {isChatOpen ? 'Copilot Active' : 'Cost Copilot'}
                </button>
             )}
             {step !== 'success' && (
               <button onClick={onBackToLogin} className="text-sm text-gray-500 hover:text-gray-900 font-medium">
                 Nosta Staff Login
               </button>
             )}
           </div>
        </div>
      </header>

      {/* Main Content */}
      <div className={`flex-1 flex flex-col ${step === 'review' ? 'overflow-hidden' : 'overflow-y-auto'}`}>

        {/* Step 1: Upload */}
        {step === 'upload' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
              <div className="max-w-xl w-full text-center">
                 <h2 className="text-4xl font-extrabold text-gray-900 mb-4 tracking-tight">Precision Manufacturing Estimates.</h2>
                 <p className="text-lg text-gray-600 mb-10">Upload your technical drawing. Nosta AI provides an instant, non-binding cost analysis.</p>

                 <div className="bg-white rounded-3xl shadow-xl shadow-gray-200/50 border border-gray-100 p-12 text-center transition-all hover:shadow-2xl">
                    <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Upload className="w-10 h-10 text-[#1F4E79]" />
                    </div>
                    <label className="block mb-6 cursor-pointer group">
                        <input type="file" className="hidden" accept="application/pdf,image/*" onChange={handleFileUpload} />
                        <span className="block w-full py-4 px-6 bg-[#1F4E79] text-white font-bold rounded-xl shadow-lg shadow-blue-900/30 group-hover:bg-[#163a5c] transition-all transform group-active:scale-95">
                          Upload Drawing (PDF/Image)
                        </span>
                    </label>
                    <p className="text-xs text-gray-400">Supported formats: PDF, PNG, JPG. Max size 25MB.</p>
                 </div>
              </div>
           </div>
        )}

        {/* Step 2: Analyzing */}
        {step === 'analyzing' && (
           <div className="flex-1 flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
              <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mb-8 shadow-xl relative">
                 <Loader2 className="w-12 h-12 text-[#1F4E79] animate-spin" />
                 <div className="absolute inset-0 border-4 border-blue-100 rounded-full animate-ping opacity-20"></div>
              </div>
              <h3 className="text-2xl font-bold text-gray-900 mb-2">Analyzing Geometry...</h3>
              <p className="text-gray-500">Applying Nosta standard cost models and material indices.</p>
           </div>
        )}

        {/* Step 3: Review Estimate (Side-by-Side) */}
        {step === 'review' && (
           <div className="flex-1 flex flex-col lg:flex-row h-full overflow-hidden bg-gray-100">

              {/* Left: Document Preview (Collapsible on Mobile) */}
              {showPreview && (
                <div className="lg:w-1/2 bg-gray-900 border-r border-gray-800 flex flex-col relative h-[50vh] lg:h-auto transition-all">
                   <div className="h-12 bg-gray-950/50 flex items-center justify-between px-4 border-b border-white/5 backdrop-blur-sm shrink-0 z-10">
                      <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <FileText className="w-3 h-3" /> Original Source
                      </span>
                      <div className="flex items-center gap-2">
                         <button onClick={() => setZoomLevel(z => Math.max(0.5, z - 0.1))} className="p-1 text-gray-400 hover:text-white"><ZoomOut className="w-4 h-4"/></button>
                         <span className="text-xs text-gray-500 font-mono w-8 text-center">{(zoomLevel * 100).toFixed(0)}%</span>
                         <button onClick={() => setZoomLevel(z => Math.min(3, z + 0.1))} className="p-1 text-gray-400 hover:text-white"><ZoomIn className="w-4 h-4"/></button>
                         <div className="w-px h-4 bg-gray-700 mx-1"></div>
                         <button onClick={() => setShowPreview(false)} className="lg:hidden text-gray-400"><X className="w-4 h-4"/></button>
                      </div>
                   </div>
                   <div className="flex-1 overflow-auto bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] p-8 flex items-center justify-center">
                     <div style={{ transform: `scale(${zoomLevel})`, transformOrigin: 'center center', transition: 'transform 0.1s' }} className="shadow-2xl shadow-black/50">
                        {filePreview && (
                            file?.type === 'application/pdf' ? (
                            <iframe src={filePreview} className="w-[600px] h-[800px] bg-white rounded-lg" title="Preview" />
                            ) : (
                            <img src={filePreview} alt="Preview" className="max-w-full max-h-full object-contain bg-white rounded-lg" />
                            )
                        )}
                     </div>
                   </div>
                </div>
              )}

              {/* Right: Estimate Data */}
              <div className="flex-1 flex flex-col bg-gray-50 h-full overflow-hidden relative shadow-2xl z-10">

                 {/* Mobile Toggle for Preview */}
                 {!showPreview && (
                    <button 
                      onClick={() => setShowPreview(true)}
                      className="lg:hidden absolute top-4 right-4 z-10 bg-gray-900 text-white p-2 rounded-full shadow-lg"
                    >
                       <Eye className="w-4 h-4" />
                    </button>
                 )}

                 <div className="flex-1 overflow-y-auto p-4 lg:p-8">
                    <div className="max-w-3xl mx-auto space-y-6">

                       <div className="flex items-center justify-between">
                          <button onClick={() => setStep('upload')} className="text-sm text-gray-500 hover:text-gray-900 flex items-center gap-1">
                             <ChevronRight className="w-4 h-4 rotate-180" /> Re-upload
                          </button>
                          <div className="bg-blue-50 text-blue-800 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-2 border border-blue-100">
                             <ShieldCheck className="w-3 h-3" /> Data Verification Mode
                          </div>
                       </div>

                       {/* Total Cost Card */}
                       <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 flex justify-between items-center bg-gradient-to-r from-[#1F4E79] to-[#2E74B5] text-white">
                          <div>
                             <h2 className="text-lg font-bold">Estimated Production Cost</h2>
                             <p className="text-xs text-blue-100 opacity-80">Subject to engineering validation</p>
                          </div>
                          <div className="text-right">
                             <span className="text-3xl font-bold block">{formatCurrency(totalCost)}</span>
                          </div>
                       </div>

                       {/* Line Items */}
                       <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                          <div className="px-6 py-4 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center">
                             <h3 className="font-bold text-gray-800">Detected Data ({verifiedItems.size}/{rfqData.lineItems.length} Verified)</h3>
                             {allVerified && (
                                <span className="text-xs font-bold text-green-600 flex items-center gap-1 bg-green-50 px-2 py-1 rounded-md animate-in fade-in">
                                    <CheckCircle className="w-3 h-3"/> All Looks Good
                                </span>
                             )}
                          </div>
                          <div className="divide-y divide-gray-100">
                             {rfqData.lineItems.map((item) => {
                                const isVerified = verifiedItems.has(item.id);
                                return (
                                <div key={item.id} className={`p-6 transition-all border-l-4 ${isVerified ? 'bg-green-50/30 border-green-500' : 'hover:bg-gray-50 border-transparent'}`}>
                                   <div className="flex justify-between items-start mb-2">
                                      <div className="flex items-start gap-4">
                                         <div 
                                            onClick={() => toggleVerification(item.id)}
                                            className={`mt-1 w-5 h-5 rounded border cursor-pointer flex items-center justify-center transition-colors ${isVerified ? 'bg-green-500 border-green-500' : 'border-gray-300 hover:border-blue-500'}`}
                                         >
                                            {isVerified && <CheckCircle className="w-3.5 h-3.5 text-white" />}
                                         </div>
                                         <div>
                                            <h4 className={`font-bold transition-colors ${isVerified ? 'text-green-900' : 'text-gray-900'}`}>{item.description}</h4>
                                            <div className="flex items-center gap-2 mt-1">
                                                {/* Material Dropdown for Analysis */}
                                                <select 
                                                    value={item.material}
                                                    onChange={(e) => handleMaterialChange(item.id, e.target.value as MaterialType)}
                                                    className="text-xs font-mono bg-white border border-gray-200 px-1.5 py-0.5 rounded text-gray-700 outline-none cursor-pointer hover:border-blue-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-200"
                                                >
                                                    {Object.values(MaterialType).map(m => (
                                                        <option key={m} value={m}>{m}</option>
                                                    ))}
                                                </select>
                                                <div className="flex items-center gap-1 bg-white border border-gray-200 rounded px-1.5 py-0.5">
                                                    <span className="text-xs text-gray-400">Qty</span>
                                                    <input 
                                                        type="number" 
                                                        value={item.quantity}
                                                        onChange={(e) => handleQuantityChange(item.id, parseInt(e.target.value))}
                                                        className="w-10 text-xs font-mono text-center outline-none"
                                                    />
                                                </div>
                                            </div>
                                         </div>
                                      </div>
                                      <div className="text-right">
                                         <span className="font-bold text-gray-900">{formatCurrency(item.calculation.totalLineCost)}</span>
                                         <p className="text-[10px] text-gray-400">{formatCurrency(item.calculation.materialCost)} / unit</p>
                                      </div>
                                   </div>

                                   {/* Specs Grid */}
                                   <div className="grid grid-cols-3 gap-2 mt-3 text-xs pl-9">
