            {/* Editor Content */}
            <div className="flex-1 flex overflow-hidden relative">

              {editorMode === 'upload' ? (
                 <div className="w-full h-full flex items-center justify-center bg-gradient-to-b from-[#F8FAFC] to-gray-50 p-8">
