           <div className={`transition-all duration-300 ${isSidebarCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100'} overflow-hidden whitespace-nowrap`}>
             <span className="font-extrabold text-slate-900 text-lg tracking-tight block">CostAI</span>
             <span className="text-[10px] text-slate-600 font-bold tracking-wider uppercase">Enterprise</span>
