  { id: '1', name: 'Technical_Drawing_v2.pdf', size: '2.4 MB', type: 'pdf', uploadDate: '2024-10-18' },
  { id: '2', name: 'Spec_Sheet_A.pdf', size: '1.1 MB', type: 'pdf', uploadDate: '2024-10-18' },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isCustomerMode, setIsCustomerMode] = useState(false);

  // Navigation State
  const [viewMode, setViewMode] = useState<ViewMode>('dashboard');
  const [editorMode, setEditorMode] = useState<EditorMode>('upload');
  const [activeTab, setActiveTab] = useState<'items' | 'collaboration' | 'documents'>('items');
  const [itemViewMode, setItemViewMode] = useState<'list' | 'table'>('list');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // Data State
  const [pricingConfig, setPricingConfig] = useState<PricingConfig>(getPricingConfig());
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [rfqData, setRfqData] = useState<RFQData>({ 
    header: INITIAL_HEADER, 
    lineItems: [],
    comments: [],
    attachments: []
  });
  const [savedQuotes, setSavedQuotes] = useState<SavedQuote[]>(MOCK_QUOTES);
  const [currentStatus, setCurrentStatus] = useState<QuoteStatus>(QuoteStatus.DRAFT);

  // UI State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [newComment, setNewComment] = useState('');

  // Calculate total
  const totalCost = rfqData.lineItems.reduce((sum, item) => sum + item.calculation.totalLineCost, 0);

  // Auto-collapse sidebar when entering editor
  useEffect(() => {
    if (viewMode === 'editor') {
      setIsSidebarCollapsed(true);
    }
  }, [viewMode]);

  // --- Actions ---

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setIsCustomerMode(false);
  }

  const handleCustomerEnter = () => {
    setIsCustomerMode(true);
  }

  const handleBackToLogin = () => {
    setIsCustomerMode(false);
    setCurrentUser(null);
  }

  // Update configuration and recalculate current items if necessary
  const updatePricingConfig = (newConfig: PricingConfig) => {
    setPricingConfig(newConfig);
    savePricingConfig(newConfig);

    // Recalculate existing items with new prices
    if (rfqData.lineItems.length > 0) {
      setRfqData(prev => ({
        ...prev,
        lineItems: prev.lineItems.map(item => ({
          ...item,
          calculation: calculateLineItem(item.material, item.dimensions, item.quantity, newConfig)
        }))
      }));
    }
  };

  const startNewQuote = () => {
    setRfqData({ header: INITIAL_HEADER, lineItems: [], comments: [], attachments: [] });
    setFile(null);
    setFilePreview(null);
    setEditorMode('upload');
    setCurrentStatus(QuoteStatus.DRAFT);
    setViewMode('editor');
    setIsChatOpen(false);
  };

  const handleEditQuote = (id: string) => {
    const quote = savedQuotes.find(q => q.id === id);
    if (quote) {
       setRfqData({
         header: quote,
         lineItems: [], // In real app, load items
         comments: MOCK_COMMENTS, // In real app, load from ID
         attachments: MOCK_ATTACHMENTS
       });
       setCurrentStatus(quote.status);
       setEditorMode('verify');
       setViewMode('editor');
    }
  };

  const handleDownloadQuote = (id: string) => {
    const quote = savedQuotes.find(q => q.id === id);
    if (quote) {
       // Construct a temporary RFQData object for PDF generation
       const pdfData: RFQData = {
         header: quote,
         lineItems: [
            // Mock items so the PDF isn't empty for demo purposes
            {
                id: '1',
                description: 'Mock Item for Download',
                material: MaterialType.STEEL_C45,
                quantity: 10,
                unit: 'pcs',
                dimensions: { length: 100, width: 50, height: 10 },
                calculation: calculateLineItem(MaterialType.STEEL_C45, { length: 100, width: 50, height: 10 }, 10, pricingConfig)
            }
         ],
         comments: [],
         attachments: []
       };
       generateQuotePDF(pdfData);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      setFilePreview(URL.createObjectURL(selectedFile));
      setIsProcessing(true);

      try {
        const base64Data = await fileToBase64(selectedFile);
        const base64Content = base64Data.split(',')[1];

        const extracted = await extractRFQData(base64Content, selectedFile.type);

        const processedItems: LineItem[] = (extracted.lineItems || []).map((item: any, idx: number) => {
          const material = Object.values(MaterialType).includes(item.material as MaterialType) 
            ? item.material as MaterialType 
            : MaterialType.STEEL_C45;

          const dims = {
             length: item.length || 0,
             width: item.width || 0,
             height: item.height || 0
          };

          return {
            id: `item-${Date.now()}-${idx}`,
            description: item.description || `Item ${idx + 1}`,
            material,
            quantity: item.quantity || 1,
            unit: item.unit || 'ST',
            dimensions: dims,
            deliveryDate: item.deliveryDate || '',
            tolerance: item.tolerance,
            calculation: calculateLineItem(material, dims, item.quantity || 1, pricingConfig)
          };
        });

        setRfqData(prev => ({
          ...prev,
          header: {
            ...INITIAL_HEADER,
            customerName: extracted.customerName || '',
            rfqNumber: extracted.rfqNumber || '',
            documentDate: extracted.documentDate || new Date().toISOString().split('T')[0]
          },
          lineItems: processedItems,
          attachments: [...prev.attachments, {
             id: Date.now().toString(),
             name: selectedFile.name,
             size: `${(selectedFile.size / 1024 / 1024).toFixed(2)} MB`,
             type: 'pdf',
             uploadDate: new Date().toLocaleDateString()
          }]
        }));

        setEditorMode('verify');
      } catch (err) {
        console.error(err);
        alert("Failed to process document. Please try again.");
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const handleLineItemChange = useCallback((id: string, field: string, value: any) => {
    setRfqData(prev => {
      const newItems = prev.lineItems.map(item => {
        if (item.id !== id) return item;
        const updated = { ...item };

        if (field.startsWith('dimensions.')) {
          const dimKey = field.split('.')[1] as keyof typeof updated.dimensions;
          updated.dimensions = { ...updated.dimensions, [dimKey]: value };
        } else if (field === 'material') {
           updated.material = value as MaterialType;
        } else if (field === 'quantity') {
           updated.quantity = value;
        } else {
          (updated as any)[field] = value;
        }

        updated.calculation = calculateLineItem(updated.material, updated.dimensions, updated.quantity, pricingConfig);
        return updated;
      });
      return { ...prev, lineItems: newItems };
    });
  }, [pricingConfig]);

  const handleDeleteItem = (id: string) => {
    setRfqData(prev => ({
      ...prev,
      lineItems: prev.lineItems.filter(item => item.id !== id)
    }));
  };

  const handleAddManualItem = () => {
    const newItem: LineItem = {
      id: `manual-${Date.now()}`,
      description: 'New Manual Item',
      material: MaterialType.STEEL_C45,
      quantity: 1,
      unit: 'ST',
      dimensions: { length: 0, width: 0, height: 0 },
      calculation: calculateLineItem(MaterialType.STEEL_C45, { length: 0, width: 0, height: 0 }, 1, pricingConfig)
    };
    setRfqData(prev => ({ ...prev, lineItems: [...prev.lineItems, newItem] }));
    if (editorMode === 'upload') setEditorMode('verify');
  };

  const handleSaveQuote = (header: typeof INITIAL_HEADER) => {
    const newQuote: SavedQuote = {
      ...header,
      id: `q-${Date.now()}`,
      status: currentStatus,
      totalValue: totalCost,
      lastModified: new Date().toISOString()
    };
    setSavedQuotes(prev => [newQuote, ...prev]);
    setIsModalOpen(false);
    setViewMode('dashboard');
  };

  const handleExportPDF = () => {
    generateQuotePDF(rfqData);
  };

  const advanceWorkflow = () => {
     if (currentStatus === QuoteStatus.DRAFT) setCurrentStatus(QuoteStatus.REVIEW);
     else if (currentStatus === QuoteStatus.REVIEW) setCurrentStatus(QuoteStatus.APPROVED);
     else if (currentStatus === QuoteStatus.APPROVED) setCurrentStatus(QuoteStatus.SENT);
  };

  const addComment = () => {
    if (!newComment.trim() || !currentUser) return;

    // Add User Comment
    setRfqData(prev => ({
      ...prev,
      comments: [...prev.comments, {
        id: Date.now().toString(),
        author: currentUser.name,
        text: newComment,
        timestamp: new Date().toLocaleString(),
        type: 'internal',
        role: currentUser.role
      }]
    }));
    setNewComment('');

    // Simulate Supplier Reply after delay (demo purposes)
    if (Math.random() > 0.5) {
      setTimeout(() => {
        setRfqData(prev => ({
          ...prev,
          comments: [...prev.comments, {
            id: (Date.now() + 1).toString(),
            author: 'Supplier Rep (System)',
            text: 'We have received your note and will update the quote shortly.',
            timestamp: new Date().toLocaleString(),
            type: 'supplier',
            role: 'supplier'
          }]
        }));
      }, 3000);
    }
  };

  const NavigationButton = ({ mode, icon: Icon, label }: { mode: ViewMode, icon: any, label: string }) => {
    const isActive = viewMode === mode;
    return (
      <button 
        onClick={() => {
           if (mode === 'editor' && editorMode === 'upload' && rfqData.lineItems.length > 0) setEditorMode('verify');
           setViewMode(mode);
        }}
        className={`w-full flex items-center relative py-3 px-3.5 rounded-xl transition-all duration-200 group ${
          isActive 
            ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' 
            : 'text-gray-900 hover:bg-slate-50 hover:text-black'
        }`}
      >
        <Icon className={`w-5 h-5 shrink-0 transition-transform group-hover:scale-110 ${isActive ? 'text-white' : 'text-gray-600 group-hover:text-blue-600'}`} />
        <span className={`ml-3 font-bold text-sm whitespace-nowrap overflow-hidden transition-all duration-300 ${isSidebarCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100'}`}>
          {label}
        </span>

        {/* Floating Tooltip for Collapsed State */}
        {isSidebarCollapsed && (
          <div className="absolute left-full ml-4 px-3 py-1.5 bg-gray-900 text-white text-xs font-medium rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none whitespace-nowrap z-50 shadow-xl border border-white/10">
             {label}
             {/* Arrow */}
             <div className="absolute top-1/2 -left-1 -translate-y-1/2 border-4 border-transparent border-r-gray-900"></div>
          </div>
        )}
      </button>
    );
  };

  // --- Render ---

  // 1. Customer Mode
  if (isCustomerMode) {
     return <CustomerPortal config={pricingConfig} onBackToLogin={handleBackToLogin} />;
  }

  // 2. Login Screen
  if (!currentUser) {
     return <Login onLogin={handleLogin} onCustomerEnter={handleCustomerEnter} />;
  }

  // 3. Employee Dashboard
  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans overflow-hidden selection:bg-blue-100 selection:text-blue-900">

      {/* Modern Sidebar - White Matte Theme */}
      <aside className={`${isSidebarCollapsed ? 'w-[88px]' : 'w-[280px]'} bg-white flex flex-col shrink-0 z-30 transition-all duration-300 ease-[cubic-bezier(0.25,0.1,0.25,1.0)] relative border-r border-slate-200`}>

        {/* Toggle Button */}
        <button 
          onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
          className="absolute -right-3 top-9 bg-white border border-gray-200 text-gray-900 hover:text-blue-600 rounded-full p-1.5 shadow-lg z-50 transition-all hover:scale-110"
        >
           <ChevronLeft size={14} className={`transition-transform duration-300 ${isSidebarCollapsed ? 'rotate-180' : ''}`} />
        </button>

        {/* Subtle texture or gradient overlay */}
        <div className="absolute top-0 left-0 w-full h-96 bg-gradient-to-b from-slate-50/80 to-transparent pointer-events-none"></div>

        <div className="h-24 flex items-center px-6 relative z-10 overflow-hidden">
           <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20 ring-1 ring-black/5 shrink-0 mr-3">
             <Calculator className="w-5 h-5 text-white" />
           </div>
           <div className={`transition-all duration-300 ${isSidebarCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100'} overflow-hidden whitespace-nowrap`}>
             <span className="font-extrabold text-black text-lg tracking-tight block">CostAI</span>
             <span className="text-[10px] text-gray-900 font-bold tracking-wider uppercase">Enterprise</span>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-4 overflow-y-auto py-4 scrollbar-none relative z-10">
          <div>
            <div className={`px-4 mb-3 transition-all duration-300 overflow-hidden ${isSidebarCollapsed ? 'h-0 opacity-0 mb-0' : 'h-auto opacity-100'}`}>
               <span className="text-[10px] font-extrabold text-black uppercase tracking-widest">Platform</span>
            </div>
            {isSidebarCollapsed && <div className="h-px bg-slate-100 mx-2 mb-4"></div>}
            <div className="space-y-1">
              <NavigationButton mode="dashboard" icon={LayoutDashboard} label="Dashboard" />
              <NavigationButton mode="editor" icon={FileText} label="Active Quote" />
              <NavigationButton mode="rfq_flow" icon={LayoutList} label="RFQ List" />
            </div>
          </div>

          <div>
            <div className={`px-4 mb-3 mt-6 transition-all duration-300 overflow-hidden ${isSidebarCollapsed ? 'h-0 opacity-0 mt-2 mb-0' : 'h-auto opacity-100'}`}>
               <span className="text-[10px] font-extrabold text-black uppercase tracking-widest">Intelligence</span>
            </div>
            {isSidebarCollapsed && <div className="h-px bg-slate-100 mx-2 my-4"></div>}
            <div className="space-y-1">
              <NavigationButton mode="analytics" icon={BarChart2} label="Analytics" />
              <NavigationButton mode="demand_intelligence" icon={Radar} label="Demand Intel" />
            </div>
          </div>

          <div>
             <div className={`px-4 mb-3 mt-6 transition-all duration-300 overflow-hidden ${isSidebarCollapsed ? 'h-0 opacity-0 mt-2 mb-0' : 'h-auto opacity-100'}`}>
               <span className="text-[10px] font-extrabold text-black uppercase tracking-widest">Management</span>
            </div>
            {isSidebarCollapsed && <div className="h-px bg-slate-100 mx-2 my-4"></div>}
            <div className="space-y-1">
              {currentUser.role === 'admin' && (
                <NavigationButton mode="team" icon={Users} label="Team" />
              )}
              <NavigationButton mode="suppliers" icon={Users} label="Suppliers" />
              <NavigationButton mode="settings" icon={SettingsIcon} label="Settings" />
            </div>
          </div>
        </nav>

        <div className="p-4 border-t border-slate-100 bg-white relative z-10 overflow-hidden">
          <div className="flex items-center group cursor-pointer p-2 rounded-xl hover:bg-slate-50 transition-colors">
             <div className="w-10 h-10 rounded-full p-[2px] bg-gradient-to-r from-blue-500 to-purple-500 shrink-0">
               <div className="w-full h-full rounded-full bg-white flex items-center justify-center border-2 border-white">
                  <span className="text-slate-900 text-xs font-bold">{currentUser.name.substring(0,2).toUpperCase()}</span>
               </div>
             </div>

             <div className={`ml-3 overflow-hidden transition-all duration-300 ${isSidebarCollapsed ? 'w-0 opacity-0' : 'w-32 opacity-100'}`}>
                <p className="text-sm font-bold text-gray-900 group-hover:text-blue-600 transition-colors truncate">{currentUser.name}</p>
                <div className="flex items-center gap-1">
                  {currentUser.role === 'admin' && <Shield className="w-3 h-3 text-purple-600" />}
                  <p className="text-xs text-gray-700 truncate capitalize font-bold">{currentUser.role}</p>
                </div>
             </div>

             <div className={`transition-all duration-300 ${isSidebarCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100 ml-auto'}`}>
               <button onClick={handleLogout} className="text-gray-600 hover:text-red-600 transition-colors p-1.5 rounded-lg hover:bg-red-50" title="Sign Out">
                  <LogOut className="w-4 h-4" />
               </button>
             </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-[#F8FAFC]">

        {viewMode === 'dashboard' && (
          <Dashboard 
            quotes={savedQuotes} 
            onNewQuote={startNewQuote}
            onEditQuote={handleEditQuote}
            onDownload={handleDownloadQuote}
          />
        )}

        {viewMode === 'rfq_flow' && <RFQStatusFlow />}

        {viewMode === 'suppliers' && <Suppliers />}

        {viewMode === 'analytics' && <Analytics />}

        {viewMode === 'demand_intelligence' && <DemandIntelligence />}

        {viewMode === 'team' && currentUser.role === 'admin' && <TeamManagement />}

        {viewMode === 'settings' && (
          <Settings 
            config={pricingConfig}
            currentUser={currentUser}
            onUpdateConfig={updatePricingConfig}
            onOpenCustomerPortal={() => {
                setCurrentUser(null); // Should logically be handled by logout first but fine for demo
                setIsCustomerMode(true);
            }}
          />
        )}

        {viewMode === 'editor' && (
          <div className="flex-1 flex flex-col h-full relative animate-in fade-in duration-300">

            {/* Glassmorphism Header */}
            <header className="sticky top-0 z-10 bg-white/80 backdrop-blur-xl border-b border-gray-200/60 shrink-0 transition-all">
               <div className="flex items-center justify-between px-8 h-20">
                  <div className="flex items-center gap-6">
                    <button onClick={() => setViewMode('dashboard')} className="hover:bg-gray-100 p-2.5 rounded-xl transition-colors text-gray-900 group">
                      <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
                    </button>
                    <div className="h-8 w-px bg-gray-200"></div>
                    <div>
                      <h2 className="font-extrabold text-gray-900 text-xl leading-tight tracking-tight">
                        {rfqData.header.rfqNumber || 'New Cost Estimate'}
                      </h2>
                      <p className="text-xs font-bold text-gray-900 mt-0.5">{rfqData.header.customerName || 'Draft Quote'}</p>
                    </div>
                  </div>

                  {/* Modern Workflow Stepper */}
                  {editorMode === 'verify' && (
                     <div className="hidden lg:flex items-center bg-gray-100/50 p-1.5 rounded-full border border-gray-200/50">
                        {[QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].map((step, idx) => {
                           const isActive = step === currentStatus;
                           const isPast = [QuoteStatus.DRAFT, QuoteStatus.REVIEW, QuoteStatus.APPROVED, QuoteStatus.SENT].indexOf(currentStatus) > idx;
                           return (
                              <div key={step} className="flex items-center">
                                 <div className={`flex items-center gap-2 px-5 py-2 rounded-full text-xs font-bold transition-all duration-300 ${
                                    isActive ? 'bg-white text-blue-700 shadow-sm ring-1 ring-black/5' : 
                                    isPast ? 'text-green-600' : 'text-gray-500'
                                 }`}>
                                    {isPast && <CheckCircle className="w-3.5 h-3.5" />}
                                    {isActive && <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />}
                                    {step}
                                 </div>
                              </div>
                           );
                        })}
                     </div>
                  )}

                  <div className="flex items-center gap-4">
                     <button 
                       onClick={handleExportPDF}
                       className="p-2.5 text-gray-900 hover:text-blue-600 hover:bg-blue-50 rounded-xl relative transition-all"
                       title="Export PDF"
                     >
                        <FileDown className="w-5 h-5" />
                     </button>
                     <div className="h-8 w-px bg-gray-200"></div>
                     <button 
                       onClick={() => setIsChatOpen(!isChatOpen)}
                       className={`flex items-center gap-2.5 px-5 py-2.5 rounded-xl text-sm font-bold transition-all duration-200 ${isChatOpen ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30 ring-2 ring-blue-600 ring-offset-2' : 'bg-white border border-gray-200 text-gray-900 hover:border-gray-300 hover:shadow-sm'}`}
                     >
                       <Bot className="w-4 h-4" /> {isChatOpen ? 'Copilot Active' : 'AI Copilot'}
                     </button>
                  </div>
               </div>

               {/* Sleek Tabs */}
               {editorMode === 'verify' && (
                  <div className="px-8 flex gap-8 border-t border-gray-100 bg-white/50 backdrop-blur-sm">
                     {[
                        { id: 'items', label: 'Line Items', count: rfqData.lineItems.length },
                        { id: 'collaboration', label: 'Collaboration', count: rfqData.comments.length },
                        { id: 'documents', label: 'Documents', count: rfqData.attachments.length }
                     ].map((tab) => (
                       <button 
                          key={tab.id}
                          onClick={() => setActiveTab(tab.id as any)}
                          className={`relative py-4 text-sm font-bold transition-all flex items-center gap-2.5 ${activeTab === tab.id ? 'text-blue-600' : 'text-gray-900 hover:text-black'}`}
                       >
                          {tab.label}
                          {tab.count > 0 && (
                            <span className={`px-2 py-0.5 rounded-md text-[10px] font-extrabold ${activeTab === tab.id ? 'bg-blue-100 text-blue-700' : 'bg-gray-200 text-gray-900'}`}>
                              {tab.count}
                            </span>
                          )}
                          {activeTab === tab.id && (
                             <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-t-full layout-id-underline shadow-[0_-2px_10px_rgba(37,99,235,0.5)]"></span>
                          )}
                       </button>
                     ))}
                  </div>
               )}
            </header>

            {/* Editor Content */}
            <div className="flex-1 flex overflow-hidden relative">

              {editorMode === 'upload' ? (
                 <div className="w-full h-full flex items-center justify-center bg-gradient-to-b from-[#F8FAFC] to-gray-50 p-8">
                    <div className="max-w-xl w-full bg-white/80 backdrop-blur-sm rounded-[2rem] shadow-2xl shadow-blue-900/5 p-12 border border-white/20 text-center hover:shadow-3xl transition-shadow duration-500 ring-1 ring-black/5">
                        <div className="w-24 h-24 bg-gradient-to-tr from-blue-50 to-indigo-50 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner ring-1 ring-black/5">
                          <Upload className="w-10 h-10 text-blue-600" />
                        </div>
                        <h3 className="text-3xl font-extrabold text-gray-900 mb-3 tracking-tight">Upload RFQ Document</h3>
                        <p className="text-gray-900 mb-10 leading-relaxed text-lg">Drag and drop your engineering drawings (PDF/Images) here. Our AI will extract specs, materials, and quantities instantly.</p>

                        <div className="flex flex-col gap-4">
                          <label className="relative group">
                            <input 
                              type="file" 
                              accept="image/*,application/pdf"
                              onChange={handleFileUpload}
                              className="hidden"
                              disabled={isProcessing}
                            />
                            <span className={`w-full block cursor-pointer px-8 py-5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-blue-500/30 hover:shadow-blue-500/50 hover:-translate-y-0.5 transition-all ${isProcessing ? 'opacity-75' : ''}`}>
                              {isProcessing ? (
                                <span className="flex items-center justify-center gap-3"><div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"/> Processing...</span>
                              ) : 'Select Document'}
                            </span>
                          </label>
                          <button onClick={handleAddManualItem} className="w-full px-8 py-5 bg-white text-gray-900 font-bold rounded-2xl border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-colors shadow-sm">
                            Continue without File
                          </button>
                        </div>
                    </div>
                 </div>
              ) : (
                <>
                  {/* Document Preview Panel */}
                  <div className="hidden lg:flex w-[40%] bg-[#0B1120] border-r border-gray-800 flex-col min-w-[400px] shadow-2xl z-10">
                    <div className="h-16 bg-[#0F172A]/80 backdrop-blur-md flex items-center justify-between px-6 border-b border-white/5">
                       <span className="text-xs font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
                         <FileText className="w-4 h-4 text-blue-500" /> Source Preview
                       </span>
                       <div className="flex gap-2">
                          <button className="p-2 text-gray-400 hover:text-white rounded-lg hover:bg-white/10 transition-colors"><Download className="w-4 h-4" /></button>
                       </div>
                    </div>
                    <div className="flex-1 overflow-auto flex items-center justify-center p-8 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
                      <div className="relative shadow-2xl shadow-black/80 rounded-xl overflow-hidden transition-transform hover:scale-[1.01] duration-300 ring-1 ring-white/10">
                        {file?.type === 'application/pdf' ? (
                          <iframe src={filePreview || ''} className="w-full h-[800px] bg-white" title="PDF Preview" />
                        ) : (
                          <img src={filePreview || ''} alt="RFQ Document" className="max-w-full max-h-[80vh] object-contain bg-white" />
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Form & Workspace */}
                  <div className="flex-1 flex flex-col bg-white min-w-[400px]">

                    {/* Items View */}
                    {activeTab === 'items' && (
                       <>
                        {/* Quote Details Bar */}
                        <div className="px-10 py-8 border-b border-gray-100 bg-white">
                           <div className="grid grid-cols-2 gap-12">
                              <div className="group relative">
                                 <label className="absolute -top-2.5 left-4 bg-white px-2 text-[11px] font-bold text-gray-900 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">Customer Name</label>
                                 <input 
                                    value={rfqData.header.customerName}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, customerName: e.target.value}}))}
                                    className="w-full text-xl font-bold text-gray-900 border border-gray-300 rounded-xl px-6 py-4 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all placeholder-gray-400 bg-white" 
                                    placeholder="Enter Client Name"
                                 />
                              </div>
                              <div className="group relative">
                                 <label className="absolute -top-2.5 left-4 bg-white px-2 text-[11px] font-bold text-gray-900 uppercase tracking-wider group-focus-within:text-blue-600 transition-colors">RFQ Reference</label>
                                 <input 
                                    value={rfqData.header.rfqNumber}
                                    onChange={(e) => setRfqData(prev => ({...prev, header: {...prev.header, rfqNumber: e.target.value}}))}
                                    className="w-full text-xl font-mono font-medium text-gray-900 border border-gray-300 rounded-xl px-6 py-4 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all placeholder-gray-400 bg-white" 
                                    placeholder="RFQ-0000"
                                 />
                              </div>
                           </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-10 bg-gray-50/50 space-y-6">
                           <div className="flex justify-between items-end mb-2">
                              <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider pl-1 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-blue-500"></span> Line Items
                              </h3>
                              <div className="flex gap-4 items-center">
                                {/* View Toggle */}
                                <div className="bg-white border border-gray-200 rounded-xl p-1 flex shadow-sm">
                                  <button 
                                    onClick={() => setItemViewMode('list')}
                                    className={`p-2 rounded-lg transition-all ${itemViewMode === 'list' ? 'bg-gray-100 text-blue-600 shadow-sm' : 'text-gray-900 hover:text-black'}`}
                                  >
                                    <LayoutList className="w-4 h-4" />
                                  </button>
                                  <button 
                                    onClick={() => setItemViewMode('table')}
                                    className={`p-2 rounded-lg transition-all ${itemViewMode === 'table' ? 'bg-gray-100 text-blue-600 shadow-sm' : 'text-gray-900 hover:text-black'}`}
                                  >
                                    <TableIcon className="w-4 h-4" />
                                  </button>
                                </div>
                                <div className="h-6 w-px bg-gray-200"></div>
                                <button onClick={handleAddManualItem} className="text-sm text-blue-600 hover:text-blue-800 font-bold flex items-center gap-1.5 hover:underline decoration-2 underline-offset-2">
                                   <Plus className="w-4 h-4" /> Add Item manually
                                </button>
                              </div>
                           </div>

                           {/* View Mode Rendering */}
                           {itemViewMode === 'list' ? (
                             rfqData.lineItems.map((item, index) => (
                                <LineItemCard 
                                  key={item.id} 
                                  item={item} 
                                  index={index} 
                                  onChange={handleLineItemChange} 
                                />
                             ))
                           ) : (
                             <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-sm">
                               <table className="w-full text-left text-sm">
                                 <thead className="bg-gray-50 border-b border-gray-100 text-gray-900 font-bold uppercase text-[11px] tracking-wider">
                                   <tr>
                                     <th className="px-6 py-4 w-16 text-center">#</th>
                                     <th className="px-6 py-4">Description</th>
                                     <th className="px-6 py-4 w-40">Material</th>
                                     <th className="px-6 py-4 w-28 text-center">Qty</th>
                                     <th className="px-6 py-4 w-48">Dims (L x W x H)</th>
                                     <th className="px-6 py-4 w-28 text-right">Unit Price</th>
                                     <th className="px-6 py-4 w-32 text-right">Total</th>
                                     <th className="px-6 py-4 w-16"></th>
                                   </tr>
                                 </thead>
                                 <tbody className="divide-y divide-gray-50">
                                   {rfqData.lineItems.map((item, index) => (
                                     <tr key={item.id} className="hover:bg-blue-50/20 transition-colors">
                                       <td className="px-6 py-4 text-center text-gray-900 font-medium">{index + 1}</td>
                                       <td className="px-6 py-4">
                                         <input 
                                           className="w-full bg-white border border-gray-200 rounded px-2 py-1 focus:border-blue-500 outline-none font-medium text-gray-900"
                                           value={item.description}
                                           onChange={(e) => handleLineItemChange(item.id, 'description', e.target.value)}
                                         />
                                       </td>
                                       <td className="px-6 py-4">
                                         <select 
                                            value={item.material}
                                            onChange={(e) => handleLineItemChange(item.id, 'material', e.target.value)}
                                            className="w-full bg-white text-xs border border-gray-200 rounded px-2 py-1 focus:border-blue-500 outline-none font-mono text-gray-900"
                                         >
                                            {Object.values(MaterialType).map(m => (
                                              <option key={m} value={m}>{m}</option>
                                            ))}
                                         </select>
                                       </td>
                                       <td className="px-6 py-4">
                                         <input 
                                            type="number"
                                            className="w-full text-center bg-white border border-gray-200 rounded px-2 py-1 focus:border-blue-500 outline-none font-medium text-gray-900"
                                            value={item.quantity}
                                            onChange={(e) => handleLineItemChange(item.id, 'quantity', parseInt(e.target.value) || 0)}
                                         />
                                       </td>
                                       <td className="px-6 py-4">
                                          <div className="flex gap-2 justify-center">
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-white rounded-md border border-gray-200 text-xs py-1 font-mono text-gray-900 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.length}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.length', parseFloat(e.target.value) || 0)}
                                            />
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-white rounded-md border border-gray-200 text-xs py-1 font-mono text-gray-900 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.width}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.width', parseFloat(e.target.value) || 0)}
                                            />
                                            <input 
                                              type="number"
                                              className="w-full text-center bg-white rounded-md border border-gray-200 text-xs py-1 font-mono text-gray-900 focus:ring-2 focus:ring-blue-500/20"
                                              value={item.dimensions.height}
                                              onChange={(e) => handleLineItemChange(item.id, 'dimensions.height', parseFloat(e.target.value) || 0)}
                                            />
                                          </div>
                                       </td>
                                       <td className="px-6 py-4 text-right font-mono text-gray-900 text-sm">
                                         {formatCurrency(item.calculation.materialCost)}
                                       </td>
                                       <td className="px-6 py-4 text-right font-mono font-bold text-gray-900 text-sm">
                                         {formatCurrency(item.calculation.totalLineCost)}
                                       </td>
                                       <td className="px-6 py-4 text-right">
                                          <button onClick={() => handleDeleteItem(item.id)} className="text-gray-400 hover:text-red-500 transition-colors p-1 hover:bg-red-50 rounded">
                                            <Trash2 className="w-4 h-4" />
                                          </button>
                                       </td>
                                     </tr>
                                   ))}
                                 </tbody>
                               </table>
                             </div>
                           )}

                           <div className="h-24"></div> {/* Spacer */}
                        </div>

                        {/* Sticky Footer */}
                        <div className="px-10 py-6 border-t border-gray-200 bg-white shadow-[0_-10px_40px_-5px_rgba(0,0,0,0.1)] z-20">
                           <div className="flex items-center justify-between">
                              <div>
                                 <p className="text-[11px] text-gray-900 font-bold uppercase tracking-wider mb-1">Total Estimate</p>
                                 <p className="text-4xl font-extrabold text-slate-900 tracking-tight">{formatCurrency(totalCost)}</p>
                              </div>
                              <div className="flex gap-4">
                                 <button 
                                   onClick={handleExportPDF}
                                   className="px-6 py-3.5 bg-white border border-gray-200 text-gray-900 hover:bg-gray-50 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm hover:shadow-md"
                                 >
                                    <FileText className="w-4 h-4" /> Save PDF
                                 </button>
                                 <button 
                                 onClick={advanceWorkflow}
                                 disabled={currentStatus === QuoteStatus.SENT}
                                 className="px-6 py-3.5 bg-gray-100 text-gray-900 hover:bg-gray-200 rounded-xl font-bold disabled:opacity-50 transition-colors"
                                 >
                                    {currentStatus === QuoteStatus.SENT ? 'Locked' : 'Approve Stage'}
                                 </button>
                                 <button 
                                 onClick={() => setIsModalOpen(true)}
                                 className="px-8 py-3.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl font-bold hover:shadow-lg hover:shadow-blue-500/30 transition-all hover:-translate-y-0.5 active:translate-y-0 flex items-center gap-2"
                                 >
                                 <Save className="w-4 h-4" /> Save Quote
                                 </button>
                              </div>
                           </div>
                        </div>
                       </>
                    )}

                    {/* Collaboration View */}
                    {activeTab === 'collaboration' && (
                       <div className="flex-1 flex flex-col bg-gray-50 p-8">
                          <div className="flex-1 overflow-y-auto space-y-6 mb-4 px-4">
                             {rfqData.comments.length === 0 && (
                                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4">
                                  <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center">
                                    <MessageSquare className="w-10 h-10 text-gray-300" />
                                  </div>
                                  <p className="font-medium">No messages yet. Start the conversation.</p>
                                </div>
                             )}
                             {rfqData.comments.map(comment => {
                                const isMe = comment.author === currentUser?.name;
                                const isInternal = comment.type === 'internal';

                                return (
                                <div key={comment.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                   <div className={`max-w-[80%] rounded-[1.5rem] p-6 shadow-sm ${
                                      isMe 
                                        ? 'bg-blue-600 text-white rounded-br-sm' 
                                        : !isInternal 
                                          ? 'bg-amber-50 border border-amber-200 text-gray-800 rounded-bl-sm' // Supplier style
                                          : 'bg-white border border-gray-100 text-gray-800 rounded-bl-sm' // Standard colleague
                                   }`}>
                                      <div className="flex justify-between items-center mb-2 gap-8">
                                         <div className="flex items-center gap-2">
                                           <span className={`font-bold text-xs ${isMe ? 'text-blue-100' : 'text-gray-900'}`}>{comment.author}</span>
                                           {comment.role && !isMe && (
                                              <span className={`text-[10px] px-1.5 py-0.5 rounded uppercase font-bold ${
                                                comment.role === 'admin' ? 'bg-purple-100 text-purple-700' : 
                                                comment.role === 'supplier' ? 'bg-amber-100 text-amber-700' : 
                                                'bg-gray-100 text-gray-500'
                                              }`}>
                                                {comment.role}
                                              </span>
                                           )}
                                         </div>
                                         <span className={`text-[10px] ${isMe ? 'text-blue-200' : 'text-gray-400'}`}>{comment.timestamp}</span>
                                      </div>
                                      <p className="text-sm leading-relaxed">{comment.text}</p>
                                   </div>
                                </div>
                             )})}
                          </div>
                          <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-xl shadow-gray-200/50 flex gap-3 items-end">
                             <div className="p-3 text-gray-400 hover:text-gray-600 cursor-pointer hover:bg-gray-50 rounded-xl transition-colors">
                                <Paperclip className="w-5 h-5" />
                             </div>
                             <textarea 
                                value={newComment}
                                onChange={(e) => setNewComment(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && addComment()}
                                placeholder={`Reply as ${currentUser.name}...`}
                                className="flex-1 outline-none text-sm resize-none max-h-32 py-3 px-2"
                                rows={1}
                             />
                             <button 
                              onClick={addComment} 
                              className="bg-blue-600 text-white p-3 rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-500/30"
                             >
                               <Send className="w-4 h-4" />
                             </button>
                          </div>
                       </div>
                    )}

                    {/* Documents View */}
                    {activeTab === 'documents' && (
                       <div className="flex-1 bg-gray-50 p-10">
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                             {rfqData.attachments.map(file => (
                                <div key={file.id} className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm hover:shadow-xl hover:border-blue-200 transition-all group cursor-pointer relative overflow-hidden">
                                   <div className="absolute top-0 left-0 w-1.5 h-full bg-blue-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                   <div className="flex items-start justify-between mb-6">
                                      <div className="p-4 bg-red-50 text-red-600 rounded-2xl">
                                         <FileText className="w-8 h-8" />
                                      </div>
                                      <button className="text-gray-400 hover:text-blue-600 transition-colors p-2 hover:bg-gray-50 rounded-lg"><Download className="w-5 h-5" /></button>
                                   </div>
                                   <p className="font-bold text-gray-900 text-base truncate mb-2" title={file.name}>{file.name}</p>
                                   <p className="text-xs text-gray-500 flex items-center gap-2 font-medium">
                                     <span>{file.size}</span>
                                     <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                     <span>{file.uploadDate}</span>
                                   </p>
                                </div>
                             ))}
                             <div className="border-2 border-dashed border-gray-300 rounded-2xl flex flex-col items-center justify-center p-10 text-gray-400 hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50/50 transition-all cursor-pointer bg-white/50 group min-h-[200px]">
                                <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center mb-4 group-hover:bg-blue-100 transition-colors">
                                  <Plus className="w-6 h-6" />
                                </div>
                                <span className="text-sm font-bold">Add Document</span>
                                <span className="text-xs text-gray-400 mt-1">PDF, Excel, Images</span>
                             </div>
                          </div>
                       </div>
                    )}

                  </div>
                </>
              )}

              {/* Overlay AI Panel */}
              {isChatOpen && editorMode === 'verify' && (
                <ChatPanel rfqData={rfqData} onClose={() => setIsChatOpen(false)} />
              )}
            </div>
          </div>
        )}
      </div>

      <SaveQuoteModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveQuote}
        initialHeader={rfqData.header}
        totalCost={formatCurrency(totalCost)}
      />
    </div>
  );
};

export default App;
